window.QUIZ={"course":{"code":"CS498","key":"cs498.quiz.v1","prof":"★ her own question","who":"her","sub":"A–D and Yes/No · one chapter per lecture · progress saved in this browser","exams":[{"name":"Midterm","date":"2026-11-16","when":"week 8 · 16–20.11.2026","scope":"Foster ch. 1–3, no GANs · lectures 1–7 · includes a calculation: encoder/decoder/VAE tables + filters"},{"name":"Quiz 1","date":"2026-10-26","when":"Mon 26.10.2026 (done)","scope":"A–D and Yes/No · autoencoders + lectures 1–4"},{"name":"Quiz 2","date":"2026-12-14","when":"Mon 14.12.2026","scope":"GenAI business applications"}]},"built":"2026-11-15","chapters":[{"id":"ae","title":"Autoencoders (Foster ch. 3)","short":"Autoencoders","exam":"Midterm","date":"2026-11-16","w":1.2,"topics":["Encoder–decoder idea","Fashion-MNIST & preprocessing","Encoder & decoder layers","Parameter counts","Conv2DTranspose","Loss & training","Latent space & reconstruction","Generation problems → VAE"],"n":51},{"id":"l01","title":"Lecture 1 · Course Introduction","short":"L1 Intro","exam":"Midterm","date":"2026-11-16","w":0.6,"topics":["Course objectives","Assessment & books","Week-preview figures"],"n":13},{"id":"l02","title":"Lecture 2 · Generative Modeling","short":"L2 Generative","exam":"Midterm","date":"2026-11-16","w":1.0,"topics":["Generative vs discriminative","Framework & desirable properties","Representation learning","Sample space, density & parametric models","Likelihood & MLE","Model taxonomy","Codebase"],"n":77},{"id":"l04","title":"Lecture 3 · Multilayer Perceptron","short":"L3 MLP","exam":"Midterm","date":"2026-11-16","w":1.0,"topics":["Unstructured data & deep learning","Neural networks & hidden layers","Supervised learning & data prep","Keras layers & model building","Activation functions","Parameter counts","Loss functions & optimizers","Training & evaluation"],"n":98},{"id":"l05","title":"Lecture 4 · Convolutional Neural Network","short":"L4 CNN","exam":"Midterm","date":"2026-11-16","w":1.0,"topics":["Convolution & filters","Stride & padding","Shapes & parameter counts","Batch normalization","Dropout & overfitting","Full CNN & results"],"n":77},{"id":"l06","title":"Lecture 5 · Autoencoder","short":"L5 AE","exam":"Midterm","date":"2026-11-16","w":1.3,"topics":["Latent space","Encoder & decoder shapes","Conv2DTranspose","Loss functions","Parameter counts"],"n":21},{"id":"l07","title":"Lecture 6 · VAE Introduction","short":"L6 VAE","exam":"Midterm","date":"2026-11-16","w":1.4,"topics":["Encoder & sampling","KL divergence","Training & β","VAE calculations"],"n":23},{"id":"l08","title":"Lecture 7 · VAE Latent Space (CelebA)","short":"L7 VAE faces","exam":"Midterm","date":"2026-11-16","w":1.3,"topics":["Faces VAE setup","Faces VAE tables","Latent arithmetic & morphing"],"n":18},{"id":"l03","title":"Lecture 2 Additional · GenAI in the Enterprise","short":"L2+ Enterprise","exam":"Quiz 2","date":"2026-12-14","w":0.5,"topics":["AI nesting & five approaches","Pilot lifecycle & prioritisation","Use-case lifecycle","Six pillars & principles","Assistant levels & BHT results","RAG & Copilot flow","Platforms & business case"],"n":30}],"questions":[{"id":"ae-001","chapter":"ae","topic":"Encoder–decoder idea","type":"mcq","q":"An autoencoder is trained so that…","options":["its output is as close as possible to its own input","a discriminator cannot tell its outputs from real images","its output matches the class label of the input","its latent vectors follow a standard normal distribution"],"answer":0,"fixed":false,"why":"Foster p. 62: trained to encode and decode an item so the output is as close to the original as possible. 'Standard normal latents' describes the VAE's KL term; 'fool a discriminator' is a GAN.","source":"Foster p. 62","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-002","chapter":"ae","topic":"Encoder–decoder idea","type":"mcq","q":"What does the encoder of an autoencoder do?","options":["Decompresses an embedding vector back into an image","Compresses high-dimensional input such as an image into a lower-dimensional embedding vector","Assigns each image a class label","Adds random noise to the image before training"],"answer":1,"fixed":false,"why":"Foster p. 63: the encoder compresses; decompressing an embedding back to the original domain is the decoder's job.","source":"Foster p. 63","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-003","chapter":"ae","topic":"Encoder–decoder idea","type":"yn","q":"In Foster's wardrobe story, does Brian (the stylist who sews items from a location) play the role of the encoder?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Brian is the decoder (location → item); you, placing clothes in the wardrobe, are the encoder.","source":"Foster p. 61","study":"book/B03-variational-autoencoders.md — 1. Introduction — Brian, the Stitch and the Wardrobe","origin":"practice"},{"id":"ae-004","chapter":"ae","topic":"Encoder–decoder idea","type":"mcq","q":"What is the embedding z?","options":["The reconstructed output image","The one-hot label of the image","A compression of the original image into a lower-dimensional latent space","The set of convolutional filter weights"],"answer":2,"fixed":false,"why":"Foster p. 63: the embedding is a compression of the image into the latent space; the reconstruction is what the decoder outputs from it.","source":"Foster p. 63","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-005","chapter":"ae","topic":"Encoder–decoder idea","type":"yn","q":"Can an autoencoder be used as a generative model because any point in the latent space — including points that are not embeddings of training items — can be decoded?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Foster p. 62, nearly verbatim: 'Crucially, it can be used as a generative model…' (how WELL it generates is a separate question, see §2.5).","source":"Foster p. 62","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-006","chapter":"ae","topic":"Fashion-MNIST & preprocessing","type":"mcq","q":"What are Fashion-MNIST images out of the box?","options":["64 × 64 grayscale","28 × 28 RGB","32 × 32 RGB","28 × 28 grayscale"],"answer":3,"fixed":false,"why":"Foster p. 62: 28 × 28 grayscale, pixel values 0–255, 10 clothing classes. 32 × 32 is the size after Foster's padding, not the raw size.","source":"Foster p. 62","study":"book/B03-variational-autoencoders.md — 2.1 Fashion-MNIST and preprocessing","origin":"practice"},{"id":"ae-007","chapter":"ae","topic":"Fashion-MNIST & preprocessing","type":"mcq","q":"Why does Foster pad Fashion-MNIST images to 32 × 32?","options":["For easier manipulation of the tensor shape as it passes through the network","To add a colour channel","Because Conv2D cannot accept 28 × 28 inputs","To make the images match CIFAR-10's 3 channels"],"answer":0,"fixed":false,"why":"Foster p. 62. With 32, three stride-2 halvings go 32 → 16 → 8 → 4 cleanly; 28 would give 14 → 7 → 4 (rounded). Padding adds no channel.","source":"Foster p. 62","study":"book/B03-variational-autoencoders.md — 2.1 Fashion-MNIST and preprocessing","origin":"practice"},{"id":"ae-008","chapter":"ae","topic":"Fashion-MNIST & preprocessing","type":"mcq","q":"How are the Fashion-MNIST pixel values preprocessed for the autoencoder?","options":["Left as integers 0–255","Divided by 255, so they lie between 0 and 1","Standardised to mean 0 and standard deviation 1","Scaled to between −1 and 1"],"answer":1,"fixed":false,"why":"Example 3-2: imgs.astype('float32') / 255.0. Note the sigmoid output also lives in [0, 1]; −1…1 would not match it.","source":"Foster pp. 62–63, Example 3-2","study":"book/B03-variational-autoencoders.md — 2.1 Fashion-MNIST and preprocessing","origin":"practice"},{"id":"ae-009","chapter":"ae","topic":"Fashion-MNIST & preprocessing","type":"mcq","q":"How many dimensions does the latent space of Foster's Fashion-MNIST autoencoder have?","options":["1","2","10","200"],"answer":1,"fixed":false,"why":"Two, so it can be plotted (Dense(2)). 10 is the number of classes; 200 is the CelebA VAE's latent size.","source":"Foster p. 64","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-010","chapter":"ae","topic":"Encoder & decoder layers","type":"mcq","q":"The encoder applies three Conv2D layers (32, 64, 128 filters; 3 × 3; strides = 2; padding = 'same') to a 32 × 32 × 1 input. What shape reaches the Flatten layer?","options":["(8, 8, 128)","(2, 2, 128)","(4, 4, 128)","(4, 4, 64)"],"answer":2,"fixed":false,"why":"Each stride-2 'same' layer halves: 32 → 16 → 8 → 4; channels = filters of the last layer = 128. (4, 4, 64) uses the wrong layer's filter count.","source":"Foster p. 64, Table 3-1","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-011","chapter":"ae","topic":"Parameter counts","type":"mcq","q":"How many parameters does the first encoder layer, Conv2D(32 filters, 3 × 3), have on a 32 × 32 × 1 input?","options":["288","320","896","9,248"],"answer":1,"fixed":false,"why":"(3·3·1 + 1)·32 = 320. 288 forgets the biases; 896 is the same layer on an RGB input.","source":"Foster p. 64, Table 3-1","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-012","chapter":"ae","topic":"Parameter counts","type":"mcq","q":"The encoder's last layer is Dense(2) on the flattened 4 × 4 × 128 tensor. How many parameters does it have?","options":["2,048","4,096","4,098","6,144"],"answer":2,"fixed":false,"why":"(2,048 + 1)·2 = 4,098. 4,096 forgets the biases; 6,144 is the decoder's Dense(2048) fed by 2 inputs: (2 + 1)·2,048.","source":"Foster p. 64, Table 3-1","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-013","chapter":"ae","topic":"Parameter counts","type":"mcq","q":"What is the total parameter count of Foster's encoder (Table 3-1)?","options":["4,098","96,770","246,273","343,043"],"answer":1,"fixed":false,"why":"320 + 18,496 + 73,856 + 4,098 = 96,770. 246,273 is the decoder; 343,043 the two together.","source":"Foster p. 64, Table 3-1","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-014","chapter":"ae","topic":"Conv2DTranspose","type":"mcq","q":"Which layer does the decoder use to grow the tensor back to 32 × 32?","options":["Dropout","Conv2D with strides = 2","MaxPooling2D","Conv2DTranspose with strides = 2"],"answer":3,"fixed":false,"why":"Conv2DTranspose with stride 2 doubles height and width (4 → 8 → 16 → 32); Conv2D with stride 2 halves them.","source":"Foster pp. 65–66","study":"book/B03-variational-autoencoders.md — 2.2 Architecture (box: Convolutional transpose layers)","origin":"practice"},{"id":"ae-015","chapter":"ae","topic":"Conv2DTranspose","type":"yn","q":"Does setting strides = 2 in a Conv2DTranspose layer halve the height and width of the input tensor?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. It doubles them (Foster p. 66). Halving is what a standard Conv2D with strides = 2 does.","source":"Foster p. 66","study":"book/B03-variational-autoencoders.md — 2.2 Architecture (box: Convolutional transpose layers)","origin":"practice"},{"id":"ae-016","chapter":"ae","topic":"Conv2DTranspose","type":"mcq","q":"In a convolutional transpose layer, what does the strides parameter determine?","options":["The internal zero padding between pixels in the image","The learning rate of the layer","The number of filters","The proportion of units dropped"],"answer":0,"fixed":false,"why":"Foster p. 66, Figure 3-5: the stride sets how many zeros are inserted between input pixels. The number of filters is a separate argument.","source":"Foster p. 66","study":"book/B03-variational-autoencoders.md — 2.2 Architecture (box: Convolutional transpose layers)","origin":"practice"},{"id":"ae-017","chapter":"ae","topic":"Conv2DTranspose","type":"mcq","q":"In Figure 3-5, a 3 × 3 × 1 filter is passed over a 3 × 3 × 1 image with a Conv2DTranspose, strides = 2. What is the output size?","options":["3 × 3 × 1","6 × 6 × 1","1 × 1 × 1","5 × 5 × 1"],"answer":1,"fixed":false,"why":"Foster p. 66: stride 2 doubles 3 → 6, giving a 6 × 6 × 1 output. 1 × 1 would be an ordinary valid convolution.","source":"Foster p. 66, Figure 3-5","study":"book/B03-variational-autoencoders.md — 2.2 Architecture (box: Convolutional transpose layers)","origin":"practice"},{"id":"ae-018","chapter":"ae","topic":"Encoder & decoder layers","type":"mcq","q":"Which activation does the decoder's final Conv2D layer use?","options":["LeakyReLU","Softmax","Sigmoid","ReLU"],"answer":2,"fixed":false,"why":"Example 3-4: activation='sigmoid', so each output pixel is in [0, 1] like the scaled input. ReLU is used in the Conv2DTranspose layers before it.","source":"Foster p. 67, Example 3-4","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-019","chapter":"ae","topic":"Encoder & decoder layers","type":"mcq","q":"How is the full autoencoder model defined in Keras?","options":["Model(encoder_input, encoder_output)","Model(decoder_input, encoder(decoder_output))","Sequential([decoder, encoder])","Model(encoder_input, decoder(encoder_output))"],"answer":3,"fixed":false,"why":"Example 3-5: the image goes through the encoder and back out through the decoder. Model(encoder_input, encoder_output) is the encoder alone.","source":"Foster p. 68, Example 3-5","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-020","chapter":"ae","topic":"Loss & training","type":"mcq","q":"What are passed as input and target when training the autoencoder?","options":["x_train as both the input and the target","random noise as input, x_train as target","y_train as input, x_train as target","x_train as input, y_train as target"],"answer":0,"fixed":false,"why":"Example 3-7: autoencoder.fit(x_train, x_train, …) — no labels are needed; the image is its own target.","source":"Foster p. 69, Example 3-7","study":"book/B03-variational-autoencoders.md — 2.3 Loss choice (box \"Choosing the Loss Function\")","origin":"practice"},{"id":"ae-021","chapter":"ae","topic":"Loss & training","type":"mcq","q":"Which loss does Foster compile the Fashion-MNIST autoencoder with?","options":["Categorical cross-entropy","Binary cross-entropy","Hinge loss","KL divergence"],"answer":1,"fixed":false,"why":"Example 3-6: loss='binary_crossentropy'. KL divergence only enters with the VAE.","source":"Foster p. 68, Example 3-6","study":"book/B03-variational-autoencoders.md — 2.3 Loss choice (box \"Choosing the Loss Function\")","origin":"practice"},{"id":"ae-022","chapter":"ae","topic":"Loss & training","type":"yn","q":"Is binary cross-entropy asymmetric, penalising errors toward the extremes (0 or 1) more heavily than errors toward the centre?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Foster p. 68. RMSE is the symmetric one (overestimate and underestimate penalised equally).","source":"Foster p. 68","study":"book/B03-variational-autoencoders.md — 2.3 Loss choice (box \"Choosing the Loss Function\")","origin":"practice"},{"id":"ae-023","chapter":"ae","topic":"Loss & training","type":"mcq","q":"The true pixel value is 0.7. Under binary cross-entropy, which prediction is penalised more heavily?","options":["0.6","Neither is penalised","0.8","Both equally"],"answer":2,"fixed":false,"why":"Foster p. 68: for a high true value, erring toward the extreme (0.8) costs more than erring toward the centre (0.6). 'Both equally' would be RMSE.","source":"Foster p. 68","study":"book/B03-variational-autoencoders.md — 2.3 Loss choice (box \"Choosing the Loss Function\")","origin":"practice"},{"id":"ae-024","chapter":"ae","topic":"Loss & training","type":"mcq","q":"Compared with RMSE, what does binary cross-entropy tend to produce?","options":["Sharper images with obviously pixelised edges","Exactly the same images","Images with colour artifacts","Slightly blurrier images, because it pushes predictions toward 0.5"],"answer":3,"fixed":false,"why":"Foster p. 68. Obviously pixelised edges are the RMSE risk, not the BCE one.","source":"Foster p. 68","study":"book/B03-variational-autoencoders.md — 2.3 Loss choice (box \"Choosing the Loss Function\")","origin":"practice"},{"id":"ae-025","chapter":"ae","topic":"Loss & training","type":"yn","q":"Does Foster say binary cross-entropy is always the right choice of reconstruction loss?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. 'There is no right or wrong choice — you should choose whichever works best for your use case after experimentation.' (p. 68)","source":"Foster p. 68","study":"book/B03-variational-autoencoders.md — 2.3 Loss choice (box \"Choosing the Loss Function\")","origin":"practice"},{"id":"ae-026","chapter":"ae","topic":"Latent space & reconstruction","type":"mcq","q":"Why do the reconstructions lose details such as logos?","options":["Reducing each image to just two numbers naturally loses information","The labels were not given to the model","The model trained for too few epochs","The sigmoid activation removes fine detail"],"answer":0,"fixed":false,"why":"Foster p. 69: by reducing each image to just two numbers we naturally lose some information. Labels are never needed for reconstruction.","source":"Foster p. 69, Figure 3-6","study":"book/B03-variational-autoencoders.md — 2.4 Reconstructing, visualising, generating","origin":"practice"},{"id":"ae-027","chapter":"ae","topic":"Latent space & reconstruction","type":"yn","q":"Did the autoencoder group similar-looking clothing items together in the latent space even though it was never shown the labels?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Foster p. 70: the labels are used only afterwards, to colour the plot (Figure 3-7).","source":"Foster p. 70","study":"book/B03-variational-autoencoders.md — 2.4 Reconstructing, visualising, generating","origin":"practice"},{"id":"ae-028","chapter":"ae","topic":"Latent space & reconstruction","type":"mcq","q":"In the coloured latent-space plot (Figure 3-7), what is the dark blue cloud of points in the bottom-right corner?","options":["Sneakers","Trousers","Ankle boots","Bags"],"answer":1,"fixed":false,"why":"Foster p. 70: dark blue bottom-right = trousers; the red cloud toward the centre = ankle boots.","source":"Foster p. 70, Figure 3-7","study":"book/B03-variational-autoencoders.md — 2.4 Reconstructing, visualising, generating","origin":"practice"},{"id":"ae-029","chapter":"ae","topic":"Generation problems → VAE","type":"mcq","q":"How does Foster generate new images from the plain autoencoder?","options":["Encode two images and average the reconstructions","Add noise to training images and reconstruct them","Sample points uniformly between the min and max of the embeddings and decode them","Sample from a standard normal distribution and decode"],"answer":2,"fixed":false,"why":"Example 3-10: np.random.uniform(mins, maxs, size=(18, 2)), then decoder.predict. Sampling a standard normal is the VAE way.","source":"Foster p. 71, Example 3-10","study":"book/B03-variational-autoencoders.md — 2.4 Reconstructing, visualising, generating","origin":"practice"},{"id":"ae-030","chapter":"ae","topic":"Generation problems → VAE","type":"mcq","q":"Which of these is NOT one of the problems Foster identifies with sampling a plain autoencoder's latent space?","options":["There are large gaps between groups of points","Some items occupy a much larger area than others","The distribution is not symmetric about (0, 0) or bounded","The decoder has too many parameters"],"answer":3,"fixed":false,"why":"Pp. 72–73 list uneven areas, an undefined/unbounded distribution, and holes/gaps. Parameter count is not one of them.","source":"Foster pp. 72–73","study":"book/B03-variational-autoencoders.md — 2.5 Why a plain autoencoder generates badly","origin":"practice"},{"id":"ae-031","chapter":"ae","topic":"Generation problems → VAE","type":"mcq","q":"Sampling uniformly from the latent space, why is a 'bag' more likely than an 'ankle boot'?","options":["The bag region of the latent space is larger than the ankle-boot region","The decoder was trained mostly on bags","There are more bags than boots in the dataset","Bags are simpler shapes, so the decoder prefers them"],"answer":0,"fixed":false,"why":"Foster p. 73: the area carved out for bags (orange) is larger than the ankle-boot area (red). Uniform sampling favours big regions.","source":"Foster p. 73, Figure 3-9","study":"book/B03-variational-autoencoders.md — 2.5 Why a plain autoencoder generates badly","origin":"practice"},{"id":"ae-032","chapter":"ae","topic":"Generation problems → VAE","type":"yn","q":"If (−1, −1) decodes to a good sandal, does a plain autoencoder guarantee that (−1.1, −1.1) also decodes to a good sandal?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. The autoencoder is not forced to make the space continuous (pp. 73–74). 'Guarantee' is the trap word.","source":"Foster pp. 73–74","study":"book/B03-variational-autoencoders.md — 2.5 Why a plain autoencoder generates badly","origin":"practice"},{"id":"ae-033","chapter":"ae","topic":"Generation problems → VAE","type":"mcq","q":"What happens to the 'gaps' problem when the latent space has more dimensions, e.g. for faces?","options":["It disappears","It becomes even more apparent — huge gaps with no incentive to decode well","It only affects reconstruction, not generation","It is unchanged"],"answer":1,"fixed":false,"why":"Foster p. 74: with free rein over more dimensions, there are huge gaps between groups. In 2-D the groups are squashed together so the issue is subtle.","source":"Foster p. 74","study":"book/B03-variational-autoencoders.md — 2.5 Why a plain autoencoder generates badly","origin":"practice"},{"id":"ae-034","chapter":"ae","topic":"Latent space & reconstruction","type":"yn","q":"Can autoencoders be used to clean noisy images (denoising)?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Box 'Autoencoders as Denoising Models', p. 64: the encoder learns it is not useful to capture the position of the random noise.","source":"Foster p. 64 (box)","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-035","chapter":"ae","topic":"Generation problems → VAE","type":"mcq","q":"In a VAE, unlike a plain autoencoder, each image is mapped to…","options":["A full-resolution pixel grid","A single point in the latent space","A multivariate normal distribution around a point in the latent space","A class label"],"answer":2,"fixed":false,"why":"Foster p. 75, Figure 3-10. The plain autoencoder maps each image to a single point — that is the distractor.","source":"Foster p. 75, Figure 3-10","study":"book/B03-variational-autoencoders.md — 3.1 The wardrobe, revisited + 3.2 The encoder outputs a distribution","origin":"practice"},{"id":"ae-036","chapter":"ae","topic":"Parameter counts","type":"mcq","q":"The decoder's first layer is Dense(2048), fed by the 2-D embedding. How many parameters does it have?","options":["4,096","4,098","6,144","2,048"],"answer":2,"fixed":false,"why":"(2 + 1)·2,048 = 6,144 (Table 3-2). 4,096 forgets the biases; 4,098 is the encoder's Dense(2) layer.","source":"Foster p. 65, Table 3-2","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-037","chapter":"ae","topic":"Parameter counts","type":"mcq","q":"The first decoder Conv2DTranspose has 128 filters of size 3 × 3 and receives a (4, 4, 128) tensor. How many parameters does it have?","options":["147,456","73,792","18,464","147,584"],"answer":3,"fixed":false,"why":"(3·3·128 + 1)·128 = 147,584 (Table 3-2). 147,456 forgets the 128 biases; 73,792 is the next (64-filter) layer.","source":"Foster p. 66, Table 3-2","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-038","chapter":"ae","topic":"Parameter counts","type":"mcq","q":"The decoder's final layer is Conv2D(1 filter, 3 × 3) on a (32, 32, 32) tensor. How many parameters does it have?","options":["289","288","320","10"],"answer":0,"fixed":false,"why":"(3·3·32 + 1)·1 = 289 (Table 3-2). 288 forgets the bias; 320 is the encoder's first Conv2D (32 filters on 1 channel).","source":"Foster p. 66, Table 3-2","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-039","chapter":"ae","topic":"Parameter counts","type":"mcq","q":"The encoder's second layer is Conv2D(64 filters, 3 × 3) on a (16, 16, 32) tensor. How many parameters does it have?","options":["18,496","18,432","640","73,856"],"answer":0,"fixed":false,"why":"(3·3·32 + 1)·64 = 18,496 (Table 3-1). 18,432 forgets the 64 biases; 73,856 is the third (128-filter) layer.","source":"Foster p. 64, Table 3-1","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-040","chapter":"ae","topic":"Parameter counts","type":"yn","q":"Does Foster's decoder (Table 3-2) have more parameters than his encoder (Table 3-1)?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes: 246,273 vs 96,770. The 128-filter Conv2DTranspose alone (147,584) is bigger than the whole encoder.","source":"Foster pp. 64–66, Tables 3-1 and 3-2","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-041","chapter":"ae","topic":"Fashion-MNIST & preprocessing","type":"mcq","q":"Example 3-2 calls np.pad(imgs, ((0, 0), (2, 2), (2, 2)), constant_values=0.0). How many zero pixels are added on each side of each image?","options":["1","4","2","3"],"answer":2,"fixed":false,"why":"2 on each side: 28 + 2 + 2 = 32. Adding 4 per side would give 36; the (0, 0) entry leaves the batch axis untouched.","source":"Foster p. 63, Example 3-2","study":"book/B03-variational-autoencoders.md — 2.1 Fashion-MNIST and preprocessing","origin":"practice"},{"id":"ae-042","chapter":"ae","topic":"Fashion-MNIST & preprocessing","type":"mcq","q":"Why does Foster embed the Fashion-MNIST images into a two-dimensional latent space?","options":["Two dimensions give the best reconstructions","There are only two clothing attributes","So the latent space can easily be plotted and visualised","Conv2D layers require an even latent size"],"answer":2,"fixed":false,"why":"Foster p. 64: 2-D helps us visualise the latent space. In practice a latent space usually has more than two dimensions to capture more nuance, so 2-D is NOT the best for reconstruction.","source":"Foster p. 64","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-043","chapter":"ae","topic":"Loss & training","type":"mcq","q":"In Example 3-7, how is the autoencoder trained?","options":["10 epochs, batch size 32","5 epochs, batch size 32","100 epochs, batch size 5","5 epochs, batch size 100"],"answer":3,"fixed":false,"why":"autoencoder.fit(x_train, x_train, epochs=5, batch_size=100, shuffle=True, …). 32 is the Keras default batch size, not Foster's choice here.","source":"Foster p. 69, Example 3-7","study":"book/B03-variational-autoencoders.md — 2.3 Loss choice (box \"Choosing the Loss Function\")","origin":"practice"},{"id":"ae-044","chapter":"ae","topic":"Loss & training","type":"yn","q":"In Example 3-7, is the validation data passed as (x_test, y_test)?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. It is validation_data=(x_test, x_test): like the training data, each test image is its own target; the labels are not used.","source":"Foster p. 69, Example 3-7","study":"book/B03-variational-autoencoders.md — 2.3 Loss choice (box \"Choosing the Loss Function\")","origin":"practice"},{"id":"ae-045","chapter":"ae","topic":"Loss & training","type":"mcq","q":"Which loss functions does Foster say are usually chosen for an autoencoder, computed between the individual pixels of the original and the reconstruction?","options":["RMSE or binary cross-entropy","Categorical cross-entropy or hinge loss","KL divergence or RMSE","Mean absolute error or categorical cross-entropy"],"answer":0,"fixed":false,"why":"Foster p. 68: 'usually chosen to be either the root mean squared error (RMSE) or binary cross-entropy'. KL divergence belongs to the VAE loss, not the plain autoencoder.","source":"Foster p. 68","study":"book/B03-variational-autoencoders.md — 2.3 Loss choice (box \"Choosing the Loss Function\")","origin":"practice"},{"id":"ae-046","chapter":"ae","topic":"Loss & training","type":"yn","q":"Under RMSE, is an overestimation of a pixel value penalised the same as an underestimation of the same size?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Foster p. 68: RMSE is symmetric, so output is distributed symmetrically around the average pixel values. It is binary cross-entropy that is asymmetric.","source":"Foster p. 68","study":"book/B03-variational-autoencoders.md — 2.3 Loss choice (box \"Choosing the Loss Function\")","origin":"practice"},{"id":"ae-047","chapter":"ae","topic":"Loss & training","type":"mcq","q":"The true pixel value is 0.3. Under binary cross-entropy, which prediction is penalised more heavily?","options":["0.4","0.2","Both equally","Neither is penalised"],"answer":1,"fixed":false,"why":"Foster p. 68: for a low true value, erring toward the extreme (0.2) costs more than erring toward the centre (0.4). The mirror of the 0.7 → 0.8 example.","source":"Foster p. 68","study":"book/B03-variational-autoencoders.md — 2.3 Loss choice (box \"Choosing the Loss Function\")","origin":"practice"},{"id":"ae-048","chapter":"ae","topic":"Latent space & reconstruction","type":"yn","q":"For denoising, does Foster say a 2-D latent space is probably too small to encode enough relevant information?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes (box, p. 64). But he adds that increasing the latent dimensionality quickly causes problems if the autoencoder is used as a generative model.","source":"Foster p. 64 (box)","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-049","chapter":"ae","topic":"Encoder & decoder layers","type":"yn","q":"In Example 3-3, does the encoder's final Dense(2) layer use a ReLU activation?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. layers.Dense(2, name='encoder_output') has no activation, so it is linear — which is why embeddings can be negative, e.g. trousers at [6.3, −0.9]. ReLU is on the three Conv2D layers.","source":"Foster pp. 61, 65, Example 3-3","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-050","chapter":"ae","topic":"Encoder & decoder layers","type":"mcq","q":"What does the Reshape layer in Foster's decoder do?","options":["Flattens the (4, 4, 128) tensor into a 2,048-vector","Pads the 28 × 28 output to 32 × 32","Adds the channel axis to the final image","Turns the 2,048-vector from the Dense layer into a (4, 4, 128) tensor"],"answer":3,"fixed":false,"why":"Example 3-4: Reshape(shape_before_flattening) turns the Dense output into a (4, 4, 128) tensor that the first Conv2DTranspose can take. Flattening is the encoder's step, the mirror image.","source":"Foster pp. 65–67, Example 3-4, Table 3-2","study":"book/B03-variational-autoencoders.md — 2.2 Architecture","origin":"practice"},{"id":"ae-051","chapter":"ae","topic":"Generation problems → VAE","type":"mcq","q":"To turn the autoencoder into a variational autoencoder, which two parts does Foster change?","options":["The decoder and the optimizer","The dataset and the decoder","The latent dimension and the optimizer","The encoder and the loss function"],"answer":3,"fixed":false,"why":"Foster p. 74: 'The two parts that we need to change are the encoder and the loss function.' The VAE decoder stays identical to the autoencoder's.","source":"Foster p. 74","study":"book/B03-variational-autoencoders.md — 3.1 The wardrobe, revisited + 3.2 The encoder outputs a distribution","origin":"practice"},{"id":"l01-001","chapter":"l01","topic":"Course objectives","type":"mcq","q":"Course objective 6 names two advanced GAN architectures that give more stable, higher-quality image generation. Which two?","options":["DCGAN and WGAN-GP","CycleGAN and StyleGAN","DCGAN and ProGAN","CGAN and StyleGAN"],"answer":0,"fixed":false,"why":"Slide 3, objective 6: 'advanced GAN architectures such as DCGAN and WGAN-GP'. CGAN appears only in the week 9–11 topic line, and StyleGAN/ProGAN/CycleGAN are not named.","source":"L01 slide 3","study":"lectures/L01-course-introduction.md — The eight course objectives (slide 3)","origin":"practice"},{"id":"l01-002","chapter":"l01","topic":"Course objectives","type":"mcq","q":"According to course objective 5, VAEs use a probabilistic approach and which quantity to better structure the latent space?","options":["Cross-entropy","KL divergence","Wasserstein distance","Mean squared error"],"answer":1,"fixed":false,"why":"Slide 3, objective 5: 'VAEs use a probabilistic approach and KL divergence to better structure the latent space'. Wasserstein distance belongs to WGAN, not VAEs.","source":"L01 slide 3","study":"lectures/L01-course-introduction.md — The eight course objectives (slide 3)","origin":"practice"},{"id":"l01-003","chapter":"l01","topic":"Course objectives","type":"yn","q":"Objective 5 motivates VAEs by a limitation of standard autoencoders. Is that limitation that standard autoencoders are poor at generating new data?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Slide 3: 'The limitations of standard autoencoders in generating new data are discussed, leading to the introduction of VAEs.' Plain autoencoders reconstruct well; generating from their latent space is the weak point.","source":"L01 slide 3","study":"lectures/L01-course-introduction.md — The eight course objectives (slide 3)","origin":"practice"},{"id":"l01-004","chapter":"l01","topic":"Course objectives","type":"mcq","q":"Which of these is NOT something objective 5 says the course will show VAEs doing?","options":["Generating new images","Manipulating the latent space","Performing arithmetic on image features","Classifying images into ten categories"],"answer":3,"fixed":false,"why":"Slide 3, objective 5 lists generating new images, manipulating the latent space and arithmetic on image features. Classification is the MLP/CNN topic (objectives 2–3), not a VAE use.","source":"L01 slide 3","study":"lectures/L01-course-introduction.md — The eight course objectives (slide 3)","origin":"practice"},{"id":"l01-005","chapter":"l01","topic":"Assessment & books","type":"mcq","q":"From the slide-5 assessment table, what share of the grade is written assessment (final exam + midterm + quizzes)?","options":["50%","60%","70%","80%"],"answer":3,"fixed":true,"why":"Final exam 30 + midterm 30 + quizzes 20 = 80; the project assignment and presentation is the remaining 20. 50% would wrongly treat the final as a project.","source":"L01 slide 5","study":"lectures/L01-course-introduction.md — Assessment (slide 5)","origin":"practice"},{"id":"l01-006","chapter":"l01","topic":"Assessment & books","type":"yn","q":"Is the 30% end-of-term component a final project rather than a written final exam?","options":["Yes","No"],"answer":1,"fixed":false,"why":"Slide 5 lists 'Final Exam, 1, 30' as a separate line from 'Project assignment and presentation, 1, 20'. The project is a different, 20% component.","source":"L01 slide 5","study":"lectures/L01-course-introduction.md — Assessment (slide 5)","origin":"practice"},{"id":"l01-007","chapter":"l01","topic":"Assessment & books","type":"mcq","q":"Which of these is NOT one of the three course books on slide 4?","options":["Goodfellow, Bengio & Courville, Deep Learning","Foster, Generative Deep Learning, 2nd ed.","Marr, Generative AI in Practice","Huyen, AI Engineering"],"answer":0,"fixed":false,"why":"Slide 4 lists Foster (2023), Marr (Wiley 2025) and Huyen (O'Reilly 2025). Goodfellow et al. is a classic deep learning text but is not on her list.","source":"L01 slide 4","study":"lectures/L01-course-introduction.md — Course materials (slide 4) — three books, not one","origin":"practice"},{"id":"l01-008","chapter":"l01","topic":"Week-preview figures","type":"mcq","q":"On the week-5 slide (Foster Fig. 3-4, autoencoder architecture), what is z?","options":["The random noise fed into a generator","The class label predicted for the image","The latent embedding vector passed from the encoder to the decoder","The reconstruction error between input and output"],"answer":2,"fixed":false,"why":"Fig. 3-4 draws image → Encoder → z → Decoder → image: z is the compressed embedding. Random noise as input belongs to the GAN generator (Fig. 4-2), not the autoencoder.","source":"L01 slide 9 · Foster Fig. 3-4","study":"lectures/L01-course-introduction.md — ★ The week-preview slides carry Foster figures — not just bullets","origin":"practice"},{"id":"l01-009","chapter":"l01","topic":"Week-preview figures","type":"mcq","q":"In the Fashion-MNIST strip on the week-5 slide, each clothing item is encoded to a vector such as [−1.8, 0.4]. How many numbers describe each item in the latent space?","options":["2","10","28","784"],"answer":0,"fixed":true,"why":"Every encoding shown is a pair, e.g. [−1.8, 0.4], [1.7, 5.8]: a 2-D latent space. 784 = 28 × 28 is the pixel count of the input image, which is what gets compressed.","source":"L01 slide 9 · Foster Fig. 3-4","study":"lectures/L01-course-introduction.md — ★ The week-preview slides carry Foster figures — not just bullets","origin":"practice"},{"id":"l01-010","chapter":"l01","topic":"Week-preview figures","type":"mcq","q":"On the week 9–11 slide (Foster Fig. 4-2), what does the discriminator output?","options":["A generated image","A prediction of how likely the image is to be real, e.g. 0.1","A random noise vector","A 2-D latent vector for the image"],"answer":1,"fixed":false,"why":"Fig. 4-2: Image (either real or fake) → Discriminator → '0.1 Prediction for how likely the image is to be real'. Producing an image from noise is the generator's job.","source":"L01 slide 11 · Foster Fig. 4-2","study":"lectures/L01-course-introduction.md — ★ The week-preview slides carry Foster figures — not just bullets","origin":"practice"},{"id":"l01-011","chapter":"l01","topic":"Week-preview figures","type":"yn","q":"In Foster Fig. 4-2 (week 9–11 slide), does the generator take an image as its input?","options":["Yes","No"],"answer":1,"fixed":false,"why":"The generator's input is random noise; its output is a generated image. It is the discriminator that takes an image (real or fake) as input.","source":"L01 slide 11 · Foster Fig. 4-2","study":"lectures/L01-course-introduction.md — ★ The week-preview slides carry Foster figures — not just bullets","origin":"practice"},{"id":"l01-012","chapter":"l01","topic":"Week-preview figures","type":"mcq","q":"The week-2 preview slide shows Foster Fig. 1-2, with labelled paintings and a prediction of 0.83. What kind of model does it illustrate?","options":["A generative model sampling new Van Gogh paintings","An autoencoder reconstructing paintings","A GAN whose discriminator scores a fake painting","A discriminative model predicting whether a painting is by Van Gogh"],"answer":3,"fixed":false,"why":"Caption on slide 6: 'A discriminative model trained to predict if a given image is painted by Van Gogh'; the training data carry labels 1/0 and the output 0.83 is p(Van Gogh | image). A generative model would need no labels.","source":"L01 slide 6 · Foster Fig. 1-2","study":"lectures/L01-course-introduction.md — ★ The week-preview slides carry Foster figures — not just bullets","origin":"practice"},{"id":"l01-013","chapter":"l01","topic":"Week-preview figures","type":"mcq","q":"The week-4 slide (Foster Fig. 2-11) applies two 3 × 3 × 1 filters to a 1 × 64 × 64 × 1 grayscale image. What output shape does the figure show?","options":["1 × 64 × 64 × 1","1 × 64 × 64 × 2","1 × 62 × 62 × 2","2 × 64 × 64 × 1"],"answer":1,"fixed":false,"why":"The figure labels the output '1 × 64 × 64 × 2' (batch × height × width × channels): one channel per filter, spatial size kept. 62 × 62 is what you would get without 'same' padding, which the figure does not show.","source":"L01 slide 8 · Foster Fig. 2-11","study":"lectures/L01-course-introduction.md — ★ The week-preview slides carry Foster figures — not just bullets","origin":"practice"},{"id":"l02-001","chapter":"l02","topic":"Generative vs discriminative","type":"mcq","q":"A discriminative model estimates…","options":["p(y | x)","p(x)","p(x | y)","p(θ | x)"],"answer":0,"fixed":false,"why":"Discriminative modeling estimates p(y | x), the probability of a label given an observation. p(x) is generative; p(x | y) is a conditional generative model.","source":"slide 8 · Foster p. 6","study":"book/B01-generative-modeling.md — 1.1 Generative versus discriminative modeling","origin":"practice"},{"id":"l02-002","chapter":"l02","topic":"Generative vs discriminative","type":"mcq","q":"Generating a new painting in the style of Van Gogh is an example of…","options":["Discriminative modeling — modelling p(y | x)","Generative modeling — modelling p(x) and sampling from it","Supervised classification","Regression"],"answer":1,"fixed":false,"why":"Creating a new observation means modelling p(x) and sampling from it. Predicting whether a painting IS by Van Gogh would be discriminative.","source":"slide 9 · Foster p. 6","study":"lectures/L02-generative-modeling.md — ★★★ The professor's in-class questions, with answers","origin":"professor"},{"id":"l02-003","chapter":"l02","topic":"Generative vs discriminative","type":"mcq","q":"Predicting whether a given painting was painted by Van Gogh is an example of…","options":["Generative modeling — modelling p(x)","Conditional generative modeling — modelling p(x | y)","Discriminative modeling — modelling p(y | x)","Representation learning — mapping to a latent space"],"answer":2,"fixed":false,"why":"It outputs the probability of a label (Van Gogh or not) given the painting, i.e. p(y | x). Generating a new Van Gogh-style painting would be the generative case.","source":"slide 9 · Foster pp. 5–6","study":"lectures/L02-generative-modeling.md — ★★★ The professor's in-class questions, with answers","origin":"professor"},{"id":"l02-004","chapter":"l02","topic":"Generative vs discriminative","type":"mcq","q":"Her slide-9 aim reads: 'Model the probability of observing an observation x. Sampling from this distribution allows us to generate new observations.' Which kind of modeling is this?","options":["Discriminative modeling","Classification with a softmax output","Maximum likelihood estimation of a label","Generative modeling"],"answer":3,"fixed":false,"why":"This is the definition of generative modeling: estimate p(x) and sample from it. Discriminative modeling models a label y given x, not the observation itself.","source":"slides 8–9 · Foster p. 6","study":"lectures/L02-generative-modeling.md — ★★★ The professor's in-class questions, with answers","origin":"professor"},{"id":"l02-005","chapter":"l02","topic":"Generative vs discriminative","type":"yn","q":"Must a generative model be deterministic, returning the same output every time?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. It must be probabilistic and include a random component so that it can sample many different variations of the output.","source":"slide 6 · Foster pp. 4–5","study":"book/B01-generative-modeling.md — 1. What is generative modeling?","origin":"practice"},{"id":"l02-006","chapter":"l02","topic":"Generative vs discriminative","type":"mcq","q":"A generative model that is told to generate specifically an image of an apple from a fruit dataset is modelling…","options":["p(x | y)","p(x)","p(y | x)","p(θ | X)"],"answer":0,"fixed":false,"why":"Foster's 'Conditional Generative Models' box: p(x | y) is the probability of seeing observation x with a specific label y. Plain p(x) has no label to condition on; p(y | x) is discriminative.","source":"Foster p. 6 (box)","study":"book/B01-generative-modeling.md — 1.1 Generative versus discriminative modeling","origin":"practice"},{"id":"l02-007","chapter":"l02","topic":"Generative vs discriminative","type":"yn","q":"If we built a perfect discriminative model for identifying Van Gogh paintings, would it know how to create a painting that looks like a Van Gogh?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. A discriminator can only output probabilities for existing images; to create one you need to train a generative model and sample from it.","source":"Foster p. 6","study":"book/B01-generative-modeling.md — 1.1 Generative versus discriminative modeling","origin":"practice"},{"id":"l02-008","chapter":"l02","topic":"Generative vs discriminative","type":"mcq","q":"Which of these is NOT a generative model, according to her slide on probabilistic vs deterministic models?","options":["A fixed calculation that outputs the average value of each pixel in the training set","A model that samples new observations from a learned p_model","A model with a random component that influences each sample","A model that turns random noise into new images resembling the training data"],"answer":0,"fixed":false,"why":"A fixed calculation such as the pixel-wise average always gives the same output, so it is not generative. The other three all include a random component and sample new observations.","source":"slide 6 · Foster pp. 4–5","study":"lectures/L02-generative-modeling.md — The three definitions she put on their own slides","origin":"practice"},{"id":"l02-009","chapter":"l02","topic":"Framework & desirable properties","type":"mcq","q":"Which are the three desirable properties of p_model in the generative modeling framework?","options":["Accuracy, Speed, Representation","Generation, Controlled Randomness, Representation","Accuracy, Generation, Representation","Accuracy, Deterministic Output, Generation"],"answer":2,"fixed":false,"why":"Her slide-13 question ('select 3 correct answers'): Accuracy, Generation, Representation. 'Controlled Randomness' and 'Deterministic Output' are her distractors.","source":"slides 12–13 · Foster pp. 10–11","study":"lectures/L02-generative-modeling.md — ★★★ The professor's in-class questions, with answers","origin":"professor"},{"id":"l02-010","chapter":"l02","topic":"Framework & desirable properties","type":"mcq","q":"Which of these is NOT one of the three named desirable properties of p_model?","options":["Accuracy","Generation","Representation","Controlled Randomness"],"answer":3,"fixed":false,"why":"The framework names Accuracy, Generation and Representation. A generative model must include a random component (slide 6), but 'Controlled Randomness' is not one of the named properties — it was her trap option.","source":"slide 13 · Foster pp. 10–11","study":"lectures/L02-generative-modeling.md — ★★★ The professor's in-class questions, with answers","origin":"professor"},{"id":"l02-011","chapter":"l02","topic":"Framework & desirable properties","type":"mcq","q":"Which property says: if p_model is high for a generated observation it should look like it was drawn from p_data, and if low it should not?","options":["Generation","Accuracy","Representation","Tractability"],"answer":1,"fixed":false,"why":"That is Accuracy. Generation is about being able to sample easily; Representation is about understanding how high-level features are represented.","source":"slide 12 · Foster p. 11","study":"book/B01-generative-modeling.md — 2.2 The Generative Modeling Framework ★","origin":"practice"},{"id":"l02-012","chapter":"l02","topic":"Framework & desirable properties","type":"mcq","q":"Which property says it should be possible to easily sample a new observation from p_model?","options":["Representation","Accuracy","Generation","Likelihood"],"answer":2,"fixed":false,"why":"That is Generation. Accuracy concerns whether high-p_model samples look like p_data; likelihood is not one of the three properties at all.","source":"slide 12 · Foster p. 11","study":"book/B01-generative-modeling.md — 2.2 The Generative Modeling Framework ★","origin":"practice"},{"id":"l02-013","chapter":"l02","topic":"Framework & desirable properties","type":"mcq","q":"In Figure 1-6, point A lies inside the orange box but in the middle of the sea. What does it show?","options":["It can be generated by p_model but does not appear to come from p_data","It can come from p_data but could never be generated by p_model","It can be generated by both p_model and p_data","It is not in the sample space"],"answer":0,"fixed":false,"why":"A is inside the box (so p_model can produce it) but in the sea (impossible under p_data) — an accuracy failure. Point B is the reverse case: outside the box on land, a gap in the model.","source":"slide 14 · Foster pp. 11–12","study":"book/B01-generative-modeling.md — 2.3 Revealing p_data (Figure 1-6)","origin":"practice"},{"id":"l02-014","chapter":"l02","topic":"Framework & desirable properties","type":"yn","q":"In the world-map example, does the orange box represent p_data?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. It represents p_model, the fitted model; p_data is the true unknown distribution (uniform over the land mass, the grey area).","source":"slides 14, 28 · Foster p. 11 (Figure 1-6 caption)","study":"lectures/L02-generative-modeling.md — ★★★ The professor's in-class questions, with answers","origin":"professor"},{"id":"l02-015","chapter":"l02","topic":"Framework & desirable properties","type":"yn","q":"Is the orange-box model easy to sample from?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. It is simply a uniform distribution over the box, so you can choose a point at random inside it — the model scores well on Generation despite being an oversimplification.","source":"Foster p. 12","study":"book/B01-generative-modeling.md — 2.3 Revealing p_data (Figure 1-6)","origin":"practice"},{"id":"l02-016","chapter":"l02","topic":"Representation learning","type":"mcq","q":"What is representation learning?","options":["Describing each observation in a lower-dimensional latent space and learning a mapping back to the original domain","Learning to classify images into labelled categories","Memorising every training observation exactly","Scaling input features to between 0 and 1"],"answer":0,"fixed":false,"why":"Her slide-15 definition: describe each observation with a lower-dimensional latent space, then learn a mapping from a latent point to a point in the original domain. Classification is discriminative.","source":"slide 15 · Foster p. 13","study":"lectures/L02-generative-modeling.md — The three definitions she put on their own slides","origin":"practice"},{"id":"l02-017","chapter":"l02","topic":"Representation learning","type":"mcq","q":"In the biscuit-tin example, which two features can uniquely represent each tin?","options":["Colour and texture","Height and width","Radius and lid shape","Brightness and contrast"],"answer":1,"fixed":false,"why":"Height and width — so each high-dimensional pixel image becomes a point in a two-dimensional latent space.","source":"slide 16 · Foster p. 13","study":"book/B01-generative-modeling.md — 2.4 Representation learning ★","origin":"practice"},{"id":"l02-018","chapter":"l02","topic":"Representation learning","type":"yn","q":"For a machine to learn the biscuit-tin latent space, must it first establish that height and width are the two latent dimensions that best describe the dataset?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 17: the machine must first establish which dimensions best describe the data, then learn the mapping to a grayscale tin image — which is why it is not easy for a machine.","source":"slide 17 · Foster p. 13","study":"book/B01-generative-modeling.md — 2.4 Representation learning ★","origin":"practice"},{"id":"l02-019","chapter":"l02","topic":"Representation learning","type":"mcq","q":"Mathematically, what do encoder–decoder techniques try to do?","options":["Increase the dimensionality of the data so classes become linearly separable","Store each training image as its own isolated latent point","Convert each image directly into its class label","Transform the highly nonlinear manifold the data lies on into a simpler latent space that can be sampled from"],"answer":3,"fixed":false,"why":"Slide 19: they map the nonlinear manifold (e.g. in pixel space) to a simpler latent space so that any sampled latent point is likely to represent a well-formed image.","source":"slide 19 · Foster pp. 14–15","study":"book/B01-generative-modeling.md — 2.4 Representation learning ★","origin":"practice"},{"id":"l02-020","chapter":"l02","topic":"Sample space, density & parametric models","type":"mcq","q":"What must the integral of a probability density function over the entire range of possible values equal?","options":["∞","It depends on the number of observations","0","1"],"answer":3,"fixed":false,"why":"1 — the defining property of a density, so that it is a well-defined probability distribution (her slide-29 question).","source":"slides 22, 29 · Foster p. 16","study":"lectures/L02-generative-modeling.md — ★★★ The professor's in-class questions, with answers","origin":"professor"},{"id":"l02-021","chapter":"l02","topic":"Sample space, density & parametric models","type":"mcq","q":"In the world-map example, how does the density function of our generative model behave with respect to the orange box?","options":["It is highest at the centre of the box and decreases towards the edges","It is zero outside the box and constant inside, so the integral over the sample space equals 1","It is constant everywhere, inside and outside the box","It is zero inside the box and constant outside it"],"answer":1,"fixed":false,"why":"p_model is uniform: zero outside the box, constant inside, with the constant chosen so the total integrates to 1. 'Highest at the centre' describes a Gaussian, not a uniform.","source":"slides 22, 28 · Foster p. 16","study":"lectures/L02-generative-modeling.md — ★★★ The professor's in-class questions, with answers","origin":"professor"},{"id":"l02-022","chapter":"l02","topic":"Sample space, density & parametric models","type":"mcq","q":"With a uniform distribution as the model family, each box defined by the coordinates of its bottom-left and top-right corners, how many parameters does the parametric model have (2-D map)?","options":["Two","Eight","Six","Four"],"answer":3,"fixed":false,"why":"Four: θ = (θ₁, θ₂) for the bottom-left corner and (θ₃, θ₄) for the top-right. Two counts only the corners; eight double-counts.","source":"slides 23, 29 · Foster p. 16","study":"lectures/L02-generative-modeling.md — ★★★ The professor's in-class questions, with answers","origin":"professor"},{"id":"l02-023","chapter":"l02","topic":"Sample space, density & parametric models","type":"mcq","q":"A uniform model is a box defined by two opposite corners. In three dimensions, how many parameters does it have?","options":["2","4","6","8"],"answer":2,"fixed":false,"why":"Corners × dimensions = 2 × 3 = 6. Her slide asked the 2-D case (answer 4).","source":"slide 29 (2-D version) · Foster p. 16","study":"lectures/L02-generative-modeling.md — ★★★ The professor's in-class questions, with answers","origin":"practice"},{"id":"l02-024","chapter":"l02","topic":"Sample space, density & parametric models","type":"mcq","q":"What is the sample space?","options":["The set of model parameters","The complete set of all values an observation x can take","The set of training observations","The latent space of the decoder"],"answer":1,"fixed":false,"why":"Definition: the complete set of all values an observation x can take — for the map, every (latitude, longitude) pair, not just the training points.","source":"slide 21 · Foster p. 16","study":"book/B01-generative-modeling.md — 3. Core probability theory ★","origin":"practice"},{"id":"l02-025","chapter":"l02","topic":"Sample space, density & parametric models","type":"yn","q":"The point x = (11.3493, 142.1996) lies in the sea. Is it a point in the sample space?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. It is in the sample space (every latitude/longitude pair is) but it does not belong to the true data-generating distribution. Don't confuse 'in the sample space' with 'likely under p_data'.","source":"slide 21 · Foster p. 16","study":"book/B01-generative-modeling.md — 3. Core probability theory ★","origin":"practice"},{"id":"l02-026","chapter":"l02","topic":"Sample space, density & parametric models","type":"mcq","q":"What is a parametric model?","options":["A family of density functions p_θ(x) that can be described by a finite number of parameters θ","A model whose output is a label for each observation","The single true density p_data that generated the data","A model with no parameters that memorises the training set"],"answer":0,"fixed":false,"why":"Definition: a family of densities p_θ(x) described by a finite number of parameters. In the map example the family is all possible boxes, each given by four numbers.","source":"slide 23 · Foster p. 16","study":"book/B01-generative-modeling.md — 3. Core probability theory ★","origin":"practice"},{"id":"l02-027","chapter":"l02","topic":"Likelihood & MLE","type":"yn","q":"Is the likelihood L(θ | x) a function of the data, with the parameters held fixed?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. It is a function of the parameters; the data are fixed once observed (her slide-30 question).","source":"slide 30 · Foster p. 17","study":"lectures/L02-generative-modeling.md — ★★★ The professor's in-class questions, with answers","origin":"professor"},{"id":"l02-028","chapter":"l02","topic":"Likelihood & MLE","type":"yn","q":"Can the likelihood of a model for the observed data be equal to zero?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. If the model gives zero density to any observed point, the product collapses to zero — e.g. a box covering only the left half of the map.","source":"slides 24, 30 · Foster p. 17","study":"lectures/L02-generative-modeling.md — ★★★ The professor's in-class questions, with answers","origin":"professor"},{"id":"l02-029","chapter":"l02","topic":"Likelihood & MLE","type":"mcq","q":"In the world-map example, which box is the maximum likelihood estimate?","options":["The smallest box that still contains all the training points","The largest box covering the entire map","The box centred on the mean of the points with unit area","A random box anywhere on the map"],"answer":0,"fixed":false,"why":"Missing a point gives likelihood 0; the uniform density is 1/area, so the smaller the box the higher the likelihood — subject to containing every point.","source":"slides 26, 30 · Foster p. 18","study":"lectures/L02-generative-modeling.md — ★★★ The professor's in-class questions, with answers","origin":"professor"},{"id":"l02-030","chapter":"l02","topic":"Likelihood & MLE","type":"mcq","q":"For a dataset X of independent observations, the likelihood L(θ | X) equals…","options":["Σ over x ∈ X of p_θ(x)","∏ over x ∈ X of p_θ(x)","the maximum of p_θ(x) over x ∈ X","∫ p_θ(x) dx over the sample space"],"answer":1,"fixed":false,"why":"The likelihood of independent observations is the product of the densities. The sum appears only after taking logs (the log-likelihood); the integral of a density is always 1.","source":"slide 24 · Foster p. 17","study":"book/B01-generative-modeling.md — 3. Core probability theory ★","origin":"practice"},{"id":"l02-031","chapter":"l02","topic":"Likelihood & MLE","type":"mcq","q":"Why do we often use the log-likelihood instead of the likelihood?","options":["Because the log-likelihood is always positive","Because it turns the parameters into probabilities","Because it makes the model deterministic","Because a product of many terms between 0 and 1 is computationally difficult to work with"],"answer":3,"fixed":false,"why":"Foster p. 17: the product of a large number of terms between 0 and 1 is hard to work with; the log turns it into a sum. Log-likelihoods of densities in [0, 1] are ≤ 0, not positive.","source":"slide 25 · Foster p. 17","study":"book/B01-generative-modeling.md — 3. Core probability theory ★","origin":"practice"},{"id":"l02-032","chapter":"l02","topic":"Likelihood & MLE","type":"mcq","q":"Neural networks minimise a loss, so the maximum likelihood estimate θ̂ is written as the argmin over θ of…","options":["the likelihood L(θ | X)","the log-likelihood ℓ(θ | X)","the negative log-likelihood −ℓ(θ | X) = −log p_θ(X)","the density integral ∫ p_θ(x) dx"],"answer":2,"fixed":false,"why":"Maximising ℓ is the same as minimising −ℓ, the negative log-likelihood. Minimising the (log-)likelihood itself would find the worst parameters.","source":"slide 27 · Foster p. 18","study":"book/B01-generative-modeling.md — 3. Core probability theory ★","origin":"practice"},{"id":"l02-033","chapter":"l02","topic":"Likelihood & MLE","type":"mcq","q":"When generative modeling is viewed as maximum likelihood estimation, what are the parameters θ?","options":["The training observations","The weights of the neural networks contained in the model","The latent vectors of each image","The class labels"],"answer":1,"fixed":false,"why":"Slide 27: θ are the network weights; we look for the weights that maximise the likelihood of the observed data. The data are fixed, not parameters.","source":"slide 27 · Foster p. 18","study":"book/B01-generative-modeling.md — 3. Core probability theory ★","origin":"practice"},{"id":"l02-034","chapter":"l02","topic":"Likelihood & MLE","type":"mcq","q":"A uniform box of area 4 contains all three training points. What is the likelihood of the box for these three points?","options":["0.75","0.25","1/64 ≈ 0.016","1/12 ≈ 0.083"],"answer":2,"fixed":false,"why":"Uniform density inside = 1/area = 1/4. Likelihood = product over points = (1/4)³ = 1/64. 0.25 is the density at one point; 0.75 adds instead of multiplying.","source":"slides 22, 24 · Foster pp. 16–17 (definitions)","study":"book/B01-generative-modeling.md — 3. Core probability theory ★","origin":"practice"},{"id":"l02-035","chapter":"l02","topic":"Likelihood & MLE","type":"yn","q":"Two boxes both contain every training point: box P has area 2 and box Q has area 8. Does box Q have the higher likelihood?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Uniform density = 1/area, so every point gets density 1/2 under P but 1/8 under Q; P's likelihood is higher. This is why the MLE is the smallest box containing all points.","source":"slide 26 · Foster pp. 16–18","study":"book/B01-generative-modeling.md — 3. Core probability theory ★","origin":"practice"},{"id":"l02-036","chapter":"l02","topic":"Model taxonomy","type":"mcq","q":"In Foster's taxonomy, which family is the variational autoencoder?","options":["Explicit density — tractable density","Implicit density","Explicit density — approximate density","It is not a generative model"],"answer":2,"fixed":false,"why":"Figure 1-10: VAEs introduce a latent variable and optimise an approximation of the density. Tractable = autoregressive, normalizing flows; implicit = GANs. (Book ch. 1 — not on her slides.)","source":"Foster pp. 19–20 (Figure 1-10)","study":"book/B01-generative-modeling.md — 4. Generative model taxonomy ★","origin":"practice"},{"id":"l02-037","chapter":"l02","topic":"Model taxonomy","type":"mcq","q":"Which model family estimates the density only implicitly, through a stochastic process that directly generates data?","options":["Variational autoencoders","Normalizing flow models","Autoregressive models","Generative adversarial networks"],"answer":3,"fixed":false,"why":"Figure 1-10: GANs are the implicit-density family; they never estimate p(x). The other three model the density explicitly.","source":"Foster p. 19 (Figure 1-10)","study":"book/B01-generative-modeling.md — 4. Generative model taxonomy ★","origin":"practice"},{"id":"l02-038","chapter":"l02","topic":"Model taxonomy","type":"mcq","q":"Which family is an explicit, TRACTABLE density model?","options":["Energy-based models","Autoregressive models","Diffusion models","Generative adversarial networks"],"answer":1,"fixed":false,"why":"Autoregressive models (and normalizing flows) constrain the architecture so the density can be calculated. Energy-based and diffusion models are approximate; GANs are implicit.","source":"Foster p. 19 (Figure 1-10)","study":"book/B01-generative-modeling.md — 4. Generative model taxonomy ★","origin":"practice"},{"id":"l02-039","chapter":"l02","topic":"Model taxonomy","type":"mcq","q":"Which of these is NOT an approximate-density model in Foster's taxonomy?","options":["Variational autoencoders","Energy-based models","Normalizing flow models","Diffusion models"],"answer":2,"fixed":false,"why":"Normalizing flows are tractable: they chain tractable, invertible functions from a simple distribution. VAEs, energy-based and diffusion models all optimise an approximation.","source":"Foster pp. 19–20 (Figure 1-10)","study":"book/B01-generative-modeling.md — 4. Generative model taxonomy ★","origin":"practice"},{"id":"l02-040","chapter":"l02","topic":"Codebase","type":"mcq","q":"According to her codebase slides, which technology is the book's codebase intended to be used with?","options":["Docker","Kubernetes","Vagrant","A Conda environment only"],"answer":0,"fixed":false,"why":"Slide 34: the codebase is intended to be used with Docker, a free containerization technology. (On this Mac the native venv in code/ is used instead.)","source":"slide 34 · Foster p. 21","study":"lectures/L02-generative-modeling.md — Codebase section (slides 32–35)","origin":"practice"},{"id":"l02-041","chapter":"l02","topic":"Codebase","type":"yn","q":"If you do not have a GPU, will the book's examples still train on a CPU?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 35: all examples train on a CPU, just more slowly; the README also describes a pay-as-you-go Google Cloud GPU option.","source":"slide 35 · Foster p. 21","study":"lectures/L02-generative-modeling.md — Codebase section (slides 32–35)","origin":"practice"},{"id":"l02-042","chapter":"l02","topic":"Generative vs discriminative","type":"mcq","q":"Writing a brand-new email that reads like the emails in a large training set of emails is an example of…","options":["Discriminative modeling — modelling p(y | x)","Spam classification with a softmax output layer","Generative modeling — modelling p(x) and sampling from it","Regression on the number of words in each email"],"answer":2,"fixed":false,"why":"Producing a new observation means modelling p(x) and sampling from it. Deciding whether an existing email is spam would be the discriminative case.","source":"slides 8–9 · Foster p. 6","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q1 (slide 9) — generative versus discriminative","origin":"practice","twin":"l02-002"},{"id":"l02-043","chapter":"l02","topic":"Generative vs discriminative","type":"yn","q":"Is generating a new Van Gogh-style painting an example of discriminative modeling?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Creating a new painting is generative: model p(x) and sample from it. Discriminative modeling only predicts a label (Van Gogh or not) for a painting that already exists.","source":"slide 9 · Foster pp. 5–6","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q1 (slide 9) — generative versus discriminative","origin":"practice","twin":"l02-002"},{"id":"l02-044","chapter":"l02","topic":"Generative vs discriminative","type":"mcq","q":"A model trained on Van Gogh paintings is asked to produce a new Van Gogh-style painting. How does it produce it?","options":["By outputting the probability that the painting has label 1","By taking the average value of each pixel in the training paintings","By returning the training painting with the highest score","By sampling from the distribution p(x) it has learned"],"answer":3,"fixed":false,"why":"Generative modeling estimates p(x), and sampling from it gives new observations. The pixel-wise average is the slide-6 example of a fixed calculation that is NOT generative.","source":"slides 6, 8 · Foster pp. 4–6","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q1 (slide 9) — generative versus discriminative","origin":"practice","twin":"l02-002"},{"id":"l02-045","chapter":"l02","topic":"Generative vs discriminative","type":"mcq","q":"A spam filter that predicts whether an incoming email is spam is an example of…","options":["Discriminative modeling — modelling p(y | x)","Conditional generative modeling — modelling p(x | y)","Generative modeling — modelling p(x)","Representation learning — mapping to a latent space"],"answer":0,"fixed":false,"why":"It outputs the probability of a label (spam or not) given the email, i.e. p(y | x). p(x | y) would generate a new email with a chosen label.","source":"slides 7–8 · Foster pp. 5–6","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q1 (slide 9) — generative versus discriminative","origin":"practice","twin":"l02-003"},{"id":"l02-046","chapter":"l02","topic":"Generative vs discriminative","type":"yn","q":"Is predicting whether a given painting was painted by Van Gogh an example of discriminative modeling?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. The model outputs the probability that the painting has label 1 (Van Gogh), which is p(y | x). It cannot create a painting, so it is not generative.","source":"slide 9 · Foster pp. 5–6","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q1 (slide 9) — generative versus discriminative","origin":"practice","twin":"l02-003"},{"id":"l02-047","chapter":"l02","topic":"Generative vs discriminative","type":"yn","q":"To train the Van Gogh discriminator, must each painting in the training data have a label?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 7: in discriminative modeling each observation has a label (Van Gogh = 1, others = 0). It is generative modeling that does not need a labelled dataset.","source":"slide 7 · Foster pp. 5–6","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q1 (slide 9) — generative versus discriminative","origin":"practice","twin":"l02-003"},{"id":"l02-048","chapter":"l02","topic":"Generative vs discriminative","type":"mcq","q":"Which kind of modeling has the aim: 'model the probability of a label y given some observation x'?","options":["Generative modeling","Discriminative modeling","Conditional generative modeling","Representation learning"],"answer":1,"fixed":false,"why":"That is the definition of discriminative modeling, p(y | x). Conditional generative modeling is the reverse, p(x | y): an observation given a label.","source":"slide 8 · Foster p. 6","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q1 (slide 9) — generative versus discriminative","origin":"practice","twin":"l02-004"},{"id":"l02-049","chapter":"l02","topic":"Generative vs discriminative","type":"yn","q":"Does the aim 'model the probability of observing an observation x; sampling from this distribution allows us to generate new observations' describe discriminative modeling?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Modelling p(x) and sampling from it is the definition of generative modeling. Discriminative modeling models a label y given x and cannot generate anything.","source":"slides 8–9 · Foster p. 6","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q1 (slide 9) — generative versus discriminative","origin":"practice","twin":"l02-004"},{"id":"l02-050","chapter":"l02","topic":"Generative vs discriminative","type":"mcq","q":"According to the generative-modeling aim on her slide, how are new observations obtained once the probability of observing x has been modelled?","options":["By predicting the label y of each training observation","By averaging the training observations feature by feature","By thresholding p(y | x) at 0.5","By sampling from the modelled distribution"],"answer":3,"fixed":false,"why":"Slide 8/9: 'Sampling from this distribution allows us to generate new observations.' Averaging is a fixed calculation (not generative); labels and thresholds belong to discriminative models.","source":"slides 8–9 · Foster p. 6","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q1 (slide 9) — generative versus discriminative","origin":"practice","twin":"l02-004"},{"id":"l02-051","chapter":"l02","topic":"Framework & desirable properties","type":"mcq","q":"Which set lists exactly the three desirable properties of p_model in the generative modeling framework?","options":["Accuracy, Generation, Representation","Generation, Representation, Controlled Randomness","Accuracy, Deterministic Output, Representation","Accuracy, Generation, Controlled Randomness"],"answer":0,"fixed":false,"why":"Foster's framework box names Accuracy, Generation and Representation. Each distractor swaps one in for her trap options 'Controlled Randomness' or 'Deterministic Output'.","source":"slides 12–13 · Foster pp. 10–11","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q2 (slide 13) — the desirable properties ⚠️ the trap","origin":"practice","twin":"l02-009"},{"id":"l02-052","chapter":"l02","topic":"Framework & desirable properties","type":"yn","q":"Is 'Deterministic Output' one of the desirable properties of p_model?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. It contradicts slide 6: a generative model must be probabilistic, not deterministic. The three properties are Accuracy, Generation and Representation.","source":"slides 6, 13 · Foster pp. 4, 11","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q2 (slide 13) — the desirable properties ⚠️ the trap","origin":"practice","twin":"l02-009"},{"id":"l02-053","chapter":"l02","topic":"Framework & desirable properties","type":"yn","q":"Is 'Representation' one of the three desirable properties of p_model?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. The three are Accuracy, Generation and Representation; Representation means it should be possible to understand how high-level features in the data are represented by p_model.","source":"slides 12–13 · Foster p. 11","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q2 (slide 13) — the desirable properties ⚠️ the trap","origin":"practice","twin":"l02-009"},{"id":"l02-054","chapter":"l02","topic":"Framework & desirable properties","type":"mcq","q":"Which of these IS one of the three named desirable properties of p_model?","options":["Controlled Randomness","Deterministic Output","Representation","Tractability"],"answer":2,"fixed":false,"why":"Representation is one of Accuracy, Generation, Representation. 'Controlled Randomness' and 'Deterministic Output' were her slide-13 traps, and tractability is not a named property.","source":"slide 13 · Foster p. 11","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q2 (slide 13) — the desirable properties ⚠️ the trap","origin":"practice","twin":"l02-010"},{"id":"l02-055","chapter":"l02","topic":"Framework & desirable properties","type":"yn","q":"Slide 6 says a generative model must include a random component. Does that make 'Controlled Randomness' one of the three named desirable properties of p_model?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Being probabilistic is a requirement of a generative model (slide 6), but the framework's named properties are only Accuracy, Generation and Representation.","source":"slides 6, 13 · Foster pp. 4, 11","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q2 (slide 13) — the desirable properties ⚠️ the trap","origin":"practice","twin":"l02-010"},{"id":"l02-056","chapter":"l02","topic":"Framework & desirable properties","type":"mcq","q":"Which property says: 'It should be possible to understand how different high-level features in the data are represented by p_model'?","options":["Accuracy","Generation","Controlled Randomness","Representation"],"answer":3,"fixed":false,"why":"That is Representation. Accuracy is about high-p_model samples looking like p_data; Generation is about easy sampling; Controlled Randomness is not a property at all.","source":"slide 12 · Foster p. 11","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q2 (slide 13) — the desirable properties ⚠️ the trap","origin":"practice","twin":"l02-010"},{"id":"l02-057","chapter":"l02","topic":"Framework & desirable properties","type":"yn","q":"In the world-map example, does the orange box represent p_model?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. The orange box is the model fitted to the training points, p_model, an estimate of p_data. The true p_data is the uniform distribution over the land mass (the gray area).","source":"slides 14, 28 · Foster pp. 10–11 (Figures 1-5, 1-6)","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q3 (slide 28) — the orange box","origin":"practice","twin":"l02-014"},{"id":"l02-058","chapter":"l02","topic":"Framework & desirable properties","type":"yn","q":"Is p_data the distribution that is assumed to have generated the training observations, and is it unknown to us?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. The framework assumes the observations were generated by some unknown distribution p_data, and we build p_model to mimic it. The orange box is p_model, not p_data.","source":"slide 12 · Foster p. 10","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q3 (slide 28) — the orange box","origin":"practice","twin":"l02-014"},{"id":"l02-059","chapter":"l02","topic":"Framework & desirable properties","type":"mcq","q":"In Figure 1-6 of the world-map example, what does the gray area (the land mass of the world) represent?","options":["p_model, the fitted uniform distribution","The sample space of all latitude/longitude pairs","p_data, the true data-generating distribution","The likelihood of the box for the training points"],"answer":2,"fixed":false,"why":"The caption reads: the orange box, p_model, is an estimate of the true data-generating distribution, p_data (the gray area). Confusing the two is exactly her slide-28 trap.","source":"slide 14 · Foster p. 11 (Figure 1-6)","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q3 (slide 28) — the orange box","origin":"practice","twin":"l02-014"},{"id":"l02-060","chapter":"l02","topic":"Sample space, density & parametric models","type":"yn","q":"Can the integral of a probability density function over the entire sample space equal 0?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. It must equal 1 so that the function is a well-defined probability distribution. 0 and ∞ were her distractors.","source":"slide 29 · Foster p. 16","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q4 (slide 29) — probability density and parameter counting","origin":"practice","twin":"l02-020"},{"id":"l02-061","chapter":"l02","topic":"Sample space, density & parametric models","type":"mcq","q":"In Foster's definition, a probability density function p(x) maps each point x in the sample space to…","options":["a label y","a non-negative density value","a point in the latent space","a parameter vector θ"],"answer":1,"fixed":false,"why":"Foster p. 16: a density maps each point x of the sample space to a number, and its integral over the whole sample space must equal 1. (Foster says 'between 0 and 1', but a density can exceed 1 on a tiny region — only the integral is fixed at 1.) Labels and parameters belong to other definitions.","source":"slide 22 · Foster p. 16","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q4 (slide 29) — probability density and parameter counting","origin":"practice","twin":"l02-020"},{"id":"l02-062","chapter":"l02","topic":"Sample space, density & parametric models","type":"yn","q":"Must the density of p_model, not just that of p_data, integrate to 1 over the whole sample space?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Every density function must integrate to 1. That is why the orange-box p_model is set to a constant inside the box chosen so the integral equals 1.","source":"slides 22, 29 · Foster p. 16","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q4 (slide 29) — probability density and parameter counting","origin":"practice","twin":"l02-020"},{"id":"l02-063","chapter":"l02","topic":"Sample space, density & parametric models","type":"mcq","q":"Under the orange-box model, what is the density at a point that lies inside the box but in the sea (like point A)?","options":["The same constant as at every other point inside the box","Zero, because the point is in the sea","Higher than elsewhere, because the point is near the centre","Undefined, because the point is not in the sample space"],"answer":0,"fixed":false,"why":"p_model is uniform: constant everywhere inside the box, whether that is land or sea. It is p_data, not p_model, that is zero in the sea, which is why point A is an accuracy failure.","source":"slides 14, 28 · Foster pp. 11, 16","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q3 (slide 28) — the orange box","origin":"practice","twin":"l02-021"},{"id":"l02-064","chapter":"l02","topic":"Sample space, density & parametric models","type":"yn","q":"Under the orange-box model, is the density at a point outside the box (such as point B, on land) greater than zero?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. The model's density is zero outside the box, so point B could never be generated by p_model even though it lies on land under p_data.","source":"slides 14, 28 · Foster pp. 12, 16","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q3 (slide 28) — the orange box","origin":"practice","twin":"l02-021"},{"id":"l02-065","chapter":"l02","topic":"Sample space, density & parametric models","type":"yn","q":"If the orange box is made larger, does the constant density inside it decrease?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. The density is constant inside and zero outside with the integral fixed at 1, so the constant is 1/area; a larger box spreads the same total over more area.","source":"slide 28 · Foster p. 16","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q3 (slide 28) — the orange box","origin":"practice","twin":"l02-021"},{"id":"l02-066","chapter":"l02","topic":"Sample space, density & parametric models","type":"mcq","q":"In the 2-D world-map example, what are the four parameters θ = (θ₁, θ₂, θ₃, θ₄) of a box?","options":["The density values of p_θ at each of the box's four corners","The bottom-left (θ₁, θ₂) and top-right (θ₃, θ₄) corner coordinates","One coordinate value for each of the four corners of the box","The box's centre point, its width, its height and its area"],"answer":1,"fixed":false,"why":"Foster p. 16: the parameters are the bottom-left (θ₁, θ₂) and top-right (θ₃, θ₄) corners. Listing all four corners would need eight coordinates, and densities are outputs, not parameters.","source":"slides 23, 29 · Foster p. 16","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q4 (slide 29) — probability density and parameter counting","origin":"practice","twin":"l02-022"},{"id":"l02-067","chapter":"l02","topic":"Sample space, density & parametric models","type":"mcq","q":"A uniform box in four dimensions is defined by the coordinates of two opposite corners. How many parameters does this parametric model have?","options":["Four","Six","Eight","Sixteen"],"answer":2,"fixed":false,"why":"Corners × dimensions = 2 × 4 = 8. Four is the 2-D answer from her slide; sixteen counts all 2⁴ corners of a 4-D box.","source":"slide 29 (2-D version) · Foster p. 16","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q4 (slide 29) — probability density and parameter counting","origin":"practice","twin":"l02-022"},{"id":"l02-068","chapter":"l02","topic":"Sample space, density & parametric models","type":"yn","q":"In the 2-D world-map example, can each box (each density p_θ in the parametric model) be uniquely represented by four numbers?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Foster p. 16: each density function in this parametric model can be uniquely represented by θ = (θ₁, θ₂, θ₃, θ₄). Two numbers would fix only one corner.","source":"slide 23 · Foster p. 16","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q4 (slide 29) — probability density and parameter counting","origin":"practice","twin":"l02-022"},{"id":"l02-069","chapter":"l02","topic":"Likelihood & MLE","type":"yn","q":"Is the likelihood L(θ | x) a function of the parameters θ, with the observed data held fixed?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Foster p. 17: the likelihood is a function of the parameters, not the data. Her slide-30 question tested exactly this.","source":"slide 30 · Foster p. 17","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q5 (slide 30) — likelihood and maximum likelihood estimation","origin":"practice","twin":"l02-027"},{"id":"l02-070","chapter":"l02","topic":"Likelihood & MLE","type":"yn","q":"Should the likelihood L(θ | x) be read as the probability that the parameter set θ is correct?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Foster p. 17: it is not a probability distribution over the parameter space and does not integrate to 1 with respect to θ. It is the density of the data under the model parameterised by θ.","source":"slide 24 · Foster p. 17","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q5 (slide 30) — likelihood and maximum likelihood estimation","origin":"practice","twin":"l02-027"},{"id":"l02-071","chapter":"l02","topic":"Likelihood & MLE","type":"mcq","q":"Which statement about the likelihood L(θ | x) is correct?","options":["It is a probability distribution over the parameter space","It integrates to 1 with respect to the parameters θ","It is a function of the data x, with θ held fixed","It equals p_θ(x), the density parameterised by θ at the observed x"],"answer":3,"fixed":false,"why":"By definition L(θ | x) = p_θ(x). It is a function of θ (the data are fixed) and is not a distribution over θ, so it need not integrate to 1 over θ.","source":"slides 24, 30 · Foster p. 17","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q5 (slide 30) — likelihood and maximum likelihood estimation","origin":"practice","twin":"l02-027"},{"id":"l02-072","chapter":"l02","topic":"Likelihood & MLE","type":"yn","q":"A box covers only the left half of the world map, but training points were observed in the right half. Is its likelihood positive?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No, it is 0. Foster p. 17: such a box couldn't possibly have generated the dataset, since points in the right half get density 0 and the product collapses to zero.","source":"slides 24, 30 · Foster p. 17","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q5 (slide 30) — likelihood and maximum likelihood estimation","origin":"practice","twin":"l02-028"},{"id":"l02-073","chapter":"l02","topic":"Likelihood & MLE","type":"mcq","q":"Why is the likelihood zero for a box that misses even one training point?","options":["That point gets density 0, and the likelihood multiplies all the densities","Its log-likelihood becomes a positive number instead of a negative one","The box would then need more than four parameters to describe it","Its density would no longer integrate to 1 over the sample space"],"answer":0,"fixed":false,"why":"L(θ | X) = ∏ p_θ(x); one zero factor makes the whole product zero. The box still has four parameters and its density still integrates to 1.","source":"slides 24, 30 · Foster p. 17","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q5 (slide 30) — likelihood and maximum likelihood estimation","origin":"practice","twin":"l02-028"},{"id":"l02-074","chapter":"l02","topic":"Likelihood & MLE","type":"yn","q":"Does the orange box in Figure 1-5, which contains every training point, have a positive likelihood?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Foster p. 17: it has a positive likelihood because the density is positive at every data point. Likelihood 0 happens only when some observed point gets density 0.","source":"slide 24 · Foster p. 17","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q5 (slide 30) — likelihood and maximum likelihood estimation","origin":"practice","twin":"l02-028"},{"id":"l02-075","chapter":"l02","topic":"Likelihood & MLE","type":"mcq","q":"In the world-map example, why is the largest box, covering the entire map, NOT the maximum likelihood estimate?","options":["It fails to contain some of the training points, so its likelihood is 0","Its constant density is spread over more area, so each point gets lower density","It needs more than four parameters to describe a box that large","Its density integrates to more than 1 when it covers the whole map"],"answer":1,"fixed":false,"why":"The big box does contain every point, but its uniform density (1/area) is tiny, so the product is small. A smaller box that still contains all points scores higher.","source":"slides 26, 30 · Foster pp. 16–18","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q5 (slide 30) — likelihood and maximum likelihood estimation","origin":"practice","twin":"l02-029"},{"id":"l02-076","chapter":"l02","topic":"Likelihood & MLE","type":"yn","q":"Starting from the MLE box, would shrinking it further so that it excludes one training point increase the likelihood?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. The excluded point gets density 0, so the likelihood drops to 0. That is why the MLE is the smallest box that still contains ALL the training points.","source":"slides 26, 30 · Foster pp. 17–18","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q5 (slide 30) — likelihood and maximum likelihood estimation","origin":"practice","twin":"l02-029"},{"id":"l02-077","chapter":"l02","topic":"Likelihood & MLE","type":"mcq","q":"Which of these boxes has the highest likelihood for the world-map training points?","options":["A box of area 5 that contains all the points","A box of area 2 that misses one point","A box of area 10 that contains all the points","A box of area 20 that contains all the points"],"answer":0,"fixed":false,"why":"Among boxes containing every point, the smallest has the highest density 1/area. The area-2 box is smaller, but it misses a point, so its likelihood is 0.","source":"slides 26, 30 · Foster pp. 16–18","study":"lectures/L02-generative-modeling.md — The professor's in-class questions › Q5 (slide 30) — likelihood and maximum likelihood estimation","origin":"practice","twin":"l02-029"},{"id":"l04-001","chapter":"l04","topic":"Unstructured data & deep learning","type":"mcq","q":"Which of the following is an example of unstructured data?","options":["A spreadsheet of product sales by region","A collection of images, audio, or text","A list of website visit counts","A table of customers' ages and incomes"],"answer":1,"fixed":false,"why":"Unstructured data is anything not naturally arranged into columns of features, such as images, audio and text. The other three are structured, tabular data.","source":"slide 10 (def. slide 6) · Foster p. 24","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 10 — unstructured data","origin":"professor"},{"id":"l04-002","chapter":"l04","topic":"Unstructured data & deep learning","type":"yn","q":"Would traditional models like logistic regression or random forests perform well when trained directly on raw pixel values from images?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. These models need input features that are informative on their own and not spatially dependent; a single pixel is almost uninformative, so they perform poorly on all but the simplest tasks.","source":"slides 9–10 · Foster p. 25","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 10 — unstructured data","origin":"professor"},{"id":"l04-003","chapter":"l04","topic":"Unstructured data & deep learning","type":"mcq","q":"Which of these is NOT a reason given for why logistic regression or random forests do poorly on raw pixel values?","options":["An individual pixel is almost entirely uninformative on its own","Raw images contain too few input values for these models to fit","If the object moves, the same feature is carried by completely different pixels","These models rely on input features that are informative and not spatially dependent"],"answer":1,"fixed":false,"why":"The problem is the opposite of too few values: granularity plus high spatial dependence destroys the pixel as an informative feature. The other three are the slide's stated reasons.","source":"slides 7–9 · Foster pp. 24–25","study":"book/B02-deep-learning.md — 1. Data for deep learning","origin":"practice"},{"id":"l04-004","chapter":"l04","topic":"Unstructured data & deep learning","type":"mcq","q":"How does the lecture define deep learning?","options":["ML algorithms using multiple stacked layers of processing units to learn high-level representations from unstructured data","A class of ML algorithms that learns from hand-engineered features arranged into the columns of a structured table","A class of ML algorithms that uses a single layer of processing units to learn a linear combination of its inputs","A class of ML algorithms that uses decision trees stacked in many layers to learn from structured tabular data"],"answer":0,"fixed":false,"why":"Slide 4 word for word: multiple stacked layers, high-level representations, unstructured data. Deep learning needs no feature engineering, so the 'hand-engineered features' option is backwards.","source":"slide 4 · Foster p. 23","study":"lectures/L04-mlp.md — Definitions she gave their own slides","origin":"practice"},{"id":"l04-005","chapter":"l04","topic":"Neural networks & hidden layers","type":"yn","q":"Does backpropagation involve adjusting the network's weights based on the errors made during prediction?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. The prediction error is propagated backward through the network, adjusting each set of weights a small amount in the direction that most improves the prediction.","source":"slides 15–16 · Foster p. 26","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 16 — backpropagation and dense layers","origin":"professor"},{"id":"l04-006","chapter":"l04","topic":"Neural networks & hidden layers","type":"mcq","q":"What is the main function of a fully connected (dense) layer in a neural network?","options":["It connects only a few selected units between layers","It removes redundant features from the data","It outputs the final classification result","It connects every unit in one layer to every unit in the next layer"],"answer":3,"fixed":false,"why":"A dense layer connects every unit to every unit of the adjacent layer. 'Outputs the final result' is the trap: a dense layer can be the output layer, but that is not what makes it dense.","source":"slides 12, 16 · Foster p. 25","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 16 — backpropagation and dense layers","origin":"professor"},{"id":"l04-007","chapter":"l04","topic":"Neural networks & hidden layers","type":"mcq","q":"What is the main advantage of having many hidden layers in a deep neural network?","options":["It increases the training speed of the model","It reduces the need for large datasets","It allows the network to learn progressively higher-level features","It ensures that all weights remain constant during training"],"answer":2,"fixed":false,"why":"Stacking many layers lets the network build progressively higher-level features from the lower-level features of previous layers. More layers make training slower, not faster.","source":"slides 20–21 · Foster p. 27","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 21 — hidden layers","origin":"professor"},{"id":"l04-008","chapter":"l04","topic":"Neural networks & hidden layers","type":"yn","q":"Do hidden layers in a neural network learn low-level features from the high-level features of previous layers?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No, it is the reverse. Each layer combines the lower-level features of the previous layer into higher-level ones. Her question is deliberately inverted.","source":"slides 19–21 · Foster p. 27","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 21 — hidden layers","origin":"professor"},{"id":"l04-009","chapter":"l04","topic":"Neural networks & hidden layers","type":"mcq","q":"In Figure 2-2 (an MLP that predicts whether a face is smiling), what does unit C fire strongest for?","options":["A low-level feature such as an edge","A higher-level feature such as teeth","The person in the image smiling","One channel of one input pixel"],"answer":1,"fixed":false,"why":"A takes one pixel channel, B fires for an edge, C combines low-level features to fire for teeth, and D fires for smiling. Edge (unit B) is the usual mix-up.","source":"slide 18 · Foster p. 27","study":"book/B02-deep-learning.md — 2.2 Learning high-level features","origin":"practice"},{"id":"l04-010","chapter":"l04","topic":"Neural networks & hidden layers","type":"mcq","q":"What are neural networks called when all adjacent layers are fully connected?","options":["Convolutional neural networks","Recurrent neural networks","Multilayer perceptrons (MLPs)","Deep belief networks"],"answer":2,"fixed":false,"why":"Slide 13: networks with all adjacent layers fully connected are MLPs. Deep belief networks appear on slide 11 only as another example of deep learning.","source":"slides 11, 13 · Foster p. 25","study":"book/B02-deep-learning.md — 2.1 What is a neural network?","origin":"practice"},{"id":"l04-011","chapter":"l04","topic":"Supervised learning & data prep","type":"yn","q":"Do supervised learning algorithms require labeled datasets to train a model?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Supervised learning trains on a labeled dataset, input data with corresponding output labels, and learns the mapping between them.","source":"slides 24, 32 · Foster p. 28","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 32 — data preparation","origin":"professor"},{"id":"l04-012","chapter":"l04","topic":"Supervised learning & data prep","type":"yn","q":"Do neural networks work best when input values are scaled to be less than 0.5?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. The rule is that the absolute value of each input is less than 1, which is why CIFAR-10's 0–255 integers are divided by 255. The 0.5 is a planted wrong number.","source":"slides 27, 32 · Foster p. 29","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 32 — data preparation","origin":"professor"},{"id":"l04-013","chapter":"l04","topic":"Supervised learning & data prep","type":"mcq","q":"What do the four dimensions of x_train, shape (50000, 32, 32, 3), represent?","options":["Index of the image, image height, image width, colour channel (RGB)","Number of classes, image height, image width, channel","Index of the pixel, row, column, channel","Image batch, colour channel, height, width"],"answer":0,"fixed":false,"why":"The first dimension indexes the image, the second and third are the image size, and the last is the RGB channel. 50,000 is the number of training images, not classes.","source":"slide 32 · Foster p. 30","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 32 — data preparation","origin":"professor"},{"id":"l04-014","chapter":"l04","topic":"Supervised learning & data prep","type":"yn","q":"Is the multilayer perceptron (MLP) that classifies CIFAR-10 a discriminative model?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 25 says the MLP is discriminative rather than generative; it is taught because supervised learning still plays a role in many generative models later on.","source":"slide 25 · Foster p. 28","study":"lectures/L04-mlp.md — Definitions she gave their own slides","origin":"practice"},{"id":"l04-015","chapter":"l04","topic":"Supervised learning & data prep","type":"mcq","q":"Which description of the CIFAR-10 dataset is correct?","options":["50,000 colour images of 32 × 32 pixels, each in exactly one of 100 classes","60,000 greyscale images of 28 × 28 pixels, each in exactly one of 10 classes","60,000 colour images of 32 × 32 pixels, each in one or more of 10 classes","60,000 colour images of 32 × 32 pixels, each in exactly one of 10 classes"],"answer":3,"fixed":false,"why":"60,000 colour 32 × 32 images, each in exactly one of 10 classes (50,000 of them are the training split). 'Exactly one class' is why softmax and categorical cross-entropy fit.","source":"slide 26 · Foster p. 28","study":"book/B02-deep-learning.md — 3.1 Preparing the data (Example 2-1)","origin":"practice"},{"id":"l04-016","chapter":"l04","topic":"Supervised learning & data prep","type":"mcq","q":"The CIFAR-10 integer labels are converted to one-hot vectors. How long is each one-hot vector?","options":["1","3","10","3,072"],"answer":2,"fixed":false,"why":"One-hot encoding gives a vector whose length is the number of classes, 10, with 1 in the class position and 0 elsewhere. 3,072 is the flattened image length.","source":"slide 28 · Foster pp. 29–30","study":"book/B02-deep-learning.md — 3.1 Preparing the data (Example 2-1)","origin":"practice"},{"id":"l04-017","chapter":"l04","topic":"Keras layers & model building","type":"mcq","q":"Why do we use a Flatten layer before a Dense layer?","options":["To reduce the number of weights in the network","To apply the activation function","To convert the input into a flat vector suitable for Dense layers","To normalize the input values"],"answer":2,"fixed":false,"why":"A Dense layer needs a flat input, so Flatten reshapes the 32 × 32 × 3 image into a 3,072-length vector. It has no weights, so it does not reduce them.","source":"slides 39, 41 · Foster p. 32","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 41 — Flatten and Dense","origin":"professor"},{"id":"l04-018","chapter":"l04","topic":"Keras layers & model building","type":"yn","q":"Does the Dense layer connect every unit in the current layer to every unit in the previous layer through weighted connections?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Every unit in a Dense layer is connected to every unit in the previous layer by a single connection carrying a weight, positive or negative.","source":"slides 40–41 · Foster p. 32","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 41 — Flatten and Dense","origin":"professor"},{"id":"l04-019","chapter":"l04","topic":"Keras layers & model building","type":"mcq","q":"When is the Sequential class NOT suitable, so that the functional API must be used?","options":["When the model has more than three Dense layers in it","When a layer feeds several layers or takes several inputs","When the input images are in colour, not greyscale","When the model is trained on a GPU rather than a CPU"],"answer":1,"fixed":false,"why":"Sequential is only for a linear stack with no branching. When outputs branch or inputs merge, you need the functional API with the Model class. Both give identical models for the simple MLP.","source":"slides 33, 35–37 · Foster pp. 30–31","study":"book/B02-deep-learning.md — 3.2 Building the model (Examples 2-3, 2-4)","origin":"practice"},{"id":"l04-020","chapter":"l04","topic":"Keras layers & model building","type":"yn","q":"Must the batch size be stated explicitly in the Input layer definition?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. You only give the shape of one data element; any number of images can be passed in at once, which is why Keras shows the first dimension as None.","source":"slides 38, 49 · Foster pp. 32, 34","study":"book/B02-deep-learning.md — 3.3 Layers","origin":"practice"},{"id":"l04-021","chapter":"l04","topic":"Keras layers & model building","type":"mcq","q":"Why is the nonlinear activation function in a Dense layer critical?","options":["It lets the network learn complex functions, not just linear combinations","It flattens each unit's output so the next Dense layer accepts it","It keeps every weight positive so that gradients never vanish","It reduces the number of parameters the layer has to train"],"answer":0,"fixed":false,"why":"Slide 40: the activation function ensures the network can learn complex functions and doesn't just output a linear combination of its inputs. Flattening is the Flatten layer's job.","source":"slide 40 · Foster p. 32","study":"book/B02-deep-learning.md — 3.3 Layers","origin":"practice"},{"id":"l04-022","chapter":"l04","topic":"Activation functions","type":"yn","q":"Does the ReLU activation function output 0 for negative input values?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. ReLU is 0 for negative input and otherwise equal to the input.","source":"slides 42, 47 · Foster p. 33","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 47 — activation functions","origin":"professor"},{"id":"l04-023","chapter":"l04","topic":"Activation functions","type":"mcq","q":"Which activation function is typically used in the final layer for multiclass classification to produce probabilities that sum to 1?","options":["Sigmoid","ReLU","LeakyReLU","Softmax"],"answer":3,"fixed":false,"why":"Softmax makes the layer's outputs sum to 1, one probability per class. Sigmoid scales each output to 0–1 separately, which suits binary or multilabel problems.","source":"slides 45, 47 · Foster p. 33","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 47 — activation functions","origin":"professor"},{"id":"l04-024","chapter":"l04","topic":"Activation functions","type":"mcq","q":"What problem does the LeakyReLU activation fix?","options":["Softmax outputs that do not add up to exactly 1 across all units","ReLU units that die: they always output 0, so the gradient is 0","Input values whose absolute value is larger than 1 before scaling","Dense layers whose parameter count becomes too large to train"],"answer":1,"fixed":false,"why":"A ReLU unit with a large negative bias always outputs 0; its gradient is 0 and no error is propagated back. LeakyReLU returns a small negative value proportional to the input, so the gradient stays nonzero.","source":"slide 42 · Foster p. 33","study":"book/B02-deep-learning.md — 3.4 Activation functions","origin":"practice"},{"id":"l04-025","chapter":"l04","topic":"Activation functions","type":"mcq","q":"A model must tag each photo with every object it contains, so one photo can belong to several classes at once. Which final-layer activation fits?","options":["Sigmoid","Softmax","ReLU","LeakyReLU"],"answer":0,"fixed":false,"why":"Sigmoid scales each output to 0–1 independently, which suits multilabel problems. Softmax forces the outputs to sum to 1, which assumes exactly one class per observation.","source":"slides 43, 45 · Foster p. 33","study":"book/B02-deep-learning.md — 3.4 Activation functions","origin":"practice"},{"id":"l04-026","chapter":"l04","topic":"Parameter counts","type":"yn","q":"Does the model.summary() method show the number of parameters (weights) for each layer in a Keras model?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. The summary gives each layer's output shape and the number of parameters trained at that layer, which helps find layers that make training slow.","source":"slides 48, 50–51 · Foster p. 35","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 51 — ★ the parameter-count question","origin":"professor"},{"id":"l04-027","chapter":"l04","topic":"Parameter counts","type":"mcq","q":"In the lecture's MLP, how many parameters does the Dense layer with 200 units have (input: the flattened 32 × 32 × 3 image)?","options":["200","3,072","614,600","646,260"],"answer":2,"fixed":false,"why":"200 × (3,072 + 1) = 614,600: weights plus one bias per unit. 646,260 is the whole model's total, her favourite distractor; 3,072 is the input length.","source":"slides 50–51 · Foster pp. 34–35 (Table 2-1)","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 51 — ★ the parameter-count question","origin":"professor"},{"id":"l04-028","chapter":"l04","topic":"Parameter counts","type":"mcq","q":"In the same MLP, the second Dense layer has 150 units and follows Dense(200). How many parameters does it have?","options":["30,000","30,200","30,351","30,150"],"answer":3,"fixed":false,"why":"150 × (200 + 1) = 30,150. 30,000 forgets the biases, 30,200 adds one bias per input instead of per unit, and 30,351 adds an extra unit on both sides.","source":"Foster p. 34 (Table 2-1) · slide 50 formula","study":"book/B02-deep-learning.md — 3.5 Inspecting the model — Table 2-1 (model.summary())","origin":"practice"},{"id":"l04-029","chapter":"l04","topic":"Parameter counts","type":"mcq","q":"Why is each unit in a Dense layer also connected to a bias unit that always outputs 1?","options":["So the outputs of the layer always add up to 1","So the gradient through the unit is never exactly 0","So the output can be nonzero when all inputs are 0","So the input values stay between 0 and 1 in training"],"answer":2,"fixed":false,"why":"Slide 50: the bias ensures the output from the unit can still be nonzero even when all inputs from the previous layer are 0. Keeping the gradient nonzero is LeakyReLU's job, not the bias's.","source":"slide 50 · Foster p. 35","study":"book/B02-deep-learning.md — 3.5 Inspecting the model — Table 2-1 (model.summary())","origin":"practice"},{"id":"l04-030","chapter":"l04","topic":"Parameter counts","type":"mcq","q":"Exercise 1 (graded) changes the two hidden Dense layers of the CIFAR-10 MLP to 250 and 180 units, keeping Dense(10) as output. How many trainable parameters does the modified model have?","options":["815,240","984,110","768,250","646,260"],"answer":0,"fixed":false,"why":"768,250 + 45,180 + 1,810 = 815,240. 984,110 is the 300/200 version previewed on lecture-1 slide 14; the handout (250/180) is the real task. 768,250 is the first layer only; 646,260 is the original model.","source":"Exercise 1 handout · Foster Table 2-1 method","study":"assignments/exercise-01-mlp.md — Question 1 — total parameters in the modified model","origin":"practice"},{"id":"l04-031","chapter":"l04","topic":"Parameter counts","type":"yn","q":"In Exercise 1, part 2, changing the batch size from 32 to 64 changes the number of trainable parameters of the MLP. Is that true?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Both stay at 646,260; parameters depend only on the architecture. Batch size changes how many observations go through per step, not how many weights there are.","source":"Exercise 1 handout, part 2 Q1 · slide 50","study":"assignments/exercise-01-mlp.md — Exercise 2 — training configuration","origin":"practice"},{"id":"l04-032","chapter":"l04","topic":"Loss functions & optimizers","type":"yn","q":"Is categorical cross-entropy the appropriate loss function for classification problems where each observation belongs to only one class?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. One class of many uses categorical cross-entropy; binary or multilabel uses binary cross-entropy; regression uses mean squared error.","source":"slides 53–57 · Foster p. 36","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 57 — loss functions","origin":"professor"},{"id":"l04-033","chapter":"l04","topic":"Loss functions & optimizers","type":"mcq","q":"Which loss function should be used for a regression problem?","options":["Hinge loss","Categorical cross-entropy","Binary cross-entropy","Mean squared error"],"answer":3,"fixed":false,"why":"A regression problem has a continuous output, so mean squared error is used. The two cross-entropies are for classification.","source":"slide 57 · Foster pp. 35–36","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 57 — loss functions","origin":"professor"},{"id":"l04-034","chapter":"l04","topic":"Loss functions & optimizers","type":"mcq","q":"Which loss should be used for a binary classification problem with one output unit?","options":["Mean squared error","Binary cross-entropy","Categorical cross-entropy","Hinge loss"],"answer":1,"fixed":false,"why":"Binary cross-entropy covers binary classification with one output unit and multilabel problems. Categorical cross-entropy is for one class out of many.","source":"slides 53–56 · Foster p. 36","study":"book/B02-deep-learning.md — 3.7 Loss functions","origin":"practice"},{"id":"l04-035","chapter":"l04","topic":"Loss functions & optimizers","type":"mcq","q":"In most cases, which parameter of the Adam optimizer is worth tuning?","options":["The batch size","The number of epochs","The learning rate","The number of units per layer"],"answer":2,"fixed":false,"why":"Slide 58: you shouldn't need to change Adam's defaults except the learning rate. Batch size and epochs are fit() arguments, not optimizer parameters.","source":"slide 58 · Foster p. 36","study":"book/B02-deep-learning.md — 3.8 Optimizers","origin":"practice"},{"id":"l04-036","chapter":"l04","topic":"Loss functions & optimizers","type":"yn","q":"Does a larger learning rate make training more stable?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. A larger learning rate makes bigger weight changes per step: training is faster at first, but less stable, and it may not find the global minimum of the loss.","source":"slide 58 · Foster p. 36","study":"book/B02-deep-learning.md — 3.8 Optimizers","origin":"practice"},{"id":"l04-037","chapter":"l04","topic":"Training & evaluation","type":"yn","q":"Does the batch_size parameter determine how many times the model sees the full training dataset?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No, that is epochs. batch_size is how many observations are passed through the network in one training step.","source":"slides 62–65 · Foster p. 37","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 65 — batch size","origin":"professor"},{"id":"l04-038","chapter":"l04","topic":"Training & evaluation","type":"mcq","q":"What does the batch_size parameter control during training?","options":["The number of observations processed in each training step","The number of layers in the model","The number of epochs to train the model","The learning rate of the optimizer"],"answer":0,"fixed":false,"why":"batch_size sets how many images are in each training-step batch. The number of passes over the data is epochs.","source":"slides 62, 65 · Foster p. 37","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 65 — batch size","origin":"professor"},{"id":"l04-039","chapter":"l04","topic":"Training & evaluation","type":"mcq","q":"With 50,000 CIFAR-10 training images and batch_size = 64, how many training steps make up one epoch?","options":["781","3,125","1,563","782"],"answer":3,"fixed":false,"why":"50,000 / 64 = 781.25, rounded up to 782 because the last partial batch is still a step. 1,563 is the batch-32 figure from slide 64; 781 forgets the rounding.","source":"Exercise 1 handout, part 2 Q5 · slide 64 (1,563 at batch 32)","study":"assignments/exercise-01-mlp.md — Question 5 — steps per epoch","origin":"practice"},{"id":"l04-040","chapter":"l04","topic":"Training & evaluation","type":"mcq","q":"Which statement about batch size matches the lecture?","options":["Usually 32–256 are used, and it is recommended to increase the batch size as training goes on","Usually 32–256 are used, and it is recommended to decrease the batch size as training goes on","The whole dataset should be used at each step, since it gives the most stable gradient","Usually 1–8 are used, and the batch size should stay fixed for every epoch of training"],"answer":0,"fixed":false,"why":"Slides 62–63: larger batches give a more stable gradient but slower steps; the full dataset is too costly, so 32–256 is typical, and it is now recommended to increase the batch size as training progresses.","source":"slides 62–63 · Foster p. 37","study":"lectures/L04-mlp.md — The two statements the exercise depends on","origin":"practice"},{"id":"l04-041","chapter":"l04","topic":"Training & evaluation","type":"mcq","q":"The MLP reaches 49.0% accuracy on the CIFAR-10 test set. Why does the lecture call this a good result?","options":["It is higher than the model's own training accuracy","Random guessing over 10 classes gives only about 10%","Random guessing over 10 classes gives about 50%","No MLP has ever exceeded 40% on CIFAR-10"],"answer":1,"fixed":false,"why":"With 10 classes, random guessing gives about 10%, so 49.0% on unseen images is good for a very basic network. Training accuracy (51.67%) is higher than test accuracy, not lower.","source":"slide 67 · Foster p. 39","study":"book/B02-deep-learning.md — 3.10 Evaluating the model (Examples 2-9 to 2-11)","origin":"practice"},{"id":"l04-042","chapter":"l04","topic":"Unstructured data & deep learning","type":"mcq","q":"Which of the following is NOT an example of unstructured data?","options":["A recording of someone speaking for ten minutes","A passage of text taken from a news article","A table of each person's age, income and website visits","A folder of photographs taken on a phone"],"answer":2,"fixed":false,"why":"A table arranged into columns of features is structured data. Audio, text and images are the slide's own examples of unstructured data.","source":"slides 5–6 · Foster p. 24","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 10 — unstructured data","origin":"practice","twin":"l04-001"},{"id":"l04-043","chapter":"l04","topic":"Unstructured data & deep learning","type":"mcq","q":"Video has both spatial and temporal structure. Why is it still considered unstructured data?","options":["Because the data does not arrive in columns of features","Because it has no spatial structure at all in its frames","Because each single pixel is highly informative on its own","Because it cannot be stored as an array of numbers"],"answer":0,"fixed":false,"why":"Slide 6: images, audio, text and video do have spatial or temporal structure, but the data does not arrive in columns of features, so it counts as unstructured. Having structure is not what decides it.","source":"slide 6 · Foster p. 24","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 10 — unstructured data","origin":"practice","twin":"l04-001"},{"id":"l04-044","chapter":"l04","topic":"Unstructured data & deep learning","type":"yn","q":"Is an image considered unstructured data, even though it has spatial structure?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 6 says there is spatial structure to an image, but since it does not arrive in columns of features it is unstructured. 'It has structure, so it must be structured' is the trap.","source":"slide 6 · Foster p. 24","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 10 — unstructured data","origin":"practice","twin":"l04-001"},{"id":"l04-045","chapter":"l04","topic":"Unstructured data & deep learning","type":"yn","q":"Can a deep learning model learn to build high-level informative features by itself, directly from unstructured data?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 9 contrasts this with logistic regression and random forests, which need informative, non-spatially-dependent input features.","source":"slide 9 · Foster p. 25","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 10 — unstructured data","origin":"practice","twin":"l04-002"},{"id":"l04-046","chapter":"l04","topic":"Unstructured data & deep learning","type":"yn","q":"Does knowing that pixel 234 of an image is a muddy shade of brown help much in telling whether the image shows a house or a dog?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Slide 7 uses exactly this example: individual pixels are almost entirely uninformative, which is why pixel-based logistic regression or random forests do poorly.","source":"slide 7 · Foster p. 24","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 10 — unstructured data","origin":"practice","twin":"l04-002"},{"id":"l04-047","chapter":"l04","topic":"Unstructured data & deep learning","type":"mcq","q":"If the chimney in an image of a house were moved to the other side of the house, what would happen according to the lecture?","options":["There is no longer a chimney feature anywhere in the image","There is still a chimney, but completely different pixels now carry it","The same pixels as before still carry the chimney information","The image would become structured data with feature columns"],"answer":1,"fixed":false,"why":"Slide 8: the image still contains a chimney, but the information is now carried by completely different pixels. This spatial dependence is why pixel-level models fail.","source":"slide 8 · Foster p. 24","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 10 — unstructured data","origin":"practice","twin":"l04-002"},{"id":"l04-048","chapter":"l04","topic":"Neural networks & hidden layers","type":"yn","q":"In backpropagation, is the prediction error propagated forward from the input layer toward the output layer?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. The error is propagated backward through the network (hence the name). Moving forward from input to output is the forward pass that produces the prediction.","source":"slides 14–15 · Foster p. 26","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 16 — backpropagation and dense layers","origin":"practice","twin":"l04-005"},{"id":"l04-049","chapter":"l04","topic":"Neural networks & hidden layers","type":"yn","q":"Is finding the set of weights for each layer that gives the most accurate predictions what is meant by training the network?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 14: the process of finding these weights is what we mean by training the network; backpropagation is how the weights are adjusted.","source":"slide 14 · Foster p. 26","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 16 — backpropagation and dense layers","origin":"practice","twin":"l04-005"},{"id":"l04-050","chapter":"l04","topic":"Neural networks & hidden layers","type":"mcq","q":"A network outputs 80% for a face that really is smiling and 23% for a face that really is not. What would a perfect prediction output for these two images?","options":["80% and 20%","50% and 50%","100% and 100%","100% and 0%"],"answer":3,"fixed":false,"why":"Slide 15: a perfect prediction would output 100% and 0%, so 80% and 23% leave a small error that backpropagation then reduces. 80%/20% just mirrors the first output.","source":"slide 15 · Foster p. 26","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 16 — backpropagation and dense layers","origin":"practice","twin":"l04-005"},{"id":"l04-051","chapter":"l04","topic":"Neural networks & hidden layers","type":"mcq","q":"Which statement about a fully connected (dense) layer is NOT correct?","options":["Every unit is connected to every unit in the previous layer","Each connection carries a weight that can be positive or negative","Each unit passes a weighted sum of inputs through an activation","Only a few selected units are connected, to cut the weight count"],"answer":3,"fixed":false,"why":"A dense layer connects all units to every unit of the previous layer, which is why it has so many weights. The other three statements are from slides 12 and 40.","source":"slides 12, 40 · Foster pp. 25, 32","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 16 — backpropagation and dense layers","origin":"practice","twin":"l04-006"},{"id":"l04-052","chapter":"l04","topic":"Neural networks & hidden layers","type":"yn","q":"Does a fully connected layer connect only some of the units in one layer to the next layer?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. 'Fully connected' means every unit in the layer is connected directly to every unit in the previous layer. Option A of her question ('only a few selected units') is this same trap.","source":"slide 12 · Foster p. 25","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 16 — backpropagation and dense layers","origin":"practice","twin":"l04-006"},{"id":"l04-053","chapter":"l04","topic":"Neural networks & hidden layers","type":"mcq","q":"During a forward pass, what does each unit of the network do?","options":["Adjusts its weights in the direction that reduces the error","Applies a nonlinear transformation to a weighted sum of its inputs","Removes the redundant features from the data it receives","Outputs one probability for each class in the dataset"],"answer":1,"fixed":false,"why":"Slide 14: each unit applies a nonlinear transformation to a weighted sum of its inputs and passes the result on. Adjusting weights from the error is backpropagation, not the forward pass.","source":"slide 14 · Foster p. 26","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 16 — backpropagation and dense layers","origin":"practice","twin":"l04-006"},{"id":"l04-054","chapter":"l04","topic":"Neural networks & hidden layers","type":"mcq","q":"Which of these statements about hidden layers is NOT correct?","options":["We must tell each unit whether to look for low- or high-level features","They are the layers between the input and the output layers","Stacking many of them builds progressively higher-level features","Deep networks can have many; ResNet, for example, has 152 layers"],"answer":0,"fixed":false,"why":"Slide 19: the feature hierarchy arises naturally from training, and we do not need to tell each unit what to look for. The other three are stated on slide 20.","source":"slides 19–20 · Foster p. 27","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 21 — hidden layers","origin":"practice","twin":"l04-007"},{"id":"l04-055","chapter":"l04","topic":"Neural networks & hidden layers","type":"mcq","q":"The lecture gives ResNet, designed for image recognition, as an example of a very deep network. How many layers does it contain?","options":["2","200","152","1,563"],"answer":2,"fixed":false,"why":"Slide 20: ResNet contains 152 layers. 2 is the number of hidden layers in the Figure 2-2 example, 200 is a Dense layer's unit count, and 1,563 is the batches per epoch.","source":"slide 20 · Foster p. 27","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 21 — hidden layers","origin":"practice","twin":"l04-007"},{"id":"l04-056","chapter":"l04","topic":"Neural networks & hidden layers","type":"yn","q":"Do you need to do feature engineering by hand before training a neural network, so it knows which features to learn?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Slide 17: neural networks learn features from the input data without human guidance, so no feature engineering is needed. That is the reason stacking hidden layers is so powerful.","source":"slide 17 · Foster p. 26","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 21 — hidden layers","origin":"practice","twin":"l04-007"},{"id":"l04-057","chapter":"l04","topic":"Neural networks & hidden layers","type":"yn","q":"Do units in each subsequent layer represent increasingly sophisticated aspects of the input, by combining lower-level features from the previous layer?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes, this is the correct direction: low-level in, higher-level out. Her slide-21 question flipped it (low-level from high-level), and the answer there was No.","source":"slide 19 · Foster p. 27","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 21 — hidden layers","origin":"practice","twin":"l04-008"},{"id":"l04-058","chapter":"l04","topic":"Neural networks & hidden layers","type":"yn","q":"In Figure 2-2, does unit B combine high-level features so that it fires strongest when the person in the image is smiling?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Unit B fires for a low-level feature such as an edge; it is unit D that combines high-level features to fire for smiling.","source":"slide 18 · Foster p. 27","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 21 — hidden layers","origin":"practice","twin":"l04-008"},{"id":"l04-059","chapter":"l04","topic":"Neural networks & hidden layers","type":"mcq","q":"In Figure 2-2, which unit receives the value for an individual channel of an input pixel?","options":["Unit A","Unit B","Unit C","Unit D"],"answer":0,"fixed":false,"why":"Unit A is the input unit: one channel of one pixel. B finds an edge, C finds teeth from low-level features, D finds smiling from high-level features, so features rise from A to D.","source":"slide 18 · Foster p. 27","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 21 — hidden layers","origin":"practice","twin":"l04-008"},{"id":"l04-060","chapter":"l04","topic":"Supervised learning & data prep","type":"yn","q":"In supervised learning, does the training dataset contain only input data, with no corresponding output labels?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Supervised learning trains on a labeled dataset: input data with corresponding output labels. Data without labels would not be supervised.","source":"slide 24 · Foster p. 28","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 32 — data preparation","origin":"practice","twin":"l04-011"},{"id":"l04-061","chapter":"l04","topic":"Supervised learning & data prep","type":"mcq","q":"What is the goal of a supervised learning algorithm, according to the lecture?","options":["Generate new images that look like the training images","Group the unlabeled inputs into clusters of similar items","Learn a mapping from inputs to labels to predict on new, unseen data","Memorise the training labels so they can be looked up later"],"answer":2,"fixed":false,"why":"Slide 24: the goal is to learn a mapping between the input data and the output labels so the model can predict on new, unseen data. Generating new images is the generative-model goal, not this MLP's.","source":"slide 24 · Foster p. 28","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 32 — data preparation","origin":"practice","twin":"l04-011"},{"id":"l04-062","chapter":"l04","topic":"Supervised learning & data prep","type":"yn","q":"Is the CIFAR-10 MLP trained with supervised learning, using the class labels in y_train?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 24: the MLP is trained to classify images using supervised learning, and y_train holds the one-hot labels passed to fit() alongside x_train.","source":"slides 24, 61 · Foster pp. 28, 37","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 32 — data preparation","origin":"practice","twin":"l04-011"},{"id":"l04-063","chapter":"l04","topic":"Supervised learning & data prep","type":"yn","q":"Do neural networks work best when the absolute value of each input is less than 1?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes, this is the real rule from slide 27. Her slide-32 version said 'less than 0.5', which is why that one was No.","source":"slide 27 · Foster p. 29","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 32 — data preparation","origin":"practice","twin":"l04-012"},{"id":"l04-064","chapter":"l04","topic":"Supervised learning & data prep","type":"mcq","q":"CIFAR-10 pixel channels are integers from 0 to 255. What preprocessing does the lecture apply to them?","options":["Divide by 510 so each value lies below 0.5","Subtract 128 so values lie from −128 to 127","Divide by 2 so each value lies below 128","Divide by 255 so each value lies between 0 and 1"],"answer":3,"fixed":false,"why":"Example 2-1 divides by 255.0, scaling values to between 0 and 1 because networks work best with |input| < 1. Dividing by 510 echoes her planted 0.5 number.","source":"slides 27, 29 · Foster pp. 29–30","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 32 — data preparation","origin":"practice","twin":"l04-012"},{"id":"l04-065","chapter":"l04","topic":"Supervised learning & data prep","type":"mcq","q":"After scaling, x_train[54, 12, 13, 1] returns 0.36862746. Which raw integer value did that pixel channel have before preprocessing?","options":["37","94","255","0.37"],"answer":1,"fixed":false,"why":"The scaled value is the raw integer divided by 255, so 0.36862746 × 255 = 94. 0.37 is just the scaled value rounded, and 37 confuses it with a percentage.","source":"slide 31 · Foster p. 30 (Example 2-2)","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 32 — data preparation","origin":"practice","twin":"l04-012"},{"id":"l04-066","chapter":"l04","topic":"Supervised learning & data prep","type":"mcq","q":"A greyscale digit dataset has x_train of shape (60000, 28, 28, 1). What does the last dimension, 1, represent?","options":["The number of classes each image belongs to","The batch size used at each training step","The number of colour channels (one, greyscale)","The index of the image within the dataset"],"answer":2,"fixed":false,"why":"Same layout as CIFAR-10: index of the image, height, width, channel. CIFAR-10 has 3 channels (RGB); a greyscale image has only 1.","source":"slide 30, 32 · Foster p. 30","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 32 — data preparation","origin":"practice","twin":"l04-013"},{"id":"l04-067","chapter":"l04","topic":"Supervised learning & data prep","type":"mcq","q":"What is the shape of x_test for CIFAR-10, as loaded in Example 2-1?","options":["(50000, 32, 32, 3)","(10000, 3072)","(10000, 10)","(10000, 32, 32, 3)"],"answer":3,"fixed":false,"why":"x_test holds the 10,000 test images in the same layout as x_train. (50000, 32, 32, 3) is x_train, (10000, 10) is the one-hot y_test, and 3,072 appears only after Flatten.","source":"slides 29–30 · Foster p. 30","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 32 — data preparation","origin":"practice","twin":"l04-013"},{"id":"l04-068","chapter":"l04","topic":"Supervised learning & data prep","type":"yn","q":"In x_train[54, 12, 13, 1], does the final index 1 select the green channel of that pixel?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. The last dimension is the RGB channel, indexed 0 = red, 1 = green, 2 = blue; Example 2-2 is titled 'the green channel (1) value of the pixel in the (12,13) position of image 54'.","source":"slide 31 · Foster p. 30","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 32 — data preparation","origin":"practice","twin":"l04-013"},{"id":"l04-069","chapter":"l04","topic":"Keras layers & model building","type":"mcq","q":"A Flatten layer receives a 28 × 28 × 1 greyscale image. How long is the vector it outputs?","options":["784","56","2,352","3,072"],"answer":0,"fixed":false,"why":"Flatten multiplies out every dimension: 28 × 28 × 1 = 784. 2,352 wrongly assumes three colour channels and 3,072 is the CIFAR-10 figure.","source":"slide 39 · Foster p. 32","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 41 — Flatten and Dense","origin":"practice","twin":"l04-017"},{"id":"l04-070","chapter":"l04","topic":"Keras layers & model building","type":"yn","q":"Does the Flatten layer add trainable parameters to the model?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Flatten only reshapes the input; model.summary() lists 0 parameters for it. That is why 'to reduce the number of weights' was a wrong answer in her question too.","source":"slides 39, 48 · Foster pp. 32, 34 (Table 2-1)","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 41 — Flatten and Dense","origin":"practice","twin":"l04-017"},{"id":"l04-071","chapter":"l04","topic":"Keras layers & model building","type":"mcq","q":"In model.summary() for the lecture's MLP, what output shape is shown for the Flatten layer?","options":["(None, 32, 32, 3)","(None, 3072)","(32, 3072)","(None, 200)"],"answer":1,"fixed":false,"why":"Flatten turns the 32 × 32 × 3 input into a 3,072-length vector, and Keras shows the unknown number of observations as None. (None, 32, 32, 3) is the Input layer; (None, 200) is the first Dense layer.","source":"slides 48–49 · Foster p. 34 (Table 2-1)","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 41 — Flatten and Dense","origin":"practice","twin":"l04-017"},{"id":"l04-072","chapter":"l04","topic":"Keras layers & model building","type":"yn","q":"Is the output of a Dense unit just the weighted sum of its inputs, sent on with no activation function applied?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. The weighted sum is passed through a nonlinear activation function before being sent on; without it the network would only output a linear combination of its inputs.","source":"slide 40 · Foster p. 32","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 41 — Flatten and Dense","origin":"practice","twin":"l04-018"},{"id":"l04-073","chapter":"l04","topic":"Keras layers & model building","type":"yn","q":"Can the weight on a connection in a Dense layer be negative?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 40: every unit is connected to every unit in the previous layer through a single connection that carries a weight, which can be positive or negative.","source":"slide 40 · Foster p. 32","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 41 — Flatten and Dense","origin":"practice","twin":"l04-018"},{"id":"l04-074","chapter":"l04","topic":"Keras layers & model building","type":"mcq","q":"A Dense(64) layer follows a layer of 100 units. Not counting biases, how many weighted connections link the two layers?","options":["164","6,464","6,400","6,500"],"answer":2,"fixed":false,"why":"Every one of the 64 units connects to every one of the 100 previous units: 64 × 100 = 6,400. 6,464 also adds the 64 biases, which the question excludes, and 164 adds instead of multiplying.","source":"slide 40 · Foster p. 32","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 41 — Flatten and Dense","origin":"practice","twin":"l04-018"},{"id":"l04-075","chapter":"l04","topic":"Activation functions","type":"yn","q":"Does ReLU output a small negative number proportional to the input when the input is negative?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No, that describes LeakyReLU. ReLU outputs 0 for any negative input.","source":"slide 42 · Foster p. 33","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 47 — activation functions","origin":"practice","twin":"l04-022"},{"id":"l04-076","chapter":"l04","topic":"Activation functions","type":"mcq","q":"What does the ReLU activation output for the inputs −3 and 2?","options":["0 and 2","−3 and 2","0 and 0","A small negative value and 2"],"answer":0,"fixed":false,"why":"ReLU is 0 for negative input and otherwise equal to the input, so −3 → 0 and 2 → 2. 'A small negative value' is what LeakyReLU gives for −3.","source":"slide 42 · Foster p. 33","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 47 — activation functions","origin":"practice","twin":"l04-022"},{"id":"l04-077","chapter":"l04","topic":"Activation functions","type":"yn","q":"Does LeakyReLU always keep the gradient nonzero, so the unit cannot die the way a ReLU unit can?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. A ReLU unit that always outputs 0 has gradient 0 and propagates no error back; LeakyReLU fixes this by always ensuring the gradient is nonzero.","source":"slide 42 · Foster p. 33","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 47 — activation functions","origin":"practice","twin":"l04-022"},{"id":"l04-078","chapter":"l04","topic":"Activation functions","type":"mcq","q":"Which activation is used in the final layer for a binary classification problem with one output unit?","options":["Softmax","ReLU","LeakyReLU","Sigmoid"],"answer":3,"fixed":false,"why":"Sigmoid scales the output to between 0 and 1, which suits binary classification with one output unit. Softmax is for one-of-many multiclass outputs that must sum to 1.","source":"slide 43 · Foster p. 33","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 47 — activation functions","origin":"practice","twin":"l04-023"},{"id":"l04-079","chapter":"l04","topic":"Activation functions","type":"mcq","q":"Which activations does the lecture call among the most reliable between the layers of a deep network, to encourage stable training?","options":["Softmax functions","ReLU-based functions","Sigmoid functions","No activation at all"],"answer":1,"fixed":false,"why":"Slide 42: ReLU-based functions are among the most reliable activations between layers. Softmax belongs in the final layer of a multiclass classifier, not between layers.","source":"slide 42 · Foster p. 33","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 47 — activation functions","origin":"practice","twin":"l04-023"},{"id":"l04-080","chapter":"l04","topic":"Activation functions","type":"yn","q":"Do the outputs of a sigmoid final layer with several units always sum to 1?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Sigmoid scales each output to between 0 and 1 on its own, so they need not sum to 1 (that is why it suits multilabel problems). Softmax is the one that makes the total equal 1.","source":"slides 43, 45 · Foster p. 33","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 47 — activation functions","origin":"practice","twin":"l04-023"},{"id":"l04-081","chapter":"l04","topic":"Parameter counts","type":"yn","q":"In model.summary(), does Keras show None as the first dimension because it does not yet know how many observations will be passed in?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 49: None marks the first dimension because the number of observations is not known yet, and it doesn't need to be: 1 or 1,000 observations work the same.","source":"slide 49 · Foster p. 34","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 51 — ★ the parameter-count question","origin":"practice","twin":"l04-026"},{"id":"l04-082","chapter":"l04","topic":"Parameter counts","type":"yn","q":"Does model.summary() report the number of epochs the model has been trained for?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. The summary shows each layer's output shape and its number of parameters (weights). Epochs are an argument of fit(), not part of the model's structure.","source":"slides 48, 50 · Foster pp. 34–35","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 51 — ★ the parameter-count question","origin":"practice","twin":"l04-026"},{"id":"l04-083","chapter":"l04","topic":"Parameter counts","type":"mcq","q":"Your model is training too slowly. What does the lecture tell you to look for in model.summary()?","options":["Layers with a huge number of weights, whose units you could reduce","A Flatten layer that holds too many trainable parameters","A batch size in the first dimension that is set too large","A learning rate shown for each layer that is set too high"],"answer":0,"fixed":false,"why":"Slide 50: check the summary for layers with a huge number of weights and consider reducing their units. Flatten has 0 parameters, and the summary shows neither batch size (None) nor the learning rate.","source":"slide 50 · Foster p. 35","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 51 — ★ the parameter-count question","origin":"practice","twin":"l04-026"},{"id":"l04-084","chapter":"l04","topic":"Parameter counts","type":"mcq","q":"In the lecture's MLP, how many parameters does the output Dense layer with 10 units have (it follows Dense(150))?","options":["1,500","1,510","1,650","646,260"],"answer":1,"fixed":false,"why":"10 × (150 + 1) = 1,510: 150 weights plus one bias for each of the 10 units. 1,500 forgets the biases, 1,650 swaps units and inputs, and 646,260 is the whole model.","source":"slide 50 formula · Foster p. 34 (Table 2-1)","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 51 — ★ the parameter-count question","origin":"practice","twin":"l04-027"},{"id":"l04-085","chapter":"l04","topic":"Parameter counts","type":"mcq","q":"A model flattens 28 × 28 × 1 greyscale images and passes them to Dense(128). How many parameters does that Dense layer have?","options":["100,352","101,136","784","100,480"],"answer":3,"fixed":false,"why":"28 × 28 × 1 = 784 inputs, so 128 × (784 + 1) = 100,480. 100,352 forgets the 128 biases, 101,136 adds a bias per input instead of per unit, and 784 is just the input length.","source":"slide 50 formula · Foster p. 35","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 51 — ★ the parameter-count question","origin":"practice","twin":"l04-027"},{"id":"l04-086","chapter":"l04","topic":"Parameter counts","type":"yn","q":"A Dense layer with 50 units receives the flattened 32 × 32 × 3 CIFAR-10 image. Does it have 153,650 parameters?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. 50 × (3,072 + 1) = 153,650. Without the bias you would get 153,600, the classic slip.","source":"slide 50 formula · Foster p. 35","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 51 — ★ the parameter-count question","origin":"practice","twin":"l04-027"},{"id":"l04-087","chapter":"l04","topic":"Loss functions & optimizers","type":"yn","q":"Is categorical cross-entropy the right loss when each observation can belong to several classes at once (a multilabel problem)?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Multilabel problems, like binary classification with one output unit, use binary cross-entropy. Categorical cross-entropy is for observations that belong to exactly one class.","source":"slides 53–56 · Foster p. 36","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 57 — loss functions","origin":"practice","twin":"l04-032"},{"id":"l04-088","chapter":"l04","topic":"Loss functions & optimizers","type":"yn","q":"Does a loss function return a single number for each observation, where a larger number means the network did worse?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 53: the loss compares prediction with ground truth and returns one number per observation; the greater the number, the worse the performance.","source":"slide 53 · Foster p. 35","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 57 — loss functions","origin":"practice","twin":"l04-032"},{"id":"l04-089","chapter":"l04","topic":"Loss functions & optimizers","type":"mcq","q":"Which loss does the lecture's CIFAR-10 MLP pass to model.compile()?","options":["binary_crossentropy","mean_squared_error","categorical_crossentropy","hinge"],"answer":2,"fixed":false,"why":"Example 2-7 compiles with loss='categorical_crossentropy', because each CIFAR-10 image belongs to exactly one of 10 classes. Binary cross-entropy would suit binary or multilabel problems.","source":"slide 52 · Foster p. 35 (Example 2-7)","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 57 — loss functions","origin":"practice","twin":"l04-032"},{"id":"l04-090","chapter":"l04","topic":"Loss functions & optimizers","type":"mcq","q":"Which pairing of problem type and loss function is WRONG?","options":["Regression with a continuous output → mean squared error","Exactly one class out of many → categorical cross-entropy","Multilabel classification → binary cross-entropy","Binary classification, one output unit → mean squared error"],"answer":3,"fixed":false,"why":"Binary classification with one output unit uses binary cross-entropy. MSE is for regression, where the output is continuous; the other three pairings are the lecture's rule.","source":"slides 53–56 · Foster pp. 35–36","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 57 — loss functions","origin":"practice","twin":"l04-033"},{"id":"l04-091","chapter":"l04","topic":"Loss functions & optimizers","type":"mcq","q":"Mean squared error, the regression loss, is the mean over all output units of what?","options":["The squared difference between ground truth and prediction","The absolute difference between ground truth and prediction","Minus the ground truth times the log of the prediction","The squared prediction, without using the ground truth"],"answer":0,"fixed":false,"why":"MSE = (1/n) Σ (yᵢ − pᵢ)², the squared difference between the ground truth yᵢ and prediction pᵢ. −y log p is the cross-entropy term, used for classification.","source":"slides 54–55 (MSE slide 54, cross-entropy slide 55) · Foster pp. 35–36","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 57 — loss functions","origin":"practice","twin":"l04-033"},{"id":"l04-092","chapter":"l04","topic":"Loss functions & optimizers","type":"yn","q":"Is mean squared error the loss to use when the network's output is continuous?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. A continuous output means a regression problem, and the lecture uses mean squared error for regression. The cross-entropies are for classification.","source":"slides 53–54 · Foster p. 35","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 57 — loss functions","origin":"practice","twin":"l04-033"},{"id":"l04-093","chapter":"l04","topic":"Training & evaluation","type":"yn","q":"Does the epochs parameter determine how many times the network is shown the full training data?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes, that is epochs. Her slide-65 question attached this to batch_size, which was wrong: batch_size is the number of observations per training step.","source":"slides 61, 63 · Foster p. 37","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 65 — batch size","origin":"practice","twin":"l04-037"},{"id":"l04-094","chapter":"l04","topic":"Training & evaluation","type":"mcq","q":"CIFAR-10 has 50,000 training images. With batch_size = 32 and epochs = 10, how many training steps are run in total?","options":["1,563","15,625","15,630","500,000"],"answer":2,"fixed":false,"why":"One epoch is 50,000 / 32 = 1,562.5, rounded up to 1,563 steps (slide 64), so 10 epochs give 15,630. 15,625 forgets the last partial batch; 500,000 counts images, not steps.","source":"slides 63–64 · Foster p. 38","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 65 — batch size","origin":"practice","twin":"l04-037"},{"id":"l04-095","chapter":"l04","topic":"Training & evaluation","type":"yn","q":"Does raising epochs from 10 to 20 change the number of images in each training step?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. The number of images per step is batch_size; epochs only sets how many full passes over the training data are made.","source":"slides 61–63 · Foster p. 37","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 65 — batch size","origin":"practice","twin":"l04-037"},{"id":"l04-096","chapter":"l04","topic":"Training & evaluation","type":"mcq","q":"According to the lecture, what happens as the batch size gets larger?","options":["The gradient is less stable, but each training step is faster","The gradient is more stable, but each training step is slower","The gradient is more stable, and each step is also faster","The model has fewer parameters, so each step is faster"],"answer":1,"fixed":false,"why":"Slide 62: the larger the batch size, the more stable the gradient calculation, but the slower each training step. Batch size never changes the parameter count.","source":"slide 62 · Foster p. 37","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 65 — batch size","origin":"practice","twin":"l04-038"},{"id":"l04-097","chapter":"l04","topic":"Training & evaluation","type":"mcq","q":"In model.fit(x_train, y_train, batch_size=32, epochs=10, shuffle=True), what does shuffle=True do?","options":["Draws batches randomly, without replacement, at each training step","Draws batches randomly, with replacement, at each training step","Shuffles the class labels so the model cannot memorise them","Shuffles the order of the layers before each new epoch begins"],"answer":0,"fixed":false,"why":"Example 2-8: if shuffle=True, the batches are drawn randomly without replacement from the training data at each step. 'With replacement' is the subtle wrong half.","source":"slide 61 · Foster p. 37 (Example 2-8)","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 65 — batch size","origin":"practice","twin":"l04-038"},{"id":"l04-098","chapter":"l04","topic":"Training & evaluation","type":"yn","q":"Is it recommended practice to decrease the batch size as training progresses?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No, the reverse. Slide 63: a batch size between 32 and 256 is generally used, and it is now recommended practice to increase the batch size as training progresses.","source":"slide 63 · Foster p. 37","study":"lectures/L04-mlp.md — Her nineteen questions, with answers › Slide 65 — batch size","origin":"practice","twin":"l04-038"},{"id":"l05-001","chapter":"l05","topic":"Convolution & filters","type":"yn","q":"Does the convolution output become more positive when the image portion is the inverse of the filter?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — more negative. The output is more positive when the patch closely matches the filter and more negative when it is the filter's inverse; the question inverts the true statement.","source":"slides 5, 9 · Foster p. 41","study":"lectures/L05-cnn.md — ★★★ Her eleven questions, with answers (slide 9)","origin":"professor"},{"id":"l05-002","chapter":"l05","topic":"Convolution & filters","type":"mcq","q":"What operation is used to perform a convolution in deep learning?","options":["Subtraction of pixel values","Division of filter and image values","Addition of pixel values without weighting","Pixelwise multiplication followed by summation"],"answer":3,"fixed":false,"why":"The filter is multiplied pixelwise with the image portion and the results are summed. 'Addition without weighting' is the near-miss: there is a sum, but each pixel is first weighted by the filter value.","source":"slides 5, 9 · Foster p. 41","study":"lectures/L05-cnn.md — ★★★ Her eleven questions, with answers (slide 9)","origin":"professor"},{"id":"l05-003","chapter":"l05","topic":"Convolution & filters","type":"mcq","q":"A filter with rows (1, 1, 1 / 0, 0, 0 / −1, −1, −1) is applied to the patch (0.6, 0.4, 0.6 / 0.1, −0.2, −0.3 / −0.5, −0.4, −0.3). What is the output?","options":["−0.1","0.4","1.6","2.8"],"answer":3,"fixed":false,"why":"(0.6+0.4+0.6)·1 + 0 + (−0.5−0.4−0.3)·(−1) = 1.6 + 1.2 = 2.8 (Figure 2-10, top). 1.6 forgets the bottom row; −0.1 is the printed value for the other (bottom) patch.","source":"slide 5 (Figure 2-10) · Foster p. 41","study":"lectures/L05-cnn.md — Worked examples (Figure 2-10)","origin":"practice"},{"id":"l05-004","chapter":"l05","topic":"Convolution & filters","type":"mcq","q":"According to slide 4, why does the MLP not perform as well as it might on images?","options":["It has too few parameters to fit CIFAR-10","Nothing in it takes account of the spatial structure of the input — its first step flattens the image","It uses softmax instead of sigmoid in the output layer","Its pixel values are not scaled before training"],"answer":1,"fixed":false,"why":"Slide 4: the first step of the MLP is to flatten the image into a single vector, so the spatial structure is lost; convolutional layers fix that. The MLP actually has more parameters than the CNN (646,260 vs 592,554).","source":"slide 4 · Foster p. 40","study":"lectures/L05-cnn.md — Key concepts (Why a CNN, slide 4)","origin":"practice"},{"id":"l05-005","chapter":"l05","topic":"Convolution & filters","type":"yn","q":"Are the values stored in a convolutional layer's filters weights that the network learns through training, starting from random values?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 7: a convolutional layer is a collection of filters whose values are the weights learned in training — random at first, then adapting to features such as edges or colour combinations.","source":"slide 7 · Foster p. 42","study":"lectures/L05-cnn.md — Key concepts (Convolution, slides 5–8)","origin":"practice"},{"id":"l05-006","chapter":"l05","topic":"Convolution & filters","type":"mcq","q":"In Figure 2-11, a 1 × 64 × 64 × 1 grayscale image is passed through a Conv2D layer with two 3 × 3 × 1 filters (strides = 1, padding = 'same'). What is the output shape?","options":["1 × 64 × 64 × 2","1 × 62 × 62 × 2","1 × 64 × 64 × 1","2 × 64 × 64 × 1"],"answer":0,"fixed":false,"why":"Same padding with stride 1 keeps 64 × 64, and the number of output channels equals the number of filters (2). 62 × 62 would be 'valid' padding; putting the 2 in the batch position confuses filters with images.","source":"slide 6 (Figure 2-11) · Foster p. 42","study":"lectures/L05-cnn.md — Key concepts (Convolution, slides 5–8)","origin":"practice"},{"id":"l05-007","chapter":"l05","topic":"Convolution & filters","type":"mcq","q":"In Figure 2-11, which feature does the filter with rows (1, 1, 1 / 0, 0, 0 / −1, −1, −1) highlight?","options":["Vertical edges","Diagonal edges","Horizontal edges","Areas of uniform colour"],"answer":2,"fixed":false,"why":"Its rows change from +1 at the top to −1 at the bottom, so it responds to a bright-above/dark-below change: a horizontal edge. Its transpose (−1 0 1 in every row) is the vertical-edge filter.","source":"slide 6 (Figure 2-11) · Foster p. 42","study":"book/B02-deep-learning.md — §4.1 Convolutional layers","origin":"practice"},{"id":"l05-008","chapter":"l05","topic":"Stride & padding","type":"yn","q":"Does setting padding = 'same' ensure that the output tensor has the same spatial dimensions as the input when stride = 1?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — that is the definition on slide 11: zero-padding so the output size is exactly the input size when strides = 1. With stride 2 the output is halved instead.","source":"slides 11, 18 · Foster p. 43","study":"lectures/L05-cnn.md — ★★★ Her eleven questions, with answers (slide 18)","origin":"professor"},{"id":"l05-009","chapter":"l05","topic":"Stride & padding","type":"mcq","q":"When stride = 2 (padding = 'same'), what happens to the height and width of the output tensor compared to the input?","options":["They double in size","They stay the same","They are reduced by half","They increase by one"],"answer":2,"fixed":false,"why":"Slide 10: with strides = 2 the output height and width are half the input's. Doubling is what a Conv2DTranspose with stride 2 does (the autoencoder's decoder) — don't swap them.","source":"slides 10, 18 · Foster p. 42","study":"lectures/L05-cnn.md — ★★★ Her eleven questions, with answers (slide 18)","origin":"professor"},{"id":"l05-010","chapter":"l05","topic":"Stride & padding","type":"mcq","q":"Conv2D(20 filters, 3 × 3, strides = 2, padding = 'same') is applied to a (16, 16, 10) tensor. What is the output shape?","options":["(8, 8, 20)","(16, 16, 20)","(8, 8, 10)","(14, 14, 20)"],"answer":0,"fixed":false,"why":"Stride 2 with 'same' halves 16 → 8; the number of channels equals the number of filters, 20. (8, 8, 10) keeps the input channels by mistake; 14 would be 'valid' padding with stride 1.","source":"slide 22 (Table 2-2) · Foster p. 46","study":"lectures/L05-cnn.md — Formulas","origin":"practice"},{"id":"l05-011","chapter":"l05","topic":"Stride & padding","type":"mcq","q":"A 3 × 3 kernel is passed over a 5 × 5 input image with strides = 1 and NO padding. What is the output size?","options":["5 × 5","4 × 4","2 × 2","3 × 3"],"answer":3,"fixed":false,"why":"Slide 12 (Figure 2-12): without padding the kernel fits only three times along each direction → 3 × 3. With padding = 'same' it fits five times → 5 × 5.","source":"slide 12 (Figure 2-12) · Foster p. 43","study":"lectures/L05-cnn.md — Key concepts (Padding, slides 11–13)","origin":"practice"},{"id":"l05-012","chapter":"l05","topic":"Stride & padding","type":"yn","q":"Does increasing the stride of a convolutional layer increase the size of the output tensor?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — the stride is the step size of the filter, so a larger stride gives fewer positions and a smaller output (slide 10). Growing the tensor is the job of Conv2DTranspose.","source":"slide 10 · Foster p. 42","study":"lectures/L05-cnn.md — Key concepts (Stride, slide 10)","origin":"practice"},{"id":"l05-013","chapter":"l05","topic":"Stride & padding","type":"mcq","q":"According to slide 10, why are stride-2 convolutions useful as data passes through the network?","options":["They reduce the spatial size of the tensor while the number of channels increases","They increase the spatial size of the tensor while the number of channels decreases","They keep the spatial size fixed so the tensor is easy to track","They prevent the network from overfitting by dropping pixels"],"answer":0,"fixed":false,"why":"Slide 10: striding reduces the spatial size of the tensor as it passes through the network, while increasing the number of channels. Keeping the size fixed is what padding = 'same' with stride 1 does.","source":"slide 10 · Foster p. 42","study":"lectures/L05-cnn.md — Key concepts (Stride, slide 10)","origin":"practice"},{"id":"l05-014","chapter":"l05","topic":"Shapes & parameter counts","type":"yn","q":"In Example 2-13 (the first CNN), do both convolutional layers use padding = 'same' and strides = 1?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Both use padding = 'same' but strides = 2 — that is why the size goes 32 → 16 → 8. A half-true compound: one wrong part makes the whole statement false.","source":"slides 21–22, 25 · Foster pp. 44–46","study":"lectures/L05-cnn.md — ★★★ Her eleven questions, with answers (slide 25)","origin":"professor"},{"id":"l05-015","chapter":"l05","topic":"Shapes & parameter counts","type":"mcq","q":"In Example 2-13, what does the final Dense layer with softmax activation represent?","options":["It performs convolution on the image","It outputs probabilities for each category in a classification task","It flattens the tensor into a single vector","It normalizes the input data"],"answer":1,"fixed":false,"why":"Slide 23: the 10-unit Dense layer with softmax represents the probability of each category in a 10-category task. Flattening is done by the separate Flatten layer.","source":"slides 23, 25 · Foster p. 46","study":"lectures/L05-cnn.md — ★★★ Her eleven questions, with answers (slide 25)","origin":"professor"},{"id":"l05-016","chapter":"l05","topic":"Shapes & parameter counts","type":"mcq","q":"How many parameters does Conv2D(10 filters, kernel 4 × 4) have on a 32 × 32 × 3 input?","options":["160","480","490","1,820"],"answer":2,"fixed":false,"why":"(4·4·3 + 1)·10 = 490 — the +1 is one bias per filter. 480 forgets the biases; 1,820 is the next layer.","source":"slide 21 (Table 2-2) · Foster p. 45","study":"lectures/L05-cnn.md — Worked examples (Table 2-2)","origin":"practice"},{"id":"l05-017","chapter":"l05","topic":"Shapes & parameter counts","type":"mcq","q":"In Example 2-13, the second Conv2D layer has 3 × 3 filters and follows a layer with 10 filters on an RGB image. What is the shape of each of its filters?","options":["3 × 3 × 3","3 × 3 × 10","3 × 3 × 20","3 × 3 × 1"],"answer":1,"fixed":false,"why":"A filter always spans the full depth of its input: the previous layer outputs 10 channels, so each filter is 3 × 3 × 10 (slide 17, 22). 3 × 3 × 3 would match the RGB image only in the first layer; 20 is this layer's number of filters, not their depth.","source":"slides 17, 22 · Foster pp. 44–46","study":"lectures/L05-cnn.md — Key concepts (Stacking, slides 14–17)","origin":"practice"},{"id":"l05-018","chapter":"l05","topic":"Shapes & parameter counts","type":"mcq","q":"The Flatten layer in Table 2-2 receives a tensor of shape (None, 8, 8, 20). What does it output, and how many parameters does it have?","options":["1,280 units and 1,280 parameters","160 units and 0 parameters","8 units and 20 parameters","1,280 units and 0 parameters"],"answer":3,"fixed":false,"why":"8 × 8 × 20 = 1,280 units; Flatten is just a restructuring of the tensor, so it has no parameters to learn (slide 23).","source":"slide 23 · Foster p. 46","study":"lectures/L05-cnn.md — Worked examples (Table 2-2)","origin":"practice"},{"id":"l05-019","chapter":"l05","topic":"Shapes & parameter counts","type":"mcq","q":"What is the total number of parameters of the first CNN in Table 2-2 (Conv2D 490 → Conv2D 1,820 → Flatten → Dense 10)?","options":["15,120","15,080","12,810","592,554"],"answer":0,"fixed":false,"why":"490 + 1,820 + 0 + 12,810 = 15,120. 15,080 drops every bias (480 + 1,800 + 12,800); 592,554 is the full CNN of Table 2-3.","source":"slides 19–23 (Table 2-2) · Foster pp. 45–46","study":"lectures/L05-cnn.md — Worked examples (Table 2-2)","origin":"practice"},{"id":"l05-020","chapter":"l05","topic":"Shapes & parameter counts","type":"yn","q":"In the model summary, does 'None' in the shape (None, 32, 32, 3) mean that any number of images can be passed through the network together as a batch?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 20: Keras uses None to show that any number of images can be passed simultaneously, as a batch, since the network is just doing tensor algebra.","source":"slide 20 · Foster p. 45","study":"lectures/L05-cnn.md — Key concepts (Stacking, slides 14–17)","origin":"practice"},{"id":"l05-021","chapter":"l05","topic":"Shapes & parameter counts","type":"mcq","q":"In Table 2-3, Conv2D(64 filters, 3 × 3, strides = 2) is applied to a (16, 16, 64) tensor. How many parameters does it have?","options":["18,496","36,928","36,864","73,856"],"answer":1,"fixed":false,"why":"(3·3·64 + 1)·64 = 577·64 = 36,928. 36,864 forgets the 64 biases; 18,496 is the previous Conv2D layer (32 input channels).","source":"slide 46 (Table 2-3) · Foster p. 52","study":"lectures/L05-cnn.md — Worked examples (Table 2-3)","origin":"practice"},{"id":"l05-022","chapter":"l05","topic":"Batch normalization","type":"yn","q":"Can extremely large weight values in a neural network be a sign of the exploding gradient problem?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes (slide 26): weights growing too large signal exploding gradients — gradients in early layers grow exponentially and the weights fluctuate wildly. The other symptom is the loss suddenly returning NaN.","source":"slides 26, 34 · Foster p. 46","study":"lectures/L05-cnn.md — ★★★ Her eleven questions, with answers (slide 34)","origin":"professor"},{"id":"l05-023","chapter":"l05","topic":"Batch normalization","type":"mcq","q":"Which parameters are trainable in a batch normalization layer?","options":["Input and output tensors","Mean and standard deviation","Momentum and variance","Scale (gamma) and shift (beta)"],"answer":3,"fixed":false,"why":"Gamma and beta are learned by backpropagation. The moving mean and standard deviation are non-trainable — computed from the data — and momentum is a hyperparameter, not a parameter.","source":"slides 29, 32, 34 · Foster p. 48","study":"lectures/L05-cnn.md — ★★★ Her eleven questions, with answers (slide 34)","origin":"professor"},{"id":"l05-024","chapter":"l05","topic":"Batch normalization","type":"mcq","q":"How many parameters in total does a BatchNormalization layer have after a 64-channel convolution?","options":["64","128","256","512"],"answer":2,"fixed":false,"why":"4 per channel: γ, β (trainable) + moving mean, moving std (non-trainable) → 4 × 64 = 256. 128 counts only the trainable pair.","source":"slide 32; slide 46 (Table 2-3) · Foster p. 48","study":"lectures/L05-cnn.md — Key concepts (Batch normalization, slides 26–33)","origin":"practice"},{"id":"l05-025","chapter":"l05","topic":"Batch normalization","type":"mcq","q":"According to slides 26–27, what is the tell-tale sign that a network has suffered exploding gradients?","options":["The training accuracy suddenly reaches 100%","The loss function suddenly returns NaN","The loss stays exactly constant from the first epoch","Each epoch takes twice as long as the previous one"],"answer":1,"fixed":false,"why":"If the loss returns NaN, the weights have probably grown large enough to cause an overflow error — and it can happen after hours of apparently happy training.","source":"slides 26–27 · Foster pp. 46–47","study":"lectures/L05-cnn.md — Key concepts (Batch normalization, slides 26–33)","origin":"practice"},{"id":"l05-026","chapter":"l05","topic":"Batch normalization","type":"mcq","q":"What does Foster call covariate shift?","options":["As the weights move away from their random initial values, the activations of later layers stop being well scaled even though the input was scaled","Pixel values of 0–255 being passed into the input layer without scaling","Randomly chosen units being set to 0 during training","The learning rate being reduced automatically as training progresses"],"answer":0,"fixed":false,"why":"Slide 28: scaling the input should keep all layers' activations well scaled, but as the network trains and the weights drift from their random start, this assumption breaks down — covariate shift. Setting units to 0 is dropout.","source":"slide 28 · Foster p. 47","study":"book/B02-deep-learning.md — §4.4 Batch normalization","origin":"practice"},{"id":"l05-027","chapter":"l05","topic":"Batch normalization","type":"mcq","q":"How does a batch normalization layer normalize its input at prediction time, when there may be only a single observation?","options":["It uses the mean and standard deviation of that single observation","It skips normalization and only applies gamma and beta to the raw input","It recomputes the mean and standard deviation over the whole training set","It uses the moving averages of the mean and standard deviation stored during training"],"answer":3,"fixed":false,"why":"Slide 31: there is no batch at prediction time, so during training the layer also stores a moving average of each channel's mean and standard deviation, and uses that at test time.","source":"slide 31 · Foster p. 48","study":"lectures/L05-cnn.md — Key concepts (Batch normalization, slides 26–33)","origin":"practice"},{"id":"l05-028","chapter":"l05","topic":"Batch normalization","type":"mcq","q":"In layers.BatchNormalization(momentum = 0.9), what is the momentum parameter?","options":["The weight given to the previous value when calculating the moving average and moving standard deviation","The learning rate used to update gamma and beta","The proportion of channels that are normalized","The weight given to the current batch's mean only, ignoring the stored average"],"answer":0,"fixed":false,"why":"Slide 33 verbatim: momentum is the weight given to the previous value of the moving average. It is a hyperparameter of the inference-time statistics, not an optimizer learning rate.","source":"slide 33 (Example 2-14) · Foster p. 49","study":"lectures/L05-cnn.md — Key concepts (Batch normalization, slides 26–33)","origin":"practice"},{"id":"l05-029","chapter":"l05","topic":"Batch normalization","type":"mcq","q":"In Table 2-3, the BatchNormalization layer after Dense(128) has 512 parameters. How many of them are non-trainable?","options":["128","256","0","512"],"answer":1,"fixed":false,"why":"4 per channel × 128 = 512, of which 2 per channel (moving mean and moving std) are non-trainable → 256. 128 would be only one of the two statistics.","source":"slides 32, 46 (Table 2-3) · Foster pp. 48, 52–53","study":"lectures/L05-cnn.md — Worked examples (Table 2-3)","origin":"practice"},{"id":"l05-030","chapter":"l05","topic":"Dropout & overfitting","type":"yn","q":"Does a dropout layer always drop the same units every training iteration?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — each dropout layer chooses a random set of units every time (slide 36), and at prediction time it drops none. 'Always' is the trap word.","source":"slides 36–37, 40 · Foster p. 49","study":"lectures/L05-cnn.md — ★★★ Her eleven questions, with answers (slide 40)","origin":"professor"},{"id":"l05-031","chapter":"l05","topic":"Dropout & overfitting","type":"mcq","q":"In Keras, what does the rate parameter of a Dropout layer specify?","options":["The learning rate for the optimizer","The number of output neurons","The proportion of units to drop from the preceding layer","The momentum for moving averages"],"answer":2,"fixed":false,"why":"Slide 38: rate is the proportion of units dropped from the preceding layer — Dropout(rate = 0.25) drops 25%. 'Learning rate' is the word-association trap; momentum belongs to BatchNormalization.","source":"slides 38, 40 (Example 2-15) · Foster p. 50","study":"lectures/L05-cnn.md — ★★★ Her eleven questions, with answers (slide 40)","origin":"professor"},{"id":"l05-032","chapter":"l05","topic":"Dropout & overfitting","type":"yn","q":"Does a dropout layer drop units at prediction time?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. Only during training; at prediction the dropout layer doesn't drop any units, so the full network is used (lecture 4, slide 37).","source":"slide 37 · Foster p. 50","study":"lectures/L05-cnn.md — Key concepts (Dropout, slides 35–40)","origin":"practice"},{"id":"l05-033","chapter":"l05","topic":"Dropout & overfitting","type":"yn","q":"Does a dropout layer have weights to learn?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. The units to drop are chosen stochastically, so it has 0 parameters (Table 2-3 lists Dropout with 0).","source":"slide 37; slide 46 (Table 2-3) · Foster p. 50","study":"lectures/L05-cnn.md — Key concepts (Dropout, slides 35–40)","origin":"practice"},{"id":"l05-034","chapter":"l05","topic":"Dropout & overfitting","type":"yn","q":"Are dropout layers most commonly placed after convolutional layers?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — most commonly after dense layers, which are the most prone to overfitting because they have the most weights; they can also be used after convolutional layers (slide 39).","source":"slide 39 · Foster p. 51","study":"lectures/L05-cnn.md — Key concepts (Dropout, slides 35–40)","origin":"practice"},{"id":"l05-035","chapter":"l05","topic":"Dropout & overfitting","type":"yn","q":"Do many modern deep learning architectures use no dropout at all, relying solely on batch normalization for regularization?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes (slide 39): batch normalization has also been shown to reduce overfitting, so many modern architectures skip dropout. There is no golden rule — test on a holdout set.","source":"slide 39 · Foster p. 51","study":"lectures/L05-cnn.md — Key concepts (Dropout, slides 35–40)","origin":"practice"},{"id":"l05-036","chapter":"l05","topic":"Full CNN & results","type":"mcq","q":"What does the acronym BAD stand for in this context?","options":["Bias, Activation, Dropout","Batch, Adjustment, Dropout","BatchNormalization, Average, Dense","BatchNormalization, Activation, Dropout"],"answer":3,"fixed":false,"why":"Slide 45: if you put batch normalization before the activation, remember the order as BAD — batch normalization, activation, then dropout.","source":"slides 45, 47 · Foster p. 52","study":"lectures/L05-cnn.md — ★★★ Her eleven questions, with answers (slide 47)","origin":"professor"},{"id":"l05-037","chapter":"l05","topic":"Full CNN & results","type":"yn","q":"Is the order of the batch normalization and activation layers a matter of preference, with some successful architectures placing the activation first?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 45: usually batch normalization goes before the activation, but some successful architectures use them the other way around; BAD only applies if you choose BN first.","source":"slide 45 · Foster p. 52","study":"lectures/L05-cnn.md — ★★★ Her eleven questions, with answers (slide 47)","origin":"practice"},{"id":"l05-038","chapter":"l05","topic":"Full CNN & results","type":"mcq","q":"Which single layer holds the largest share of the full CNN's 592,554 parameters (Table 2-3)?","options":["The last Conv2D layer (64 filters)","The Dense(128) layer after Flatten","The output Dense(10) layer","The BatchNormalization layer after Dense(128)"],"answer":1,"fixed":false,"why":"Dense(128) on the 4,096 flattened values has (4,096 + 1)·128 = 524,416 parameters — about 88.5% of the model. The last Conv2D has 36,928, Dense(10) 1,290, that BN layer 512.","source":"slide 46 (Table 2-3) · Foster pp. 52–53","study":"lectures/L05-cnn.md — Worked examples (Table 2-3)","origin":"practice"},{"id":"l05-039","chapter":"l05","topic":"Full CNN & results","type":"mcq","q":"What test accuracy did the full CNN reach on CIFAR-10 according to slide 49, compared with the MLP?","options":["49.0%, up from 71.5% for the MLP","71.5%, up from 49.0% for the MLP","71.5%, the same as the MLP","90.0%, up from 49.0% for the MLP"],"answer":1,"fixed":false,"why":"Slide 49: 'this model is now achieving 71.5% accuracy, up from 49.0% previously'. The first option swaps the two numbers.","source":"slide 49 · Foster p. 53","study":"lectures/L05-cnn.md — Key concepts (The full CNN / Result, slides 41–50)","origin":"practice"},{"id":"l05-040","chapter":"l05","topic":"Full CNN & results","type":"yn","q":"Did the CNN beat the MLP's accuracy while having fewer parameters, even though it has far more layers?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 49: the number of parameters is actually fewer in the new model (592,554 vs the MLP's 646,260) even though the number of layers is far greater.","source":"slide 49; slide 46 (Table 2-3) · Foster p. 53","study":"lectures/L05-cnn.md — Key concepts (The full CNN / Result, slides 41–50)","origin":"practice"},{"id":"l05-045","chapter":"l05","topic":"Batch normalization","type":"mcq","q":"How many parameters are contained within a batch normalization layer, for each channel in the preceding layer?","options":["2 — gamma and beta, both trainable","4 — all four trainable by backpropagation","4 — 2 trainable (γ, β) and 2 non-trainable","3 — gamma, beta and momentum, all trainable"],"answer":2,"fixed":false,"why":"Slide 32: gamma and beta are learned (trainable); the moving mean and standard deviation are derived from the data, so they are non-trainable — four per channel. 'Two' counts only the trainable pair.","source":"slide 32 · Foster p. 48","study":"lectures/L05-cnn.md — Key concepts (Batch normalization, slides 26–33)","origin":"professor"},{"id":"l05-046","chapter":"l05","topic":"Convolution & filters","type":"yn","q":"Does the convolution output become more positive when the image portion closely matches the filter?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — slide 5: the output is more positive when the portion closely matches the filter. It is the inverse portion that drives it more negative.","source":"slide 5 · Foster p. 41","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 9 — what a convolution is","origin":"practice","twin":"l05-001"},{"id":"l05-047","chapter":"l05","topic":"Convolution & filters","type":"yn","q":"Does the convolution produce a large positive value when the image portion does not resonate much with the filter?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — slide 5: a portion that does not resonate much with the filter produces a value near zero. A large positive value needs a close match.","source":"slide 5 · Foster p. 41","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 9 — what a convolution is","origin":"practice","twin":"l05-001"},{"id":"l05-048","chapter":"l05","topic":"Convolution & filters","type":"mcq","q":"What kind of convolution output is produced when the image portion is the inverse of the filter?","options":["A large positive value","A value near zero","A large negative value","Exactly the same value as the filter's centre pixel"],"answer":2,"fixed":false,"why":"Slide 5: the output is more negative when the portion is the inverse of the filter. A large positive value is what a close match gives; near zero is a poor resemblance.","source":"slide 5 · Foster p. 41","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 9 — what a convolution is","origin":"practice","twin":"l05-001"},{"id":"l05-049","chapter":"l05","topic":"Convolution & filters","type":"mcq","q":"Which of the following is NOT part of performing a convolution of a filter with a portion of an image?","options":["Dividing each image value by the matching filter value","Multiplying the filter pixelwise with the image portion","Summing the results of the pixelwise multiplication","Moving the filter across the image, recording each output"],"answer":0,"fixed":false,"why":"Slide 5–6: multiply pixelwise, sum, and slide the filter across the image to build the feature map. Division is never used — it was her distractor b.","source":"slides 5–6 · Foster pp. 41–42","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 9 — what a convolution is","origin":"practice","twin":"l05-002"},{"id":"l05-050","chapter":"l05","topic":"Convolution & filters","type":"yn","q":"Is a convolution performed by adding up the pixel values of the image portion without weighting them by the filter?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — each pixel is first multiplied by the corresponding filter value, then the products are summed (slide 5). An unweighted sum ignores the filter entirely.","source":"slide 5 · Foster p. 41","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 9 — what a convolution is","origin":"practice","twin":"l05-002"},{"id":"l05-051","chapter":"l05","topic":"Convolution & filters","type":"mcq","q":"A filter with rows (1, 0, −1 / 1, 0, −1 / 1, 0, −1) is applied to the image portion (0.9, 0.5, 0.1 / 0.8, 0.5, 0.2 / 0.9, 0.4, 0.1). What is the convolution output?","options":["4.4","2.2","0.0","−2.2"],"answer":1,"fixed":false,"why":"Pixelwise multiply and sum: (0.9 − 0.1) + (0.8 − 0.2) + (0.9 − 0.1) = 2.2. 4.4 is the unweighted sum of the patch — the 'addition without weighting' trap.","source":"slide 5 (Figure 2-10) · Foster p. 41","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 9 — what a convolution is","origin":"practice","twin":"l05-002"},{"id":"l05-052","chapter":"l05","topic":"Stride & padding","type":"yn","q":"Does setting padding = \"same\" ensure that the output tensor has the same spatial dimensions as the input when stride = 2?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — slide 11 limits the guarantee to strides = 1. With stride 2 the height and width are halved (slide 10), even with padding = \"same\".","source":"slides 10–11 · Foster p. 43","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 18 — padding and stride","origin":"practice","twin":"l05-008"},{"id":"l05-053","chapter":"l05","topic":"Stride & padding","type":"yn","q":"Does padding = \"same\" pad the input data with zeros?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — slide 11: padding = \"same\" pads the input data with zeros so the kernel can extend over the edge of the image.","source":"slides 11–12 · Foster p. 43","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 18 — padding and stride","origin":"practice","twin":"l05-008"},{"id":"l05-054","chapter":"l05","topic":"Stride & padding","type":"mcq","q":"A 3 × 3 kernel is passed over a 5 × 5 input image with padding = \"same\" and strides = 1 (Figure 2-12). What is the output size, and how many times does the kernel fit in each direction?","options":["3 × 3; it fits three times","7 × 7; it fits seven times","5 × 5; it fits three times","5 × 5; it fits five times"],"answer":3,"fixed":false,"why":"Slide 12: the padding lets the kernel extend over the edge, so it fits five times each way → 5 × 5. 3 × 3 is the answer without padding.","source":"slide 12 (Figure 2-12) · Foster p. 43","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 18 — padding and stride","origin":"practice","twin":"l05-008"},{"id":"l05-055","chapter":"l05","topic":"Stride & padding","type":"mcq","q":"Conv2D(32 filters, kernel 3 × 3, strides = 2, padding = \"same\") is applied to a (64, 64, 3) tensor. What is the output shape?","options":["(32, 32, 32)","(64, 64, 32)","(32, 32, 3)","(31, 31, 32)"],"answer":0,"fixed":false,"why":"Stride 2 with padding \"same\" halves height and width (64 → 32) and the depth equals the number of filters (32). (31, 31, 32) is what padding \"valid\" would give.","source":"slides 10, 13 · Foster p. 43","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 18 — padding and stride","origin":"practice","twin":"l05-009"},{"id":"l05-056","chapter":"l05","topic":"Stride & padding","type":"mcq","q":"Conv2D(16 filters, kernel 4 × 4, strides = 2, padding = \"valid\" — no padding) is applied to a (32, 32, 3) tensor. What is the output shape?","options":["(16, 16, 16)","(15, 15, 16)","(14, 14, 16)","(15, 15, 3)"],"answer":1,"fixed":false,"why":"Without padding the kernel only fits ⌊(32 − 4) / 2⌋ + 1 = 15 times each way, and depth = 16 filters. 'Exactly half' (16) holds only with padding \"same\" — slide 10's rule assumes it.","source":"slides 10, 12 · Foster p. 43","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 18 — padding and stride","origin":"practice","twin":"l05-009"},{"id":"l05-057","chapter":"l05","topic":"Stride & padding","type":"yn","q":"With strides = 2 and padding = \"same\", does a 64 × 64 input give a 32 × 32 output?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — slide 10: with strides = 2 the height and width of the output are half the input, so 64 → 32. Doubling would be a Conv2DTranspose, not a Conv2D.","source":"slide 10 · Foster p. 43","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 18 — padding and stride","origin":"practice","twin":"l05-009"},{"id":"l05-058","chapter":"l05","topic":"Shapes & parameter counts","type":"yn","q":"In Example 2-13 (the first CNN), do both convolutional layers use padding = \"same\" and strides = 2?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — slides 21–22: both layers use strides = 2 and padding = \"same\", which is why 32 → 16 → 8. Her own version asked about strides = 1, which is false.","source":"slides 21–22 · Foster pp. 45–46","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 25 — the first CNN (Example 2-13)","origin":"practice","twin":"l05-014"},{"id":"l05-059","chapter":"l05","topic":"Shapes & parameter counts","type":"yn","q":"In Example 2-13, do both convolutional layers use 4 × 4 kernels?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — the first layer uses 4 × 4 kernels (10 filters) but the second uses 3 × 3 kernels (20 filters), slides 21–22. One wrong half makes the whole statement false.","source":"slides 21–22 · Foster pp. 45–46","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 25 — the first CNN (Example 2-13)","origin":"practice","twin":"l05-014"},{"id":"l05-060","chapter":"l05","topic":"Shapes & parameter counts","type":"mcq","q":"In Example 2-13, why does the spatial size go from 32 × 32 to 16 × 16 to 8 × 8?","options":["Both layers use padding = \"valid\", which trims the edges","A pooling layer follows each convolutional layer","The Flatten layer halves the tensor before the Dense layer","Both layers use strides = 2 with padding = \"same\""],"answer":3,"fixed":false,"why":"Slides 21–22: strides = 2 and padding = \"same\" halve width and height at each conv layer. There is no pooling in Foster's CNN — it downsamples with stride instead.","source":"slides 21–22 · Foster pp. 45–46","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 25 — the first CNN (Example 2-13)","origin":"practice","twin":"l05-014"},{"id":"l05-061","chapter":"l05","topic":"Shapes & parameter counts","type":"mcq","q":"In Example 2-13, how many units does the final Dense layer with softmax activation have, and why?","options":["1,280 — one per unit of the flattened tensor","20 — one per filter of the last convolutional layer","10 — one probability per category of the 10-category task","1 — a single probability that the image is correct"],"answer":2,"fixed":false,"why":"Slide 23: a 10-unit Dense layer with softmax represents the probability of each category in a 10-category classification task. 1,280 is the size of its input (8 × 8 × 20), not its output.","source":"slide 23 · Foster p. 46","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 25 — the first CNN (Example 2-13)","origin":"practice","twin":"l05-015"},{"id":"l05-062","chapter":"l05","topic":"Shapes & parameter counts","type":"yn","q":"In Example 2-13, does the final Dense layer with softmax activation flatten the tensor into a single vector?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — flattening is done by the Flatten layer before it (8 × 8 × 20 → 1,280). The softmax Dense layer outputs a probability for each of the 10 categories (slide 23).","source":"slide 23 · Foster p. 46","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 25 — the first CNN (Example 2-13)","origin":"practice","twin":"l05-015"},{"id":"l05-063","chapter":"l05","topic":"Shapes & parameter counts","type":"mcq","q":"Which statement about the layers of Example 2-13 is NOT correct?","options":["The Flatten layer has no parameters to learn","The first convolutional layer has (4 × 4 × 3 + 1) × 10 = 490 parameters","The final Dense layer adds (1,280 + 1) × 10 = 12,810 parameters","The final softmax Dense layer normalizes the input data"],"answer":3,"fixed":false,"why":"The softmax Dense layer outputs category probabilities; it does not normalize the input (that would be batch normalization). The other three are on slides 21 and 23.","source":"slides 21, 23 · Foster pp. 45–46","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 25 — the first CNN (Example 2-13)","origin":"practice","twin":"l05-015"},{"id":"l05-064","chapter":"l05","topic":"Batch normalization","type":"yn","q":"If your loss function starts to return NaN, is it likely that your weights have grown large enough to cause an overflow error?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — slide 26: a NaN loss usually means the weights have grown large enough to overflow, the tell-tale sign of exploding gradients.","source":"slide 26 · Foster p. 46","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 34 — batch normalization","origin":"practice","twin":"l05-022"},{"id":"l05-065","chapter":"l05","topic":"Batch normalization","type":"yn","q":"Does the exploding gradient problem always show up immediately, in the first iterations of training?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — slide 27: it doesn't necessarily happen immediately; a network can train happily for hours before the loss suddenly returns NaN.","source":"slide 27 · Foster p. 47","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 34 — batch normalization","origin":"practice","twin":"l05-022"},{"id":"l05-066","chapter":"l05","topic":"Batch normalization","type":"mcq","q":"As errors are propagated backward through the network, where can the gradient calculation grow exponentially large, causing the exploding gradient problem?","options":["In the earlier layers of the network","Only in the final output layer","Only in the Flatten layer itself","In the scaled pixel values of the input"],"answer":0,"fixed":false,"why":"Slide 26: the gradient in the earlier layers can grow exponentially large as errors propagate backward, causing wild weight fluctuations. The output layer is where backpropagation starts, not where it explodes.","source":"slide 26 · Foster p. 46","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 34 — batch normalization","origin":"practice","twin":"l05-022"},{"id":"l05-067","chapter":"l05","topic":"Batch normalization","type":"mcq","q":"Which parameters of a batch normalization layer are NON-trainable?","options":["Scale (gamma) and shift (beta)","Moving mean and moving standard deviation","Momentum and the dropout rate","Kernel weights and filter biases"],"answer":1,"fixed":false,"why":"Slide 32: the moving mean and standard deviation are derived from the data passing through the layer, not trained by backpropagation. Gamma and beta are the trainable ones.","source":"slide 32 · Foster p. 48","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 34 — batch normalization","origin":"practice","twin":"l05-023"},{"id":"l05-068","chapter":"l05","topic":"Batch normalization","type":"yn","q":"Are the moving mean and moving standard deviation of a batch normalization layer learned through backpropagation?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — slide 32: they are derived from the data passing through the layer, so they are nontrainable. Only gamma and beta are learned by backpropagation.","source":"slide 32 · Foster p. 48","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 34 — batch normalization","origin":"practice","twin":"l05-023"},{"id":"l05-069","chapter":"l05","topic":"Batch normalization","type":"yn","q":"During training, is the output of a batch normalization layer the normalized input, scaled by gamma and shifted by beta?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — slide 29: each channel is normalized with the batch mean and standard deviation, then scaled by the learned gamma and shifted by the learned beta.","source":"slide 29 · Foster p. 47","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 34 — batch normalization","origin":"practice","twin":"l05-023"},{"id":"l05-070","chapter":"l05","topic":"Dropout & overfitting","type":"yn","q":"During training, does each dropout layer choose a random set of units from the preceding layer and set their output to 0?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — slide 36. Because the set is random, it changes every iteration, which is why her own question (always the same units?) is answered no.","source":"slide 36 · Foster p. 49","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 40 — dropout","origin":"practice","twin":"l05-030"},{"id":"l05-071","chapter":"l05","topic":"Dropout & overfitting","type":"yn","q":"Does dropout prevent the network from becoming overdependent on certain units, so that knowledge is spread more evenly across the whole network?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — slide 37: with dropout the network cannot rely too much on any one unit, so knowledge is more evenly spread and it generalizes better.","source":"slide 37 · Foster p. 49","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 40 — dropout","origin":"practice","twin":"l05-030"},{"id":"l05-072","chapter":"l05","topic":"Dropout & overfitting","type":"mcq","q":"Why does a dropout layer reduce overfitting?","options":["It permanently removes the weakest units after the first epoch","It lowers the optimizer's learning rate as training goes on","The network cannot rely too much on any single unit","It normalizes each channel by the batch mean and standard deviation"],"answer":2,"fixed":false,"why":"Slide 37: randomly dropped units stop the network from over-relying on units that just remember training observations. Nothing is removed permanently — the dropped set changes each step.","source":"slide 37 · Foster p. 49","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 40 — dropout","origin":"practice","twin":"l05-030"},{"id":"l05-073","chapter":"l05","topic":"Dropout & overfitting","type":"mcq","q":"In layers.Dropout(rate = 0.25), what does the value 0.25 specify?","options":["25% of the preceding layer's units are dropped","25% of the preceding layer's units are kept","The optimizer's learning rate is set to 0.25","Exactly 25 units are dropped in every step"],"answer":0,"fixed":false,"why":"Slide 38: rate is the proportion of units to drop from the preceding layer, so 0.25 drops 25%. Reading it as a learning rate is the word-association trap.","source":"slide 38 (Example 2-15) · Foster p. 50","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 40 — dropout","origin":"practice","twin":"l05-031"},{"id":"l05-074","chapter":"l05","topic":"Dropout & overfitting","type":"yn","q":"In Keras, does the rate parameter of a Dropout layer specify the proportion of units to keep?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — slide 38: it is the proportion of units to drop. Dropout(rate = 0.25) drops 25% and keeps 75%.","source":"slide 38 (Example 2-15) · Foster p. 50","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 40 — dropout","origin":"practice","twin":"l05-031"},{"id":"l05-075","chapter":"l05","topic":"Dropout & overfitting","type":"mcq","q":"In the full CNN, Dropout(rate = 0.5) follows the Dense(128) block. On average, how many of the 128 units are set to 0 in a training step, and how many at prediction time?","options":["64 in training and 64 at prediction","64 in training and 0 at prediction","0 in training and 64 at prediction","128 in training and 0 at prediction"],"answer":1,"fixed":false,"why":"rate = 0.5 drops half of the 128 units on average (64) during training; at prediction time the dropout layer drops no units (slide 37).","source":"slides 37–38, 44 · Foster pp. 50–51","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 40 — dropout","origin":"practice","twin":"l05-031"},{"id":"l05-076","chapter":"l05","topic":"Full CNN & results","type":"mcq","q":"If you place batch normalization before the activation, what order of layers does the acronym BAD describe?","options":["Activation → BatchNormalization → Dropout","Dropout → BatchNormalization → Activation","BatchNormalization → Dropout → Activation","BatchNormalization → Activation → Dropout"],"answer":3,"fixed":false,"why":"Slide 45: BAD = batch normalization, activation, then dropout. Putting the activation first is allowed, but then the order no longer spells BAD.","source":"slide 45 · Foster p. 52","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 47 — the BAD acronym","origin":"practice","twin":"l05-036"},{"id":"l05-077","chapter":"l05","topic":"Full CNN & results","type":"yn","q":"Must batch normalization always be placed before the activation layer in a successful architecture?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — slide 45: the order is a matter of preference; usually BN goes before the activation, but some successful architectures use them the other way around.","source":"slide 45 · Foster p. 52","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 47 — the BAD acronym","origin":"practice","twin":"l05-036"},{"id":"l05-078","chapter":"l05","topic":"Full CNN & results","type":"mcq","q":"In the full CNN (Example 2-16), which layers immediately follow the Dense(128) layer, in order?","options":["Dropout, LeakyReLU, BatchNormalization","LeakyReLU, BatchNormalization, Dropout","BatchNormalization, LeakyReLU, Dropout","BatchNormalization, Dropout, LeakyReLU"],"answer":2,"fixed":false,"why":"Slide 44: Dense(128) is followed by BatchNormalization and LeakyReLU, then immediately by Dropout — the BAD order. The other orders swap layers around.","source":"slide 44 · Foster p. 51","study":"lectures/L05-cnn.md — Her eleven questions, with answers › Slide 47 — the BAD acronym","origin":"practice","twin":"l05-036"},{"id":"l05-079","chapter":"l05","topic":"Batch normalization","type":"mcq","q":"A BatchNormalization layer follows a Conv2D layer with 32 filters. How many parameters does it have in total, and how many of them are trainable?","options":["64 in total, all 64 trainable","128 in total, 64 trainable","128 in total, all 128 trainable","64 in total, 32 trainable"],"answer":1,"fixed":false,"why":"Four per channel: 4 × 32 = 128, of which gamma and beta (2 × 32 = 64) are trainable. 64/64 counts only gamma and beta and forgets the moving mean and std.","source":"slide 32; slide 46 (Table 2-3) · Foster pp. 48, 52","study":"lectures/L05-cnn.md — Key concepts (Batch normalization, slides 26–33)","origin":"practice","twin":"l05-045"},{"id":"l05-080","chapter":"l05","topic":"Batch normalization","type":"yn","q":"Does a batch normalization layer placed after a 64-channel convolutional layer have 128 trainable parameters?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes — two trainable parameters (gamma, beta) per channel: 2 × 64 = 128. The layer has 256 in total, but the other 128 (moving mean, std) are non-trainable.","source":"slide 32; slide 46 (Table 2-3) · Foster p. 48","study":"lectures/L05-cnn.md — Key concepts (Batch normalization, slides 26–33)","origin":"practice","twin":"l05-045"},{"id":"l05-081","chapter":"l05","topic":"Batch normalization","type":"mcq","q":"A BatchNormalization layer follows a Dense layer with 256 units. How many non-trainable parameters does it have?","options":["512","256","1,024","0"],"answer":0,"fixed":false,"why":"Two non-trainable per channel (moving mean, moving std): 2 × 256 = 512. 1,024 is the layer's total (4 × 256); 0 forgets that the moving statistics are counted as parameters.","source":"slide 32 · Foster p. 48","study":"lectures/L05-cnn.md — Key concepts (Batch normalization, slides 26–33)","origin":"practice","twin":"l05-045"},{"id":"l06-001","chapter":"l06","topic":"Latent space","type":"mcq","q":"What does the latent space (embedding space) in an autoencoder represent?","options":["A space from which new examples can be generated","The set of original images in the dataset","A subset of the test data","A vector of normalized pixels"],"answer":0,"fixed":false,"why":"Sampling a point in the latent space and decoding it generates a new image. It is a compressed space, not the images or pixels themselves.","source":"L5 slide 10 · Foster p. 61","study":"lectures/L06-autoencoder.md — 7. Her questions","origin":"professor"},{"id":"l06-002","chapter":"l06","topic":"Encoder & decoder shapes","type":"yn","q":"Is the latent space in this encoder (Conv2D 32→64→128, Flatten, Dense(2)) three-dimensional?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No, it is two-dimensional: the encoder ends in Dense(2), output (None, 2). (4, 4, 128) is the feature map before Flatten, not the latent space.","source":"L5 slide 22 · Table 3-1","study":"lectures/L06-autoencoder.md — 7. Her questions","origin":"professor"},{"id":"l06-003","chapter":"l06","topic":"Conv2DTranspose","type":"mcq","q":"Which parameter in Conv2DTranspose layers is responsible for increasing the spatial dimensions of the output?","options":["activation","strides","padding","kernel_size"],"answer":1,"fixed":false,"why":"strides = 2 inserts zeros between input pixels and doubles height and width. padding='same' only fixes the size rule; it does not upsample.","source":"L5 slides 16, 22","study":"lectures/L06-autoencoder.md — 7. Her questions","origin":"professor"},{"id":"l06-004","chapter":"l06","topic":"Loss functions","type":"yn","q":"Can both RMSE and binary cross-entropy be used as loss functions for training the autoencoder?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Slide 24 names both. RMSE is symmetric (sharper but pixelised edges); BCE is asymmetric (slightly blurrier).","source":"L5 slides 24–25, 33","study":"lectures/L06-autoencoder.md — 7. Her questions","origin":"professor"},{"id":"l06-005","chapter":"l06","topic":"Latent space","type":"mcq","q":"What is one consequence of using a two-dimensional latent space?","options":["The model captures all image details perfectly","The decoder no longer needs training","Some information is lost during encoding","The number of parameters becomes extremely large"],"answer":2,"fixed":false,"why":"Compressing a 32×32 image into 2 numbers must discard detail, so reconstructions are blurrier. A small latent actually reduces the parameters.","source":"L5 slide 33","study":"lectures/L06-autoencoder.md — 7. Her questions","origin":"professor"},{"id":"l06-006","chapter":"l06","topic":"Latent space","type":"yn","q":"Does the latent space of an autoencoder contain the set of original training images?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. It holds low-dimensional embeddings; new examples are generated by decoding points from it.","source":"L5 slides 9–11","study":"lectures/L06-autoencoder.md — 7. Her questions","origin":"practice","twin":"l06-001"},{"id":"l06-007","chapter":"l06","topic":"Encoder & decoder shapes","type":"yn","q":"Is the output of the encoder's last Conv2D layer in her autoencoder (None, 4, 4, 128)?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. 32 → 16 → 8 → 4 after three stride-2 convolutions with 128 filters in the last one. The latent space itself is Dense(2).","source":"L5 slide 14 · Table 3-1","study":"lectures/L06-autoencoder.md — 7. Her questions","origin":"practice","twin":"l06-002"},{"id":"l06-008","chapter":"l06","topic":"Conv2DTranspose","type":"mcq","q":"In a Conv2DTranspose layer with padding='same', what does setting strides = 2 do?","options":["Halves the height and width of the input tensor","Doubles the number of channels","Leaves the size unchanged","Doubles the height and width of the input tensor"],"answer":3,"fixed":false,"why":"A transposed convolution with stride 2 doubles both spatial dimensions (4×4 → 8×8). Halving is what a stride-2 Conv2D does.","source":"L5 slide 16","study":"lectures/L06-autoencoder.md — 7. Her questions","origin":"practice","twin":"l06-003"},{"id":"l06-009","chapter":"l06","topic":"Loss functions","type":"mcq","q":"True pixel value 0.7. Under binary cross-entropy, which prediction is penalised more heavily?","options":["0.8","0.6","Both are penalised equally","Neither; BCE ignores errors this small"],"answer":0,"fixed":false,"why":"BCE is asymmetric: errors towards the extremes cost more, so 0.8 costs more than 0.6. Equal penalties would be RMSE.","source":"L5 slide 25","study":"lectures/L06-autoencoder.md — 7. Her questions","origin":"practice","twin":"l06-004"},{"id":"l06-010","chapter":"l06","topic":"Loss functions","type":"mcq","q":"Which loss tends to produce slightly blurrier reconstructions, and why?","options":["RMSE: it penalises over- and under-estimation equally","Binary cross-entropy: it pushes predictions towards 0.5","RMSE: it creates pixelised edges","Binary cross-entropy: it ignores the extremes"],"answer":1,"fixed":false,"why":"BCE penalises errors near the extremes more and so pulls predictions towards the centre (0.5), which blurs. RMSE can give pixelised edges instead.","source":"L5 slide 25","study":"lectures/L06-autoencoder.md — 7. Her questions","origin":"practice","twin":"l06-004"},{"id":"l06-011","chapter":"l06","topic":"Latent space","type":"mcq","q":"Which is NOT one of the three problems of a plain autoencoder's latent space?","options":["Some classes occupy a much larger area than others","The distribution is undefined: not symmetric about (0,0) or bounded","The decoder has more parameters than the encoder","There are holes where no images are encoded"],"answer":2,"fixed":false,"why":"The three problems are unequal areas, an undefined distribution and holes/gaps. Decoder size is irrelevant to sampling.","source":"L5 slides 36–40","study":"lectures/L06-autoencoder.md — 5. Reconstruct, visualise, generate","origin":"practice","twin":"l06-005"},{"id":"l06-012","chapter":"l06","topic":"Parameter counts","type":"mcq","q":"How many parameters does the first Conv2D(32, 3×3) layer of her encoder have on a 32×32×1 input?","options":["288","896","9,248","320"],"answer":3,"fixed":false,"why":"(3·3·1 + 1)·32 = 320. 288 forgets the bias; 896 is for 3 input channels.","source":"L5 slide 14","study":"calc-ae-vae.md — Part A","origin":"practice"},{"id":"l06-013","chapter":"l06","topic":"Parameter counts","type":"mcq","q":"How many parameters does Conv2D(64, 3×3) have when it follows a 32-channel layer?","options":["18,496","18,432","73,792","2,368"],"answer":0,"fixed":false,"why":"(3·3·32 + 1)·64 = 18,496. 18,432 forgets the 64 biases.","source":"L5 slide 14","study":"calc-ae-vae.md — Part A","origin":"practice"},{"id":"l06-014","chapter":"l06","topic":"Parameter counts","type":"mcq","q":"How many parameters does the encoder's Dense(2) have after Flatten produces 2048 values?","options":["4,096","4,098","6,144","2,050"],"answer":1,"fixed":false,"why":"(2048 + 1)·2 = 4,098. 6,144 is the decoder's Dense: (2 + 1)·2048.","source":"L5 slide 14","study":"calc-ae-vae.md — Part A","origin":"practice"},{"id":"l06-015","chapter":"l06","topic":"Parameter counts","type":"mcq","q":"How many parameters does the decoder's first Conv2DTranspose(128, 3×3) have after Reshape to (4, 4, 128)?","options":["73,856","147,456","147,584","18,464"],"answer":2,"fixed":false,"why":"(3·3·128 + 1)·128 = 147,584. 73,856 is the encoder's last Conv2D, which has only 64 input channels.","source":"L5 slide 20","study":"calc-ae-vae.md — Part A","origin":"practice"},{"id":"l06-016","chapter":"l06","topic":"Parameter counts","type":"mcq","q":"What is the total number of parameters of her Fashion-MNIST AE decoder?","options":["96,770","343,043","100,868","246,273"],"answer":3,"fixed":false,"why":"6,144 + 147,584 + 73,792 + 18,464 + 289 = 246,273. 96,770 is the encoder; 343,043 is the whole AE.","source":"L5 slide 20 · Table 3-2","study":"calc-ae-vae.md — Part C","origin":"practice"},{"id":"l06-017","chapter":"l06","topic":"Encoder & decoder shapes","type":"mcq","q":"What is the output shape of the decoder's Dense layer in her autoencoder?","options":["(None, 2048)","(None, 2)","(None, 4, 4, 128)","(None, 128)"],"answer":0,"fixed":false,"why":"Dense(np.prod(shape_before_flattening)) = 4·4·128 = 2048; Reshape then restores (4, 4, 128).","source":"L5 slides 19–20","study":"calc-ae-vae.md — Part B","origin":"practice"},{"id":"l06-018","chapter":"l06","topic":"Parameter counts","type":"mcq","q":"If the AE's EMBEDDING_DIM changes from 2 to 3, by how much does the whole model's parameter count grow?","options":["2,049","4,097","2,048","0"],"answer":1,"fixed":false,"why":"Encoder Dense +2,049 ((2048+1)·1) and decoder Dense +2,048 (one more input row of 2048 weights). The convolutions do not change.","source":"Exercise 3.1 · verified in Keras","study":"calc-ae-vae.md — Problem 1","origin":"practice"},{"id":"l06-019","chapter":"l06","topic":"Conv2DTranspose","type":"mcq","q":"Transposed convolution with input [[0,1],[2,3]], kernel [[0,1],[2,3]], stride 1, no padding. What is the centre value of the 3×3 output?","options":["3","6","4","12"],"answer":2,"fixed":false,"why":"Each input pixel scales the kernel and the overlaps add. The centre receives 1·2 + 2·1 + 3·0 = 4. The full output is [[0,0,1],[0,4,6],[4,12,9]].","source":"L5 slide 43 · verified in Keras","study":"lectures/L06-autoencoder.md — 6. Transposed convolution by hand","origin":"practice"},{"id":"l06-020","chapter":"l06","topic":"Conv2DTranspose","type":"mcq","q":"Output size of a transposed convolution (no padding) with a 2×2 input, 2×2 kernel and stride 2?","options":["3×3","5×5","6×6","4×4"],"answer":3,"fixed":false,"why":"(n − 1)·s + k = (2 − 1)·2 + 2 = 4. 3×3 would be stride 1.","source":"L5 slide 44","study":"lectures/L06-autoencoder.md — 6. Transposed convolution by hand","origin":"practice"},{"id":"l06-021","chapter":"l06","topic":"Encoder & decoder shapes","type":"yn","q":"Does the AE decoder end with a Conv2D (not a Conv2DTranspose) layer with sigmoid activation?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes: Conv2D(1, (3,3), strides=1, activation='sigmoid', padding='same') maps 32 channels to 1 and keeps 32×32 (Fashion AE). The faces VAE uses a Conv2DTranspose instead.","source":"L5 slide 19","study":"lectures/L06-autoencoder.md — 3. The decoder","origin":"practice"},{"id":"l07-001","chapter":"l07","topic":"Encoder & sampling","type":"yn","q":"Is the log variance used instead of the variance in the encoder to allow the neural network to output any real number?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Variance must be positive; its logarithm ranges over (−∞, ∞), which a plain Dense layer can output.","source":"L6 slides 10, 13","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"professor"},{"id":"l07-002","chapter":"l07","topic":"Encoder & sampling","type":"mcq","q":"Why do we use an isotropic multivariate normal distribution in the VAE?","options":["To simplify sampling by assuming each latent dimension is independent","Because the variance is always zero","Because latent dimensions are always correlated","To make the model deterministic"],"answer":0,"fixed":false,"why":"Isotropic means a diagonal covariance: independent dimensions, so the encoder outputs only a mean and a variance per dimension.","source":"L6 slides 9, 13","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"professor"},{"id":"l07-003","chapter":"l07","topic":"Encoder & sampling","type":"yn","q":"Does sampling a point from the area around z_mean encourage the decoder to produce different images for nearby latent points?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No, the opposite. Because z is a random point near z_mean, the decoder must decode a whole neighbourhood to similar images, so the latent space becomes continuous.","source":"L6 slides 16, 29","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"professor"},{"id":"l07-004","chapter":"l07","topic":"Encoder & sampling","type":"mcq","q":"What is the purpose of the Sampling layer in a VAE?","options":["To flatten the input image before the latent layer","To sample a latent vector z from a normal distribution defined by z_mean and z_log_var","To compute the reconstruction loss","To apply a Conv2D transformation to the latent space"],"answer":1,"fixed":false,"why":"Sampling computes z = z_mean + exp(0.5·z_log_var)·ε. It has no weights.","source":"L6 slides 17, 29","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"professor"},{"id":"l07-005","chapter":"l07","topic":"KL divergence","type":"yn","q":"Does the KL divergence term penalize the network when z_mean and z_log_var differ significantly from 1?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No — from 0. The KL term pulls towards the standard normal: z_mean = 0 and z_log_var = 0 (variance 1). The '1' is the trap.","source":"L6 slides 32, 34","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"professor"},{"id":"l07-006","chapter":"l07","topic":"KL divergence","type":"mcq","q":"What is the purpose of the KL divergence term in a VAE?","options":["To measure the difference between the input and output images","To apply a convolutional transformation in the latent space","To force the encoded latent distributions toward a standard normal distribution","To compute the gradient of the reconstruction loss"],"answer":2,"fixed":false,"why":"KL measures how far N(z_mean, σ) is from N(0, 1). Input-versus-output difference is the reconstruction loss.","source":"L6 slides 31–34","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"professor"},{"id":"l07-007","chapter":"l07","topic":"Training & β","type":"yn","q":"Does the total_loss in this VAE example include only the KL loss?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. total_loss = reconstruction_loss + kl_loss.","source":"L6 slides 37, 39","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"professor"},{"id":"l07-008","chapter":"l07","topic":"Training & β","type":"mcq","q":"Why is a beta value of 500 applied in the reconstruction loss?","options":["To reduce the latent space dimensionality","To scale the KL divergence loss","To initialize the optimizer","To scale the reconstruction loss so it is balanced with the KL divergence"],"answer":3,"fixed":false,"why":"In the code 500 multiplies the binary cross-entropy, so the reconstruction term is weighed against KL. It does not multiply the KL term.","source":"L6 slides 37, 39","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"professor"},{"id":"l07-009","chapter":"l07","topic":"Encoder & sampling","type":"yn","q":"Does the VAE encoder output the variance directly from a ReLU layer?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. It outputs z_log_var from a plain Dense layer (any real number); the variance is exp(z_log_var).","source":"L6 slide 10","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"practice","twin":"l07-001"},{"id":"l07-010","chapter":"l07","topic":"Encoder & sampling","type":"mcq","q":"In an isotropic multivariate normal distribution, the covariance matrix is…","options":["Diagonal","Full, with every dimension correlated","All zeros","Equal to the mean vector"],"answer":0,"fixed":false,"why":"Diagonal covariance means no correlation between dimensions, so each can be sampled independently.","source":"L6 slide 9","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"practice","twin":"l07-002"},{"id":"l07-011","chapter":"l07","topic":"Encoder & sampling","type":"yn","q":"Must a VAE decoder decode points in the same neighbourhood to very similar images?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. It is trained on random points around z_mean, so the reconstruction loss stays small only if nearby points look alike.","source":"L6 slide 16","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"practice","twin":"l07-003"},{"id":"l07-012","chapter":"l07","topic":"Encoder & sampling","type":"mcq","q":"Which equation does the Sampling layer compute?","options":["z = z_mean + z_log_var·ε","z = z_mean + exp(0.5·z_log_var)·ε","z = exp(z_mean)·ε","z = z_mean · z_log_var"],"answer":1,"fixed":false,"why":"σ = exp(0.5·log σ²), so z = μ + σ·ε with ε ~ N(0, I).","source":"L6 slides 12, 17","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"practice","twin":"l07-004"},{"id":"l07-013","chapter":"l07","topic":"KL divergence","type":"mcq","q":"When is kl_loss = −0.5·Σ(1 + z_log_var − z_mean² − exp(z_log_var)) minimised to 0?","options":["z_mean = 1 and z_log_var = 1","z_mean = 0 and z_log_var = 1","z_mean = 0 and z_log_var = 0","z_mean = 1 and z_log_var = 0"],"answer":2,"fixed":false,"why":"Each term 1 + 0 − 0 − e⁰ = 0. z_log_var = 1 would mean variance e ≈ 2.72, not 1.","source":"L6 slide 32","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"practice","twin":"l07-005"},{"id":"l07-014","chapter":"l07","topic":"KL divergence","type":"yn","q":"Does the KL term reduce the chance that large gaps form between point clusters in the latent space?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. It pulls all encodings towards the standard normal, so the space around the origin is used symmetrically and efficiently.","source":"L6 slide 33","study":"lectures/L07-vae-introduction.md — 7. Her questions","origin":"practice","twin":"l07-006"},{"id":"l07-015","chapter":"l07","topic":"Training & β","type":"mcq","q":"In her VAE code, which term does BETA multiply?","options":["The KL divergence","The learning rate","The sampled z","The reconstruction (binary cross-entropy) loss"],"answer":3,"fixed":false,"why":"reconstruction_loss = reduce_mean(500 · binary_crossentropy(...)). Foster's prose talks of β 'for the KL', but the code scales reconstruction; same balance, opposite side.","source":"L6 slide 37","study":"lectures/L07-vae-introduction.md — 5. Training","origin":"practice","twin":"l07-008"},{"id":"l07-016","chapter":"l07","topic":"Training & β","type":"mcq","q":"Where is the KL term added to the loss in the Keras VAE?","options":["In a custom train_step of a Model subclass, inside a GradientTape","In model.compile(loss='kl_divergence')","In the Sampling layer's call()","In the decoder's last layer"],"answer":0,"fixed":false,"why":"Subclassing models.Model lets train_step compute reconstruction + KL, take gradients with tf.GradientTape and apply them.","source":"L6 slides 35–38","study":"lectures/L07-vae-introduction.md — 5. Training","origin":"practice","twin":"l07-007"},{"id":"l07-017","chapter":"l07","topic":"VAE calculations","type":"mcq","q":"How many parameters does the z_log_var Dense(2) layer have in her Fashion VAE encoder?","options":["0","4,098","2,050","8,196"],"answer":1,"fixed":false,"why":"(2048 + 1)·2 = 4,098, the same as z_mean. 8,196 is both heads together.","source":"L6 slide 28 · Table 3-4","study":"calc-ae-vae.md — Part C","origin":"practice"},{"id":"l07-018","chapter":"l07","topic":"VAE calculations","type":"mcq","q":"What is the total number of parameters in her Fashion VAE encoder?","options":["96,770","104,966","100,868","246,273"],"answer":2,"fixed":false,"why":"96,770 (the AE encoder) + another 4,098 head = 100,868. The Sampling layer adds 0.","source":"L6 slide 28","study":"calc-ae-vae.md — Part C","origin":"practice"},{"id":"l07-019","chapter":"l07","topic":"VAE calculations","type":"mcq","q":"How many parameters does the Sampling layer have?","options":["2","4,098","Equal to Z_DIM","0"],"answer":3,"fixed":false,"why":"It has no weights; it only computes z from z_mean, z_log_var and random ε.","source":"L6 slide 27","study":"calc-ae-vae.md — Part A","origin":"practice"},{"id":"l07-020","chapter":"l07","topic":"VAE calculations","type":"mcq","q":"Fashion VAE with Z_DIM = 10: parameters of each of z_mean and z_log_var?","options":["20,490","20,480","4,098","22,528"],"answer":0,"fixed":false,"why":"(2048 + 1)·10 = 20,490. 22,528 is the decoder Dense: (10 + 1)·2048.","source":"verified in Keras","study":"calc-ae-vae.md — Problem 3","origin":"practice"},{"id":"l07-021","chapter":"l07","topic":"VAE calculations","type":"mcq","q":"z_mean = (1, −1), z_log_var = (0, 0). What is the KL loss?","options":["0","1.0","2.0","0.5"],"answer":1,"fixed":false,"why":"Per dimension ½(μ² + σ² − 1 − ln σ²) = ½(1 + 1 − 1 − 0) = 0.5; two dimensions give 1.0.","source":"L6 slide 31 formula · NumPy","study":"calc-ae-vae.md — Problem 10","origin":"practice"},{"id":"l07-022","chapter":"l07","topic":"VAE calculations","type":"mcq","q":"z_mean = 2, z_log_var = ln 0.25, ε = −2. What is the sampled z?","options":["2.5","1.5","1.0","−2.0"],"answer":2,"fixed":false,"why":"σ = exp(0.5·ln 0.25) = 0.5, so z = 2 + 0.5·(−2) = 1.0.","source":"L6 slide 12","study":"calc-ae-vae.md — Problem 10","origin":"practice"},{"id":"l07-023","chapter":"l07","topic":"VAE calculations","type":"yn","q":"Is the decoder of a VAE identical to the decoder of a plain autoencoder?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Only the encoder (z_mean, z_log_var, Sampling) and the loss (+KL) change; the decoder stays at 246,273 parameters in the Fashion example.","source":"L6 slide 14","study":"lectures/L07-vae-introduction.md — 1. What changes","origin":"practice"},{"id":"l08-001","chapter":"l08","topic":"Faces VAE setup","type":"mcq","q":"Which is NOT one of the differences between the CelebA VAE and the Fashion-MNIST VAE?","options":["The decoder becomes a mirror image using Conv2D instead of Conv2DTranspose","Three input channels instead of one","A 200-dimensional latent space instead of 2","Batch normalization after each convolutional layer"],"answer":0,"fixed":false,"why":"Slide 9 lists RGB (3 channels), Z_DIM 200, BatchNorm after each conv and β = 2000. The decoder still uses Conv2DTranspose.","source":"L7 slide 9","study":"lectures/L08-vae-latent-space.md — 2. What changes","origin":"practice"},{"id":"l08-002","chapter":"l08","topic":"Faces VAE setup","type":"yn","q":"Are the CelebA attribute labels needed to train the VAE?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No. They are only used afterwards to find feature vectors such as Smiling.","source":"L7 slide 6","study":"lectures/L08-vae-latent-space.md — 1. Dataset","origin":"practice"},{"id":"l08-003","chapter":"l08","topic":"Faces VAE setup","type":"mcq","q":"What does image_dataset_from_directory do for the CelebA VAE?","options":["Loads all 200,000 images into memory at once","Reads batches into memory only when needed and resizes images to 32×32","Downloads the dataset from Kaggle","Encodes the images into the latent space"],"answer":1,"fixed":false,"why":"It creates a TensorFlow Dataset that reads batches lazily and resizes with interpolation, so large datasets fit.","source":"L7 slide 7","study":"lectures/L08-vae-latent-space.md — 1. Dataset","origin":"practice"},{"id":"l08-004","chapter":"l08","topic":"Faces VAE tables","type":"mcq","q":"Parameters of the first Conv2D(128, 3×3) in the faces encoder (input 32×32×3)?","options":["3,456","1,280","3,584","147,584"],"answer":2,"fixed":false,"why":"(3·3·3 + 1)·128 = 3,584. 3,456 forgets the bias; 147,584 is for 128 input channels.","source":"L7 slide 11 · Table 3-5","study":"lectures/L08-vae-latent-space.md — 3. Encoder","origin":"practice"},{"id":"l08-005","chapter":"l08","topic":"Faces VAE tables","type":"mcq","q":"How many parameters does a BatchNormalization layer on 128 channels have, and how many are non-trainable?","options":["256, all trainable","512, all trainable","128, of which 64 non-trainable","512, of which 256 non-trainable"],"answer":3,"fixed":false,"why":"BN stores 4 values per channel: γ and β are trainable; the moving mean and variance are not. 4·128 = 512, half non-trainable.","source":"L7 slide 11 · Keras","study":"lectures/L08-vae-latent-space.md — 3. Encoder","origin":"practice"},{"id":"l08-006","chapter":"l08","topic":"Faces VAE tables","type":"mcq","q":"What is the shape after the 4th stride-2 Conv2D in the faces encoder, and the Flatten size?","options":["(2, 2, 128) and 512","(4, 4, 128) and 2048","(2, 2, 128) and 256","(1, 1, 128) and 128"],"answer":0,"fixed":false,"why":"32 → 16 → 8 → 4 → 2, with 128 channels, gives 2·2·128 = 512.","source":"L7 slide 11","study":"lectures/L08-vae-latent-space.md — 3. Encoder","origin":"practice"},{"id":"l08-007","chapter":"l08","topic":"Faces VAE tables","type":"mcq","q":"Parameters of z_mean = Dense(200) in the faces encoder?","options":["102,400","102,600","409,800","102,912"],"answer":1,"fixed":false,"why":"(512 + 1)·200 = 102,600. 102,912 is the decoder Dense: (200 + 1)·512.","source":"L7 slide 11","study":"lectures/L08-vae-latent-space.md — 3. Encoder","origin":"practice"},{"id":"l08-008","chapter":"l08","topic":"Faces VAE tables","type":"mcq","q":"The faces encoder's total parameters are 653,584. How many are non-trainable?","options":["0","2,048","1,024","512"],"answer":2,"fixed":false,"why":"4 BN layers × 128 channels × 2 (moving mean and variance) = 1,024. 2,048 is the decoder's figure.","source":"L7 slide 11 · Table 3-5","study":"lectures/L08-vae-latent-space.md — 3. Encoder","origin":"practice"},{"id":"l08-009","chapter":"l08","topic":"Faces VAE tables","type":"mcq","q":"Parameters of the BatchNormalization right after the decoder's Dense(512)?","options":["512","1,024","4","2,048"],"answer":3,"fixed":false,"why":"BN on a 512-vector keeps 4 values per unit: 4·512 = 2,048 (1,024 non-trainable).","source":"L7 slide 13 · Table 3-6","study":"lectures/L08-vae-latent-space.md — 4. Decoder","origin":"practice"},{"id":"l08-010","chapter":"l08","topic":"Faces VAE tables","type":"mcq","q":"Parameters of the faces decoder's output Conv2DTranspose(3, 3×3, strides 1) after 128 channels?","options":["3,459","3,456","1,161","3,584"],"answer":0,"fixed":false,"why":"(3·3·128 + 1)·3 = 3,459. 3,584 is the encoder's first Conv2D (3 in, 128 out).","source":"L7 slide 13","study":"lectures/L08-vae-latent-space.md — 4. Decoder","origin":"practice"},{"id":"l08-011","chapter":"l08","topic":"Faces VAE tables","type":"mcq","q":"Totals of the faces decoder (Table 3-6)?","options":["653,584 total · 652,560 trainable · 1,024 non-trainable","700,803 total · 698,755 trainable · 2,048 non-trainable","700,803 total · all trainable","698,755 total · 2,048 non-trainable"],"answer":1,"fixed":false,"why":"Dense 102,912 + BN 2,048 + 4×(147,584 + 512) + 3,459 = 700,803; non-trainable 1,024 + 4·256 = 2,048.","source":"L7 slide 13 · Keras","study":"lectures/L08-vae-latent-space.md — 4. Decoder","origin":"practice"},{"id":"l08-012","chapter":"l08","topic":"Faces VAE tables","type":"yn","q":"Does the faces decoder's last Conv2DTranspose use strides = 2?","options":["Yes","No"],"answer":1,"fixed":false,"why":"No, strides = 1. The four stride-2 layers already reach 32×32; the last layer only maps 128 channels to 3.","source":"L7 slide 12","study":"lectures/L08-vae-latent-space.md — 4. Decoder","origin":"practice"},{"id":"l08-013","chapter":"l08","topic":"Latent arithmetic & morphing","type":"mcq","q":"How is the 'Smiling' feature vector found?","options":["Encoding of the single most smiling face","Training a new encoder on Smiling labels","Average encoding of Smiling images minus average encoding of non-Smiling images","Adding the Smiling label to z_log_var"],"answer":2,"fixed":false,"why":"Subtracting the two mean positions gives the direction of increasing smile.","source":"L7 slide 18","study":"lectures/L08-vae-latent-space.md — 6. Latent space arithmetic","origin":"practice"},{"id":"l08-014","chapter":"l08","topic":"Latent arithmetic & morphing","type":"mcq","q":"Which formula adds a feature to an encoded image?","options":["z_new = z · feature_vector","z_new = alpha · z","z_new = z − z_mean","z_new = z + alpha · feature_vector"],"answer":3,"fixed":false,"why":"alpha controls how much of the feature is added (negative removes it).","source":"L7 slide 18","study":"lectures/L08-vae-latent-space.md — 6. Latent space arithmetic","origin":"practice"},{"id":"l08-015","chapter":"l08","topic":"Latent arithmetic & morphing","type":"yn","q":"When morphing from face A to face B, does the VAE decode points along the straight line between their encodings?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Yes. Encode A and B and decode points at regular intervals on the line; the smooth result shows the latent space is continuous.","source":"L7 slides 20–22","study":"lectures/L08-vae-latent-space.md — 7. Morphing","origin":"practice"},{"id":"l08-016","chapter":"l08","topic":"Latent arithmetic & morphing","type":"mcq","q":"What does Fig. 3-17 (histograms of the first 50 latent dimensions) show?","options":["No dimension differs significantly from the standard normal","Every dimension is uniform between −1 and 1","Only the first dimension is used","The latent space has large holes"],"answer":0,"fixed":false,"why":"Each looks like N(0, 1), which justifies sampling new faces from a standard normal.","source":"L7 slide 15","study":"lectures/L08-vae-latent-space.md — 5. Analysis","origin":"practice"},{"id":"l08-017","chapter":"l08","topic":"Faces VAE setup","type":"mcq","q":"How many new faces does `np.random.normal(size=(10 * 3, 200))` followed by decoder.predict generate?","options":["200","30","10","6,000"],"answer":1,"fixed":false,"why":"30 vectors of length 200 (Z_DIM), one per face in a 10×3 grid.","source":"L7 slide 16","study":"lectures/L08-vae-latent-space.md — 5. Analysis","origin":"practice"},{"id":"l08-018","chapter":"l08","topic":"Faces VAE tables","type":"mcq","q":"Faces VAE with NUM_FEATURES = 64 and Z_DIM = 100: encoder total parameters?","options":["653,584","164,488","165,000","177,347"],"answer":2,"fixed":false,"why":"1,792 + 3·36,928 + 4·256 + 2·25,700 = 165,000 (164,488 trainable; 177,347 is the decoder).","source":"verified in Keras","study":"calc-ae-vae.md — Problem 6","origin":"practice"},{"id":"l03-001","chapter":"l03","topic":"AI nesting & five approaches","type":"mcq","q":"Which nesting appears on slide 2 ('GenAI as a subset of AI')?","options":["GenAI ⊆ LLMs ⊆ DL ⊆ ML ⊆ AI","LLMs ⊆ DL ⊆ GenAI ⊆ ML ⊆ AI","LLMs ⊆ GenAI ⊆ DL ⊆ ML ⊆ AI","LLMs ⊆ GenAI ⊆ ML ⊆ DL ⊆ AI"],"answer":2,"fixed":false,"why":"Slide 2 reads exactly LLMs ⊆ GenAI ⊆ DL ⊆ ML ⊆ AI. Deep learning sits inside machine learning, not the reverse, and LLMs are one kind of GenAI.","source":"L03 slide 2","study":"lectures/L03-genai-in-the-enterprise.md — 1. Where GenAI sits (slide 2)","origin":"practice"},{"id":"l03-002","chapter":"l03","topic":"AI nesting & five approaches","type":"mcq","q":"In the 'Approaches in applying GenAI' diagram, in how many of the five approaches is the foundation model provider-managed?","options":["1","2","3","4"],"answer":3,"fixed":true,"why":"Consume, Embed, Extend-retrieval and Extend-fine-tuning all use the provider's foundation model; only Build ('custom models from scratch') self-manages it.","source":"L03 slide 3","study":"lectures/L03-genai-in-the-enterprise.md — 2. ★ The five approaches to applying GenAI (slide 3)","origin":"practice"},{"id":"l03-003","chapter":"l03","topic":"AI nesting & five approaches","type":"mcq","q":"You build your own application around a provider's GenAI API, while retrieval/prompting, fine-tuning and the foundation model stay provider-managed. Which approach is this?","options":["Consume","Embed","Extend via data retrieval","Build"],"answer":1,"fixed":false,"why":"Embed = 'Generative AI APIs in a custom app frame': only the application layer is self-managed. In Consume even the application is the provider's.","source":"L03 slide 3","study":"lectures/L03-genai-in-the-enterprise.md — 2. ★ The five approaches to applying GenAI (slide 3)","origin":"practice"},{"id":"l03-004","chapter":"l03","topic":"AI nesting & five approaches","type":"mcq","q":"In 'Extend — GenAI models via data retrieval', which layers are self-managed?","options":["Application only","Application, data retrieval & prompt engineering, and fine-tuning","All four layers, including the foundation model","Application, and data retrieval & prompt engineering"],"answer":3,"fixed":false,"why":"On slide 3 the retrieval column is grey (self) for Application and Data Retrieval & Prompt Engineering, blue (provider) for Fine-Tuning and Foundation Model. Self-managed fine-tuning is the next column to the right.","source":"L03 slide 3","study":"lectures/L03-genai-in-the-enterprise.md — 2. ★ The five approaches to applying GenAI (slide 3)","origin":"practice"},{"id":"l03-005","chapter":"l03","topic":"AI nesting & five approaches","type":"yn","q":"In the 'Consume' approach (GenAI embedded in apps), is the application layer self-managed?","options":["Yes","No"],"answer":1,"fixed":false,"why":"In Consume all four layers, including Application, are provider-managed: you buy a finished product. Embed is the first approach where the application becomes self-managed.","source":"L03 slide 3","study":"lectures/L03-genai-in-the-enterprise.md — 2. ★ The five approaches to applying GenAI (slide 3)","origin":"practice"},{"id":"l03-006","chapter":"l03","topic":"AI nesting & five approaches","type":"mcq","q":"Which statement about the two 'Extend' approaches on slide 3 is correct?","options":["Retrieval sits nearer the 'Buy' end and leaves fine-tuning to the provider","Fine-tuning sits nearer the 'Buy' end and leaves retrieval to the provider","Both require you to self-manage the foundation model","They differ only in who manages the application layer"],"answer":0,"fixed":false,"why":"Left-to-right the order is Consume, Embed, Extend-retrieval, Extend-fine-tuning, Build. Retrieval self-manages retrieval/prompting but not fine-tuning; both Extends keep the provider's foundation model.","source":"L03 slide 3","study":"lectures/L03-genai-in-the-enterprise.md — 2. ★ The five approaches to applying GenAI (slide 3)","origin":"practice"},{"id":"l03-007","chapter":"l03","topic":"Pilot lifecycle & prioritisation","type":"mcq","q":"What are the two decision points in the GenAI pilot stage-gate diagram (slide 7)?","options":["'Build or buy?' and 'Go live?'","'Invest in pilot?' and 'Stop or scale?'","'Invest in pilot?' and 'Build or buy?'","'Prioritise use cases?' and 'Stop or scale?'"],"answer":1,"fixed":false,"why":"The two orange diamonds read 'Invest in Pilot?' (after Formalize Pilot Team) and 'Stop or Scale?' (before Roadmap). 'Prioritize Use Cases' is a step, not a gate.","source":"L03 slide 7","study":"lectures/L03-genai-in-the-enterprise.md — 3. ★ The GenAI pilot lifecycle (slide 7)","origin":"practice"},{"id":"l03-008","chapter":"l03","topic":"Pilot lifecycle & prioritisation","type":"mcq","q":"Which loop is drawn inside the Iterate step of the pilot lifecycle?","options":["Plan → Do → Check","Ideate → Prioritize → Design","Build → Test → Refine","Train → Validate → Deploy"],"answer":2,"fixed":false,"why":"Slide 7 shows a circular Build → Test → Refine arrow above 'Iterate'. Ideate/Prioritize/Design are earlier steps of the pilot, not the inner loop.","source":"L03 slide 7","study":"lectures/L03-genai-in-the-enterprise.md — 3. ★ The GenAI pilot lifecycle (slide 7)","origin":"practice"},{"id":"l03-009","chapter":"l03","topic":"Pilot lifecycle & prioritisation","type":"mcq","q":"In the slide-7 pilot lifecycle, which step comes immediately before the 'Invest in pilot?' gate?","options":["Generate ideas","Design","Roadmap","Formalize pilot team"],"answer":3,"fixed":false,"why":"The order is Generate Ideas → Prioritize Use Cases → Formalize Pilot Team → [Invest in Pilot?] → Design → Iterate → [Stop or Scale?] → Roadmap. Design comes after the gate.","source":"L03 slide 7","study":"lectures/L03-genai-in-the-enterprise.md — 3. ★ The GenAI pilot lifecycle (slide 7)","origin":"practice"},{"id":"l03-010","chapter":"l03","topic":"Pilot lifecycle & prioritisation","type":"mcq","q":"The 'Gen AI Pilot' cycle on slide 6 has five numbered steps. Which is step 3?","options":["Build team","Prioritize","Design","Iterate"],"answer":0,"fixed":false,"why":"Slide 6: 1 Ideate → 2 Prioritize → 3 Build Team → 4 Design → 5 Iterate. Step 3 builds a dedicated team of business partners, software developers and AI experts.","source":"L03 slide 6","study":"lectures/L03-genai-in-the-enterprise.md — 3. ★ The GenAI pilot lifecycle (slide 7)","origin":"practice"},{"id":"l03-011","chapter":"l03","topic":"Pilot lifecycle & prioritisation","type":"yn","q":"Does the slide-6 pilot cycle advise prioritising as many GenAI use cases as possible?","options":["Yes","No"],"answer":1,"fixed":false,"why":"Step 2 says 'Prioritize no more than a few Gen AI use cases, building a small portfolio that balances value and feasibility'. Generating many ideas is step 1; prioritising narrows them.","source":"L03 slide 6","study":"lectures/L03-genai-in-the-enterprise.md — 3. ★ The GenAI pilot lifecycle (slide 7)","origin":"practice"},{"id":"l03-012","chapter":"l03","topic":"Pilot lifecycle & prioritisation","type":"mcq","q":"In the Gartner value–feasibility matrix (slide 8), where does a use case with high value but low feasibility fall?","options":["Likely Wins","Calculated Risks","Marginal Gains","Quick Wins"],"answer":1,"fixed":false,"why":"Value is the vertical axis, feasibility the horizontal. Top-left (high value, low feasibility) is Calculated Risks; top-right is Likely Wins; the low-value band is Marginal Gains. 'Quick Wins' is not on the slide.","source":"L03 slide 8","study":"lectures/L03-genai-in-the-enterprise.md — 3. ★ The GenAI pilot lifecycle (slide 7)","origin":"practice"},{"id":"l03-013","chapter":"l03","topic":"Use-case lifecycle","type":"mcq","q":"In the six-step use-case lifecycle (slide 5), in which step do legal compliance and the DPO appear?","options":["Business need (step 1)","Testing & evaluation (step 4)","Preliminary screening (step 2)","Monitoring & improvement (step 6)"],"answer":2,"fixed":false,"why":"Step 2 'Preliminary screening' lists legal compliance and DPO, security, technical feasibility, grounding and a reliable knowledge source — compliance is a gate before development, not a review after it.","source":"L03 slide 5","study":"lectures/L03-genai-in-the-enterprise.md — 4. ★ The six-step use-case lifecycle (slide 5)","origin":"practice"},{"id":"l03-014","chapter":"l03","topic":"Use-case lifecycle","type":"mcq","q":"In which use-case lifecycle step are hallucinations and misinterpretations checked?","options":["Preliminary screening","Production readiness","Controlled development","Testing & evaluation"],"answer":3,"fixed":false,"why":"Step 4 'Testing & evaluation': test scenarios; accuracy, completeness and clarity; hallucinations and misinterpretations. Preliminary screening handles grounding, which reduces hallucination but does not test for it.","source":"L03 slide 5","study":"lectures/L03-genai-in-the-enterprise.md — 4. ★ The six-step use-case lifecycle (slide 5)","origin":"practice"},{"id":"l03-015","chapter":"l03","topic":"Use-case lifecycle","type":"yn","q":"Is 'cost and quality optimization' listed under production readiness (step 5) of the use-case lifecycle?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Step 5 'Production readiness': optimal architecture; cost and quality optimization; confirmed readiness for production. Do not confuse it with the pillar item 'model costs and optimization' (slide 4).","source":"L03 slide 5","study":"lectures/L03-genai-in-the-enterprise.md — 4. ★ The six-step use-case lifecycle (slide 5)","origin":"practice"},{"id":"l03-016","chapter":"l03","topic":"Use-case lifecycle","type":"mcq","q":"Which of these is NOT one of the six steps of the use-case lifecycle?","options":["Controlled development","Foundation model pre-training","Production readiness","Monitoring & improvement"],"answer":1,"fixed":false,"why":"The six steps are business need, preliminary screening, controlled development, testing & evaluation, production readiness, monitoring & improvement. Controlled development selects a platform and model; it does not pre-train one.","source":"L03 slide 5","study":"lectures/L03-genai-in-the-enterprise.md — 4. ★ The six-step use-case lifecycle (slide 5)","origin":"practice"},{"id":"l03-017","chapter":"l03","topic":"Six pillars & principles","type":"mcq","q":"Which of these is NOT one of the six pillars of BH Telecom's strategic introduction of GenAI (slide 4)?","options":["Organization","Bottom-up use cases","Vendor partnerships","QA & monitoring"],"answer":2,"fixed":false,"why":"The six pillars are Organization, Methodology, Bottom-up use cases, Security & regulation, QA & monitoring, Impact & consumption. Vendor partnerships is not one of them.","source":"L03 slide 4","study":"lectures/L03-genai-in-the-enterprise.md — 5. ★ The six pillars of strategic introduction (slide 4)","origin":"practice"},{"id":"l03-018","chapter":"l03","topic":"Six pillars & principles","type":"mcq","q":"Which of these is one of the three technology principles on slide 4?","options":["LLM orchestration and tiered routing","One central model serving every task","Fully autonomous agents with no human approval","On-premise training of foundation models"],"answer":0,"fixed":false,"why":"The three principles are: multimodal and multi-agent; LLM orchestration and tiered routing; human approval and human-in-the-loop. 'No human approval' contradicts the third.","source":"L03 slide 4","study":"lectures/L03-genai-in-the-enterprise.md — 5. ★ The six pillars of strategic introduction (slide 4)","origin":"practice"},{"id":"l03-019","chapter":"l03","topic":"Six pillars & principles","type":"mcq","q":"Under which pillar does 'model costs and optimization' appear?","options":["Security & regulation","Methodology","Organization","Impact & consumption"],"answer":3,"fixed":false,"why":"Impact & consumption: business value measurement; licences and access rights; model costs and optimization. Security & regulation covers compliance checkpoints, data classification and secure, ethical use.","source":"L03 slide 4","study":"lectures/L03-genai-in-the-enterprise.md — 5. ★ The six pillars of strategic introduction (slide 4)","origin":"practice"},{"id":"l03-020","chapter":"l03","topic":"Six pillars & principles","type":"yn","q":"Is 'governance and decision gates' listed under the Methodology pillar?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Methodology: adaptive GenAI strategy; use-case lifecycle; governance and decision gates. Organization is about teams (GenAI team, assistant development team, use-case teams).","source":"L03 slide 4","study":"lectures/L03-genai-in-the-enterprise.md — 5. ★ The six pillars of strategic introduction (slide 4)","origin":"practice"},{"id":"l03-021","chapter":"l03","topic":"Assistant levels & BHT results","type":"mcq","q":"A level-2 low-code assistant that actually carries out tasks in company systems is called a…","options":["Q&A assistant","Flow assistant","Action agent","Ready-made solution"],"answer":2,"fixed":false,"why":"Level 2 has Q&A assistants (knowledge-based), flow assistants (process guidance) and action agents (execution of actions). A flow assistant guides a process but does not execute it.","source":"L03 slide 9","study":"lectures/L03-genai-in-the-enterprise.md — 6. ★ Three levels of assistant, and the BH Telecom results (slide 9)","origin":"practice"},{"id":"l03-022","chapter":"l03","topic":"Assistant levels & BHT results","type":"mcq","q":"Integrations with internal systems and data, and specialised multimodal AI chatbots, belong to which assistant level?","options":["Level 1 — ready-made solutions","Level 3 — full-code assistants","Level 2 — low-code assistants","Level 0 — consumer chat apps"],"answer":1,"fixed":false,"why":"Slide 9, level 3 (full-code): advanced AI assistants, integrations with internal systems and data, specialised multimodal chatbots. Level 1 is office productivity, custom assistants and software-development support; there is no level 0.","source":"L03 slide 9","study":"lectures/L03-genai-in-the-enterprise.md — 6. ★ Three levels of assistant, and the BH Telecom results (slide 9)","origin":"practice"},{"id":"l03-023","chapter":"l03","topic":"Assistant levels & BHT results","type":"mcq","q":"According to the slide-9 results, how many assistants does BH Telecom have in production or development?","options":["2","24","100","1000"],"answer":1,"fixed":true,"why":"Results: 1000+ employees use GenAI, 2 teams dedicated to the AI transformation, 24 assistants in production/development. 2 is the number of teams and 1000 the employees.","source":"L03 slide 9","study":"lectures/L03-genai-in-the-enterprise.md — 6. ★ Three levels of assistant, and the BH Telecom results (slide 9)","origin":"practice"},{"id":"l03-024","chapter":"l03","topic":"Assistant levels & BHT results","type":"yn","q":"According to the 'decentralized adoption' statement, is AI transformation at BH Telecom delivered only centrally?","options":["Yes","No"],"answer":1,"fixed":false,"why":"'AI transformation is not delivered only centrally. It scales through trained employees who independently develop and improve business assistants.' Level-2 low-code tools are what make that possible.","source":"L03 slide 9","study":"lectures/L03-genai-in-the-enterprise.md — 6. ★ Three levels of assistant, and the BH Telecom results (slide 9)","origin":"practice"},{"id":"l03-025","chapter":"l03","topic":"RAG & Copilot flow","type":"mcq","q":"In the complete RAG flow (slide 13), what is put into the prompt together with the user's question?","options":["The embedding vectors of the relevant sections","The entire document library","The fine-tuned model weights","The text of the N most relevant document sections"],"answer":3,"fixed":false,"why":"Azure AI Search returns N relevant sections, and their section text plus the user question form the prompt for gpt-4o. The embeddings are only the search key; the LLM reads text.","source":"L03 slide 13","study":"lectures/L03-genai-in-the-enterprise.md — 7. The RAG flow (slide 13)","origin":"practice"},{"id":"l03-026","chapter":"l03","topic":"RAG & Copilot flow","type":"yn","q":"In the slide-13 RAG flow, is the user's question embedded with the same model (text-embedding-3-large) that embedded the document sections?","options":["Yes","No"],"answer":0,"fixed":false,"why":"Both the document sections and the question go through text-embedding-3-large. They must share one vector space, otherwise the vector-index similarity search is meaningless.","source":"L03 slide 13","study":"lectures/L03-genai-in-the-enterprise.md — 7. The RAG flow (slide 13)","origin":"practice"},{"id":"l03-027","chapter":"l03","topic":"RAG & Copilot flow","type":"mcq","q":"In the slide-13 RAG flow, which component generates the final answer?","options":["gpt-4o (Azure OpenAI Service)","text-embedding-3-large","Azure AI Search vector index","The document chunking process"],"answer":0,"fixed":false,"why":"The prompt (relevant sections + question) is sent to Azure OpenAI gpt-4o, which performs the NLP task (summarisation, Q&A). text-embedding-3-large only produces vectors; the vector index only retrieves.","source":"L03 slide 13","study":"lectures/L03-genai-in-the-enterprise.md — 7. The RAG flow (slide 13)","origin":"practice"},{"id":"l03-028","chapter":"l03","topic":"RAG & Copilot flow","type":"mcq","q":"In the Microsoft Copilot architecture (slide 12), what happens before the modified prompt is sent to the LLM?","options":["Post-processing: a Compliance and Purview check","Pre-processing: Copilot grounds the prompt using Microsoft Graph (plus optional web/other services)","The LLM is fine-tuned on the user's emails","A human approves every prompt"],"answer":1,"fixed":false,"why":"Data flow: 1 prompt to Copilot → 2 grounding via Graph (pre-processing) → 3 modified prompt to LLM → 4 LLM response → 5 Compliance and Purview (post-processing) → 6 response to user. Compliance comes after the LLM.","source":"L03 slide 12","study":"lectures/L03-genai-in-the-enterprise.md — 7. The RAG flow (slide 13)","origin":"practice"},{"id":"l03-029","chapter":"l03","topic":"Platforms & business case","type":"mcq","q":"In the slide-10 platform matrix, which vendor has no offering listed for image and video recognition?","options":["IBM","Google","OpenAI","Amazon AWS"],"answer":2,"fixed":false,"why":"OpenAI's row shows '-' for enterprise operations automation, voice assistants and image/video recognition. IBM has Watson Visual Recognition, Google has Cloud Vision AI, AWS has Rekognition.","source":"L03 slide 10","study":"lectures/L03-genai-in-the-enterprise.md — 8. Platform landscape (slide 10)","origin":"practice"},{"id":"l03-030","chapter":"l03","topic":"Platforms & business case","type":"mcq","q":"The slide-15 business case for a knowledge-worker productivity use case gives a low-end value of $7,488 per user per year and $7,488,000 per year for all users. How many users does it assume?","options":["100","1,000","7,488","10,000"],"answer":1,"fixed":true,"why":"$7,488,000 ÷ $7,488 per user = 1,000 users; the high end agrees ($15,463 × 1,000 ≈ $15,462,720). 7,488 confuses the per-user value with a head count.","source":"L03 slide 15","study":"lectures/L03-genai-in-the-enterprise.md — 8. Platform landscape (slide 10)","origin":"practice"}]};
